#!/bin/sh
# geomask.sh - geo-masking overlay + 2-subscription mihomo stack for OpenWrt
# Workflow: check -> geo overlay -> mihomo 2 subs -> AI-DNS (no DNS leak) -> magitrickle sync -> services -> verify
#
# Usage:
#   sh geomask.sh              interactive menu (status dashboard + actions loop)
#   sh geomask.sh --reinstall  delete -> install -> configure geomask (asks for 2 subscription URLs)
#   sh geomask.sh --backup     create a full settings backup (LuCI-restorable) and exit
#   sh geomask.sh --auto       all steps unattended: check, apply if needed, verify; stop on FAIL
#   sh geomask.sh --check      read-only report of every step (no changes, no downloads)
#   sh geomask.sh --step N     single step N interactively
#   sh geomask.sh --yes        never ask (with --auto/--step/--reinstall)
#   sh geomask.sh --restart    allow mihomo/magitrickle restarts where needed (drops VPN ~3s)
#   sh geomask.sh --vpn-url U --ai-url U    set subscription URLs (kept secret in config only)
#   sh geomask.sh --seed-lists  restore MagiTrickle domain lists from the bundled template (all groups)
#   sh geomask.sh --list-modules   what is mandatory and what is optional
#   sh geomask.sh --modules=core,path_vpn   install only the modules this router needs
#   sh geomask.sh --adopt-config  take an existing (non-geomask) mihomo config under management
#   sh geomask.sh --replace-config  rewrite an existing config with the template (drops tun/dns/secret)
#   sh geomask.sh --help
#
# Install (jsDelivr CDN - fast, shows download progress):
#   curl -fL -m 60 -o /tmp/geomask.sh 'https://cdn.jsdelivr.net/gh/kabzon93region/geomask@master/geomask.sh' && sh /tmp/geomask.sh
# wget fallback:
#   wget -T 30 -O /tmp/geomask.sh 'https://cdn.jsdelivr.net/gh/kabzon93region/geomask@master/geomask.sh' && sh /tmp/geomask.sh
# GitHub raw (can be VERY slow from some networks -> looks like a hang; prefer jsDelivr):
#   sh <(wget -qO - 'https://raw.githubusercontent.com/kabzon93region/geomask/master/geomask.sh')
#
# SAFETY: never reboots the router; never restarts working services (only starts missing ones);
#         never touches network/pppoe config; backups before every file write and before ANY
#         mihomo restart (full settings backup via sysupgrade -b -> /root/geomask-backups/,
#         built in /tmp then moved, freshest one kept, published read-only over SMB as
#         'geomask-backups' with links in the panel - v1.9.0),
#         mihomo restart = trial-run on shifted ports FIRST, restart only if the trial starts,
#         and automatic rollback to the previous config if the restarted service does not
#         answer. Hard pin: /root/.geomask-norestart disables --restart entirely.

set -u

GM_VERSION="1.31.0"
GM_PREFIX="${GM_PREFIX:-}"          # path prefix for tests (empty on real router)
GM_YES=0
GM_AUTO=0
GM_CHECK_ONLY=0
GM_RESTART=0
GM_BACKUP=0
GM_REINSTALL=0
GM_SEED_LISTS=0
GM_ADOPT=0
GM_REPLACE=0
GM_STEP=""
GM_VPN_URL=""
GM_AI_URL=""
# IPv6 is OFF by default (owner decision 14.11.2026): geomask tunnels IPv4 only, so a global
# IPv6 address leaves for the WAN directly and shows the real address and country.
# `--ipv6=keep` is the only way to keep IPv6 on the router.
GM_IPV6=off

# ---- paths shared by the backup, SMB and module code (used before their sections) ----
BACKUP_DIR=/root/geomask-backups
SMB_SHARE_NAME=geomask-backups
SMB_SHARE_ENABLE=/etc/geomask/backup-share.enable

# ---- embedded assets are injected by build.py into the heredocs below ----

PASS=0; FAILCNT=0; SKIP=0
# Counts failed writes so an apply step can refuse to report success. A heredoc call cannot
# carry `|| ...` without breaking the build-time asset parser, so save_stream records it.
SAVE_FAIL=0

log()  { printf '%s\n' "$*"; }
info() { printf '  %s\n' "$*"; }
ok()   { printf '  [OK] %s\n' "$*"; PASS=$((PASS+1)); }
bad()  { printf '  [FAIL] %s\n' "$*"; FAILCNT=$((FAILCNT+1)); }
warn() { printf '  [WARN] %s\n' "$*"; }
hdr()  { printf '\n== [%s] %s ==\n' "$1" "$2"; }

ask() { # ask "question" -> 0=yes  (auto/yes modes never block)
  [ "$GM_YES" = 1 ] && return 0
  [ "$GM_AUTO" = 1 ] && return 0
  printf '%s [y/N]: ' "$1"
  read -r _a || return 1
  case "$_a" in y|Y|yes|YES) return 0 ;; *) return 1 ;; esac
}

P() { printf '%s%s' "$GM_PREFIX" "$1"; }

# ---- discovered names: nothing below may assume br-lan / pppoe-wan / 192.168.0.x ----
LAN_IF_CACHE=""
lan_iface() {
  [ -n "$LAN_IF_CACHE" ] && { printf '%s' "$LAN_IF_CACHE"; return 0; }
  _i=$(uci -q get network.lan.device 2>/dev/null)
  [ -n "$_i" ] || _i=$(uci -q get network.lan.ifname 2>/dev/null)
  case "$_i" in ''|*[!a-zA-Z0-9._-]*) _i="" ;; esac
  [ -n "$_i" ] || _i=br-lan
  LAN_IF_CACHE="$_i"
  printf '%s' "$_i"
}

lan_ip() {
  ip -4 addr show "$(lan_iface)" 2>/dev/null \
    | sed -n 's/.*inet \([0-9][0-9.]*\)\/.*/\1/p' | head -1
}

wan_iface() {
  # The device that actually carries the default route, not the uci interface name: on PPPoE
  # the uci name is `wan` while traffic leaves through `pppoe-wan`, and every consumer here
  # (MagiTrickle group interface, curl --interface) needs the device.
  #
  # netifd is asked first because it knows the L3 device; the routing table is only a
  # fallback, and the OLD fallback picked the first default - which on a policy-routed box is
  # the tunnel - then silently returned `pppoe-wan` when nothing matched (audit F17).
  _i=""
  if have ubus; then
    _i=$(ubus call network.interface.wan status 2>/dev/null \
         | sed -n 's/.*"l3_device"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -1)
    case "$_i" in ''|*[!a-zA-Z0-9._-]*) _i="" ;; esac
  fi
  _tun=$(mihomo_tun)
  if [ -z "$_i" ]; then
    for _cand in $(ip route show default 2>/dev/null | sed -n 's/.*dev \([a-zA-Z0-9._-]*\).*/\1/p'); do
      case "$_cand" in
        "$_tun"|Mihomo|AI|wg*|tun*|tap*) continue ;;
      esac
      _i=$_cand; break
    done
  fi
  if [ -z "$_i" ]; then
    for _k in network.wan.device network.wan.ifname network.wan6.device; do
      _cand=$(uci -q get "$_k" 2>/dev/null)
      case "$_cand" in ''|*[!a-zA-Z0-9._-]*) continue ;; esac
      # `wan` is the interface name, not a device: accept only something that exists
      ip link show "$_cand" >/dev/null 2>&1 && { _i=$_cand; break; }
    done
  fi
  # No guess: an empty answer means "unknown", and callers must not configure a direct lane
  # on an interface nobody verified.
  printf '%s' "$_i"
}

mihomo_tun() { # the TUN device mihomo is configured to create
  _d=$(awk '/^tun:/{f=1;next} f&&/^[^ ]/{exit} f&&/^[[:space:]]*device:/{gsub(/^[[:space:]]*device:[[:space:]]*/,"");print;exit}' \
       "$(P /etc/mihomo/config.yaml)" 2>/dev/null)
  case "$_d" in ''|*[!a-zA-Z0-9._-]*) _d=Mihomo ;; esac
  printf '%s' "$_d"
}

# Address for the second (AI) dnsmasq. An explicit override wins; otherwise .53 inside the
# real LAN subnet, and only when that is a usable, unoccupied host address. The old version
# always replaced the last octet with 53: on a /25 that address is outside the LAN, and on a
# router whose own address ends in .53 the alias "already existed" while the DNAT pointed at
# the router itself. When no safe address can be chosen the caller must refuse to configure
# AI-DNS instead of sending devices to a DNS that does not answer.
_aidns_usable() { # _aidns_usable <candidate> <lan-ip> <prefix>
  awk -v ip="$1" -v lan="$2" -v p="$3" 'BEGIN{
    n=split(ip,A,"."); m=split(lan,B,".");
    if (n != 4 || m != 4) exit 1;
    for (i=1; i<=4; i++) { if (A[i] !~ /^[0-9]+$/ || A[i] < 0 || A[i] > 255) exit 1 }
    for (i=1; i<=4; i++) { if (B[i] !~ /^[0-9]+$/ || B[i] < 0 || B[i] > 255) exit 1 }
    ipn=((A[1]*256+A[2])*256+A[3])*256+A[4];
    lann=((B[1]*256+B[2])*256+B[3])*256+B[4];
    size=2^(32-p);
    net=int(lann/size)*size;
    if (ipn < net+1 || ipn > net+size-2) exit 1;   # network/broadcast are not hosts
    if (ipn == lann) exit 1;                        # the router itself
    exit 0
  }'
}

_prefix_to_mask() { # _prefix_to_mask <prefix> -> dotted netmask
  awk -v p="$1" 'BEGIN{
    v=0; for (i=0; i<p; i++) v+=2^(31-i);
    printf "%d.%d.%d.%d", int(v/16777216)%256, int(v/65536)%256, int(v/256)%256, v%256
  }'
}

# 0 when <ip> is already in use by something other than our own alias on <iface>.
# Absence of a neighbour entry does not prove the address is free; it only rules out a host
# that answered recently, so the caller still refuses when the answer is ambiguous.
_aidns_taken() { # _aidns_taken <ip> <iface>
  _at="$1"
  ip -4 addr show "$2" 2>/dev/null | grep -q " $_at/" && return 1   # our own alias
  ip -4 addr show 2>/dev/null | grep -q " $_at/" && return 0
  ip neigh show "$_at" 2>/dev/null | grep -q 'lladdr' && return 0
  return 1
}

aidns_ip() {
  _ip=$(lan_ip)
  case "$_ip" in *.*.*.*) ;; *) printf ''; return 0 ;; esac
  _if=$(lan_iface)
  _pfx=$(ip -4 addr show "$_if" 2>/dev/null | sed -n 's/.*inet [0-9.]*\/\([0-9][0-9]*\).*/\1/p' | head -1)
  case "$_pfx" in ''|*[!0-9]*) _pfx=24 ;; esac
  [ "$_pfx" -ge 1 ] 2>/dev/null || _pfx=24
  [ "$_pfx" -le 30 ] 2>/dev/null || { printf ''; return 0; }
  # An explicit override is still an address on THIS LAN. The old code returned any four
  # dot-separated pieces without a single check, so 999.1.1.1 or the router's own address
  # became the DNAT target and the alias was written to uci (audit 14.11.2026, F11).
  _ov=$(tr -d ' \r\n' < "$(P /etc/geomask-aidns.ip)" 2>/dev/null)
  if [ -n "$_ov" ]; then
    if ! _aidns_usable "$_ov" "$_ip" "$_pfx"; then
      printf '  [WARN] AI-DNS: адрес из /etc/geomask-aidns.ip (%s) не подходит для %s/%s - AI-DNS не настраивается\n' "$_ov" "$_ip" "$_pfx" >&2
      printf ''; return 0
    fi
    if _aidns_taken "$_ov" "$_if"; then
      printf '  [WARN] AI-DNS: адрес %s из /etc/geomask-aidns.ip уже занят - AI-DNS не настраивается\n' "$_ov" >&2
      printf ''; return 0
    fi
    printf '%s' "$_ov"; return 0
  fi
  # An alias this installer created earlier is not a conflict: keep it on re-runs.
  _cur=$(uci -q get network.lanai.ipaddr 2>/dev/null)
  case "$_cur" in
    *.*.*.*)
      if _aidns_usable "$_cur" "$_ip" "$_pfx" && ! _aidns_taken "$_cur" "$_if"; then
        printf '%s' "$_cur"; return 0
      fi
      ;;
  esac
  _cand=$(printf '%s' "$_ip" | cut -d. -f1-3).53
  _aidns_usable "$_cand" "$_ip" "$_pfx" || { printf ''; return 0; }
  # Already assigned to another interface, or a neighbour answers for it: a collision, not a
  # free address. Both checks are cheap and prevent pointing DNS at someone else's host.
  _aidns_taken "$_cand" "$_if" && { printf ''; return 0; }
  printf '%s' "$_cand"
}

# Keep authentication out of curl argv and diagnostics; read the active config on each call.
controller_curl() {
  python3 - "$(P /etc/mihomo/config.yaml)" "$@" <<'GM_CONTROLLER_PY'
import json, re, subprocess, sys

def controller_headers(path):
    with open(path, encoding='utf-8') as config:
        for line in config:
            match = re.match(r'^secret:\s*(.*)$', line.rstrip('\r\n'))
            if not match:
                continue
            value = match.group(1).strip()
            if value.startswith('"'):
                value, end = json.JSONDecoder().raw_decode(value)
                tail = match.group(1).strip()[end:].strip()
                if tail and not tail.startswith('#'):
                    raise ValueError('Invalid controller secret')
            elif value.startswith("'"):
                quoted = re.fullmatch(r"'((?:[^']|'')*)'\s*(?:#.*)?", value)
                if not quoted:
                    raise ValueError('Invalid controller secret')
                value = quoted.group(1).replace("''", "'")
            else:
                value = re.split(r'\s+#', value, maxsplit=1)[0].strip()
                if value.startswith('#'):
                    value = ''
                if value.startswith(('|', '>', '[', '{', '&', '*', '!')):
                    raise ValueError('Unsupported controller secret')
            if not isinstance(value, str) or any(ord(c) < 32 or ord(c) == 127 for c in value):
                raise ValueError('Invalid controller secret')
            return {'Authorization': 'Bearer ' + value} if value else {}
    return {}

try:
    headers = controller_headers(sys.argv[1])
    options = ''.join('header = ' + json.dumps(k + ': ' + v, ensure_ascii=False) + '\n'
                      for k, v in headers.items())
    result = subprocess.run(['curl', '--config', '-', *sys.argv[2:]],
                            input=options.encode('utf-8'))
    sys.exit(result.returncode)
except Exception:
    print('Controller request failed (configuration or transport error)', file=sys.stderr)
    sys.exit(1)
GM_CONTROLLER_PY
}

# ---- mihomo config: ownership, validation, provider discovery -----------------
# A config that already carries geomask's layout (provider + the two groups it manages) can
# be patched in place. Anything else belongs to the owner: it is never overwritten silently,
# because a rewrite drops tun/dns/secret and every custom rule with it.
#
# Ownership is a STRUCTURAL question. The previous version grepped for a line `  sub:` and
# for two `- name:` lines anywhere in the file, so a foreign YAML with `proxy-providers.own`
# and a `rule-providers.sub` was taken over, and --vpn-url then rewrote the rule-provider's
# URL instead of a proxy-provider (audit 14.11.2026, F06). Without a YAML parser the answer
# is "not ours": refusing is the safe direction.
# The router always has python3. A test host may expose only `python`, or a broken `python3`
# alias that `command -v` still finds - so the interpreter is probed, not assumed.
_mihomo_py() {
  # `-` makes the interpreter read the program from stdin and pass the rest as sys.argv.
  if [ -n "${GM_PYTHON:-}" ]; then "$GM_PYTHON" - "$@" 2>/dev/null; return; fi
  if python3 -c 'pass' >/dev/null 2>&1; then python3 - "$@" 2>/dev/null
  else python - "$@" 2>/dev/null; fi
}

# Run an INSTALLED python asset (a file, not a program on stdin). Same interpreter probe as
# above so a host with only `python` still works; stderr is left to the caller.
_gm_py_script() { # _gm_py_script <script> [args...]
  if [ -n "${GM_PYTHON:-}" ]; then "$GM_PYTHON" "$@"; return; fi
  if python3 -c 'pass' >/dev/null 2>&1; then python3 "$@"; else python "$@"; fi
}

# PyYAML is what decides ownership of the mihomo config; ask the same interpreter the parser
# would use, not a hard-coded `python3`.
_py_yaml_ok() {
  if [ -n "${GM_PYTHON:-}" ]; then "$GM_PYTHON" -c 'import yaml' >/dev/null 2>&1; return; fi
  python3 -c 'import yaml' >/dev/null 2>&1 && return 0
  python -c 'import yaml' >/dev/null 2>&1
}

geomask_config_verdict() { # geomask_config_verdict <file> -> 0 ours, 1 foreign, 2 cannot judge
  # N04 (audit 18.11.2026): "cannot parse" used to mean "foreign", so a missing PyYAML turned a
  # geomask config into somebody else's and the operator was offered --replace-config on it.
  # The verdict is tri-state now: only a readable, parsed, non-shaped file is foreign.
  _f="$1"
  [ -s "$_f" ] || return 1
  grep -qxF '# geomask-managed: 1' "$_f" 2>/dev/null && return 0
  _mihomo_py "$_f" <<'PYEOF'
import sys
try:
    import yaml
except Exception:
    raise SystemExit(2)
try:
    with open(sys.argv[1], encoding='utf-8') as fh:
        data = yaml.safe_load(fh)
except Exception:
    raise SystemExit(2)
if not isinstance(data, dict):
    raise SystemExit(1)
providers = data.get('proxy-providers')
groups = data.get('proxy-groups')
if not isinstance(providers, dict) or 'sub' not in providers:
    raise SystemExit(1)
if not isinstance(groups, list):
    raise SystemExit(1)
names = {g.get('name') for g in groups if isinstance(g, dict)}
raise SystemExit(0 if {'VPN-noP2P', 'AI'} <= names else 1)
PYEOF
}

# Backwards-compatible predicate: "is this file ours?". Callers that must distinguish
# "foreign" from "cannot judge" use geomask_config_verdict directly (N04).
geomask_config_shaped() { # geomask_config_shaped <file> -> 0 only when the file is ours
  geomask_config_verdict "$1"
  _gcs=$?
  [ "$_gcs" = 0 ]
}

# One ownership decision for every writer that is about to touch the live mihomo config.
# --replace-config is the owner's explicit consent; --adopt-config means "merge, keep mine".
# Everything else refuses, and an unreadable file is refused with its own reason: it is NOT
# "somebody else's config" and must never be offered for replacement.
_mihomo_guard() { # _mihomo_guard <file> <where> -> 0 may proceed, 1 refuse
  [ -s "$1" ] || return 0
  [ "${GM_REPLACE:-0}" = 1 ] && return 0
  geomask_config_verdict "$1"
  _mg_rc=$?
  case "$_mg_rc" in
    0) return 0 ;;
    2)
      bad "$2: конфиг mihomo не читается (нет python3-yaml или файл повреждён) - владение не определить"
      info "  Ничего не изменено. Установите python3 python3-yaml и повторите."
      return 1 ;;
  esac
  [ "${GM_ADOPT:-0}" = 1 ] && return 0
  bad "$2: на роутере свой конфиг mihomo - шаблон поверх него не пишется"
  info "  Взять его под управление без потери настроек: --adopt-config"
  info "  Полная замена шаблоном (tun/dns/secret и ваши правила будут потеряны): --replace-config"
  return 1
}

_mihomo_has_provider() { # _mihomo_has_provider <file> <provider> -> 0 when it exists
  _mihomo_py "$1" "$2" <<'PYEOF'
import sys
try:
    import yaml
except Exception:
    raise SystemExit(1)
try:
    with open(sys.argv[1], encoding='utf-8') as fh:
        data = yaml.safe_load(fh)
except Exception:
    raise SystemExit(1)
providers = data.get('proxy-providers') if isinstance(data, dict) else None
raise SystemExit(0 if isinstance(providers, dict) and sys.argv[2] in providers else 1)
PYEOF
}

any_provider_url() { # first http provider url in the config (any provider name)
  _mihomo_py "$1" <<'PYEOF'
import sys
try:
    import yaml
except Exception:
    raise SystemExit(1)
try:
    with open(sys.argv[1], encoding='utf-8') as fh:
        data = yaml.safe_load(fh)
except Exception:
    raise SystemExit(1)
providers = data.get('proxy-providers') if isinstance(data, dict) else None
if not isinstance(providers, dict):
    raise SystemExit(0)
for entry in providers.values():
    url = entry.get('url') if isinstance(entry, dict) else None
    if isinstance(url, str) and url.strip():
        print(url.strip())
        break
PYEOF
}

mihomo_validate() { # mihomo_validate <config-file>  - the CANDIDATE, never the live file
  [ -s "$1" ] || return 1
  mihomo -d "$(P /etc/mihomo)" -f "$1" -t >/dev/null 2>&1
}

# extract provider url from mihomo config: _prov_url <file> <provider-name>
_prov_url() {
  _mihomo_py "$1" "$2" <<'PYEOF'
import sys
try:
    import yaml
except Exception:
    raise SystemExit(1)
try:
    with open(sys.argv[1], encoding='utf-8') as fh:
        data = yaml.safe_load(fh)
except Exception:
    raise SystemExit(1)
providers = data.get('proxy-providers') if isinstance(data, dict) else None
entry = providers.get(sys.argv[2]) if isinstance(providers, dict) else None
url = entry.get('url') if isinstance(entry, dict) else None
if isinstance(url, str) and url.strip():
    print(url.strip())
PYEOF
}

# ---- modules: which parts of geomask get installed -------------------------
# core and path_vpn are mandatory: without the core nothing runs, without the VPN
# lane the product has no purpose. Everything else is optional and can be left out
# with --modules=... so a router only carries the features its owner wants.
GM_REQUIRED_MODULES="core path_vpn"
GM_ALL_MODULES="core luci guard path_vpn path_vpn_nop2p path_ai ai_dns youtube torrent diagnostic doctor device_modes backup_share self_update admission_service"
GM_MODULES=""

module_required() { case " $GM_REQUIRED_MODULES " in *" $1 "*) return 0 ;; esac; return 1; }
module_selected() {
  [ -z "$GM_MODULES" ] && return 0
  case " $GM_MODULES " in *" $1 "*) return 0 ;; esac
  return 1
}
module_label() {
  case "$1" in
    core) echo "geomask (ядро): синк, node-audit, лейн, списки" ;;
    luci) echo "Админка LuCI: панель, бэкенд, RPC" ;;
    guard) echo "geomask-guard: сторож маршрута после ifup" ;;
    path_vpn) echo "VPN-лейн (основной туннель)" ;;
    path_vpn_nop2p) echo "VPN-noP2P (без торрентов)" ;;
    path_ai) echo "AI-лейн (Google/OpenAI/Claude)" ;;
    ai_dns) echo "DNS-over-HTTPS для AI-устройств" ;;
    youtube) echo "YouTube: watchdog и списки доменов" ;;
    torrent) echo "Торренты: правила и слушатель" ;;
    diagnostic) echo "Старые проверки: dnscheck, vpnwatch, утренняя проверка" ;;
    doctor) echo "Центр диагностики: проверки, маршруты, логи" ;;
    device_modes) echo "Режимы устройств (исключения из туннеля)" ;;
    backup_share) echo "SMB-шар с бэкапами" ;;
    self_update) echo "Самообновление из GitHub" ;;
    admission_service) echo "Служба допуска AI-устройств" ;;
    *) echo "" ;;
  esac
}
module_owns_path() { # echoes the module id that owns an install path, if any
  GM_PATH_MODULE=""
  case "$1" in
    "/etc/init.d/ai-doh") GM_PATH_MODULE="ai_dns" ;;
    "/etc/init.d/dnsmasq-ai") GM_PATH_MODULE="ai_dns" ;;
    "/etc/geomask-nodes.conf") GM_PATH_MODULE="core" ;;
    "/etc/geomask/lists/magitrickle-groups.yaml") GM_PATH_MODULE="core" ;;
    "/etc/geomask/zapret-always-exclude.txt") GM_PATH_MODULE="core" ;;
    "/etc/geomask/zapret-force-keep.txt") GM_PATH_MODULE="core" ;;
    "/etc/hotplug.d/iface/99-default-vpn-route") GM_PATH_MODULE="core" ;;
    "/etc/init.d/geomask-syncd") GM_PATH_MODULE="core" ;;
    "/root/sync_mtrickle_mihomo.sh") GM_PATH_MODULE="core" ;;
    "/usr/bin/geo-backend.sh") GM_PATH_MODULE="core" ;;
    "/usr/bin/geomask-lane.sh") GM_PATH_MODULE="core" ;;
    "/usr/bin/geomask-node-scan.sh") GM_PATH_MODULE="core" ;;
    "/usr/bin/geomask-seed-lists.py") GM_PATH_MODULE="core" ;;
    "/usr/bin/geomask-syncd.sh") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/99-default-vpn-route.dist") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-apply.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-audit-scheduler.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-audit-state.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-config-owner.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-config-tx.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-console.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-diag-redact.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-diag-spool.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-dnsguard.sh") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-lane-torrent.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-lists-edit.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-lock.sh") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-mihomo-adopt.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-node-audit.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-reload-state.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-routes.sh") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-slot-patch.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-subscription-status.py") GM_PATH_MODULE="core" ;;
    "/usr/lib/geomask/geomask-sync-youtube.py") GM_PATH_MODULE="core" ;;
    "/etc/geomask/vpnwatch.conf") GM_PATH_MODULE="diagnostic" ;;
    "/usr/bin/geomask-dnscheck.sh") GM_PATH_MODULE="diagnostic" ;;
    "/usr/bin/geomask-morning-check.sh") GM_PATH_MODULE="diagnostic" ;;
    "/usr/bin/geomask-vpnwatch.sh") GM_PATH_MODULE="diagnostic" ;;
    "/usr/lib/geomask/geomask-doctor.py") GM_PATH_MODULE="doctor" ;;
    "/etc/hotplug.d/iface/99-geomask-guard") GM_PATH_MODULE="guard" ;;
    "/usr/bin/geomask-guard.sh") GM_PATH_MODULE="guard" ;;
    "/usr/libexec/rpcd/geo-sync") GM_PATH_MODULE="luci" ;;
    "/usr/share/luci/menu.d/luci-app-geo-sync.json") GM_PATH_MODULE="luci" ;;
    "/usr/share/rpcd/acl.d/luci-app-geo-sync.json") GM_PATH_MODULE="luci" ;;
    "/www/luci-static/resources/view/geo-sync/main.js") GM_PATH_MODULE="luci" ;;
    "/etc/mihomo/ruleset/torrentdirect.yaml") GM_PATH_MODULE="torrent" ;;
    "/usr/bin/geomask-torrent.sh") GM_PATH_MODULE="torrent" ;;
    "/etc/geomask-ytwatch.conf") GM_PATH_MODULE="youtube" ;;
    "/etc/mihomo/ruleset/ytdirect.yaml") GM_PATH_MODULE="youtube" ;;
    "/etc/mihomo/ruleset/ytvpn.yaml") GM_PATH_MODULE="youtube" ;;
    "/usr/bin/geomask-ytwatch.sh") GM_PATH_MODULE="youtube" ;;
  esac
  [ -n "$GM_PATH_MODULE" ] && echo "$GM_PATH_MODULE"
}
module_skip_path() { # true when the path belongs to a module the owner did not select
  _m=$(module_owns_path "$1")
  [ -n "$_m" ] || return 1
  module_selected "$_m" && return 1
  return 0
}

# ---- the one lock helper (R04) ----------------------------------------------
# Single source of truth: assets/geomask-lock.sh. Injected here so the installer locks with
# exactly the same code it installs to /usr/lib/geomask/geomask-lock.sh, and installed by the
# save_stream below. Kernel flock(2) on a persistent inode: no PID, no reclaim, no unlink.
# The config-transaction lock path and the lock directory are prefixed exactly like every other
# path the installer touches. On the router P is the identity, so these are the real
# /etc/geomask/node-audit/state/.config-tx.lock and /tmp/geomask-locks the runtime writers use;
# a test root can never make the installer lock (or write) the host /etc or host /tmp. Both are
# set BEFORE the helper is sourced: the helper captures the canonical path and keeps a
# non-empty GM_LOCK_DIR provided by the caller. They are exported because the installer starts
# child writers (uninstall calls geomask-lane.sh), which must inherit the injected paths
# instead of falling back to the host ones.
GM_CONFIG_TX_LOCK=${GM_CONFIG_TX_LOCK:-$(P /etc/geomask/node-audit/state/.config-tx.lock)}
GM_LOCK_DIR=${GM_LOCK_DIR:-$(P /tmp/geomask-locks)}
export GM_CONFIG_TX_LOCK GM_LOCK_DIR
# geomask-lock.sh - the ONE inter-process lock helper of geomask (R04).
#
# Contract
#   * One persistent lock file per name. The file is opened, never deleted and never
#     recreated while a lock is in use: the same inode is locked every time, so a lock
#     released by one process is exactly the lock the next process takes.
#   * The lock itself is kernel flock(2) on that file: BusyBox `flock` (the applet is part of
#     the upstream OpenWrt 24.10 busybox config) and Python `fcntl.flock` on the same path
#     (geomask-config-tx.py) are the same primitive, so shell and Python exclude each other.
#   * No PID is stored, no owner is guessed, no stale lock is reclaimed. A holder that dies -
#     including SIGKILL - has its lock released by the kernel when the last descriptor of
#     that open file description is closed. There is therefore no ownerless window (nothing
#     is created before the lock is held) and no unlock-after-takeover (the file is never
#     removed, so a slow release cannot hand the lock to two writers).
#   * Fixed lock order, enforced at run time: a process may only take locks with a strictly
#     higher rank than every lock it already holds (gm_lock_rank). Downward nesting is
#     refused with rc=4 instead of deadlocking. The order is:
#       maintenance(10) -> console(20) -> cron(25) -> config-tx(30) -> routes-worker(35)
#       -> route-<table>(40) -> sync(45) -> devices(60) -> subs(65)
#   routes-worker is the R05 single-flight queue worker: it is taken before the per-table lock
#   (so two workers cannot fight over one table) and after config-tx (a panel transaction may
#   hold config-tx and then ask the queue to apply, never the other way around).
#   cron sits before config-tx because the uninstall (under maintenance) removes crontab lines
#   and then asks the lane helper to rewrite the mihomo config; the reverse nesting never
#   happens (the transaction and the lane manager never touch cron).
#   * Waiting is bounded and explicit: `gm_lock_acquire <name> [seconds] [path]`. 0 means a
#     single non-blocking attempt (hotplug, guard watchdog, single-instance entrypoints).
#     BusyBox flock has no -w, so a bounded wait is `flock -n` plus sleep 1 up to the budget.
#   * Critical sections stay short and contain no long-running external call. Commands that
#     may leave a daemon behind (init scripts, services) MUST be run through
#     gm_lock_safe_exec, which closes the reserved descriptors in the child: otherwise the
#     daemon inherits the descriptor and keeps the lock after the writer has exited.
#   * Fail-closed on the target: if `flock` cannot be found on Linux, every acquisition
#     returns rc=2 and the caller must refuse to mutate. There is NO mkdir/O_EXCL fallback on
#     Linux - that would bring back the reclaim race R04 is about.
#
# Safety: this file performs no dynamic code evaluation, starts no shell with a command
# string, and uses no dynamically named shell variables. The lock path and the lock name are DATA: paths reach
# `exec` only as quoted words, state lives in fixed variables (_GM_PATH_5..9) and in a
# token list "name=fd", and every descriptor operation is a literal `exec 5..9`. A path or a
# name that contains quotes, `$(...)`, backticks, `;`, `&` or spaces is never executed.
# The name is validated (`[A-Za-z][A-Za-z0-9-]*`) and a path containing a newline is refused.
#
# Non-Linux hosts (the Windows-hosted test suite) have neither flock(2) nor /proc. There the
# helper uses an atomic O_EXCL file (noclobber) created once and removed only by its owner.
# This backend exists so that caller logic can be exercised off-router; it is never selected
# on Linux, it does not release on SIGKILL (documented Linux-only test gap) and it is not a
# supported runtime.
#
# Environment (overridable for injected test roots only, never for skipping the lock):
#   GM_LOCK_DIR      directory of the lock files (default /tmp/geomask-locks, mode 0700)
#   GM_CONFIG_TX_LOCK  CANONICAL path of the config-transaction lock, shared with
#                      geomask-config-tx.py, geomask-node-scan.sh and geomask-torrent.sh
#   GM_LOCK_TX_FILE    legacy alias of GM_CONFIG_TX_LOCK (test roots only)
#   GM_LOCK_FDS      reserved descriptors; must be a subset of 5 6 7 8 9

GM_LOCK_DIR=${GM_LOCK_DIR:-/tmp/geomask-locks}
GM_LOCK_TX_FILE=${GM_CONFIG_TX_LOCK:-${GM_LOCK_TX_FILE:-/etc/geomask/node-audit/state/.config-tx.lock}}
GM_LOCK_FDS=${GM_LOCK_FDS:-5 6 7 8 9}
GM_LOCK_MAX_RANK=${GM_LOCK_MAX_RANK:-0}
GM_LOCK_STACK=${GM_LOCK_STACK:-}
_GM_PATH_5=${_GM_PATH_5:-}
_GM_PATH_6=${_GM_PATH_6:-}
_GM_PATH_7=${_GM_PATH_7:-}
_GM_PATH_8=${_GM_PATH_8:-}
_GM_PATH_9=${_GM_PATH_9:-}

# The rank table is the lock order. Unknown names get 90 so a new writer is the outermost -
# an earlier rank could otherwise turn a lawful sequence into a refused one silently.
gm_lock_rank() {
  case "$1" in
    maintenance)   printf '10' ;;
    console)       printf '20' ;;
    cron)          printf '25' ;;
    config-tx)     printf '30' ;;
    routes-worker) printf '35' ;;
    route-*)       printf '40' ;;
    sync)          printf '45' ;;
    devices)       printf '60' ;;
    subs)          printf '65' ;;
    *)             printf '90' ;;
  esac
}

# Echo the file a lock name uses. An explicit path wins (callers keep their historical
# env-overridable path, e.g. GM_CONSOLE_LOCK, so an injected test root never touches /tmp).
gm_lock_path() { # gm_lock_path <name> [explicit-path]
  if [ -n "${2:-}" ]; then
    printf '%s' "$2"
  elif [ "$1" = config-tx ]; then
    printf '%s' "$GM_LOCK_TX_FILE"
  else
    printf '%s/%s.lock' "$GM_LOCK_DIR" "$1"
  fi
}

# flock | portable | missing. "missing" is a refusal on Linux (the caller must fail closed).
gm_lock_backend() {
  if command -v flock >/dev/null 2>&1; then
    printf 'flock'
    return 0
  fi
  case "$(uname -s 2>/dev/null)" in
    Linux) printf 'missing' ;;
    '')    printf 'missing' ;;
    *)     printf 'portable' ;;
  esac
}

_gm_lock_fds_ok() {
  for _gm_f in $GM_LOCK_FDS; do
    case "$_gm_f" in
      5|6|7|8|9) : ;;
      *) return 1 ;;
    esac
  done
  return 0
}

# Echo the descriptor held for <name>, empty when this shell does not hold it.
_gm_lock_fd_of() {
  for _gm_t in $GM_LOCK_STACK; do
    case "$_gm_t" in
      "$1"=*) printf '%s' "${_gm_t#*=}"; return 0 ;;
    esac
  done
  return 1
}

_gm_lock_held() { _gm_lock_fd_of "$1" >/dev/null 2>&1; }

_gm_lock_fd_used() { # 0 when <fd> is in the stack
  for _gm_t in $GM_LOCK_STACK; do
    [ "${_gm_t#*=}" = "$1" ] && return 0
  done
  return 1
}

_gm_lock_recalc_rank() {
  GM_LOCK_MAX_RANK=0
  for _gm_t in $GM_LOCK_STACK; do
    _gm_r=$(gm_lock_rank "${_gm_t%%=*}")
    [ "$_gm_r" -gt "$GM_LOCK_MAX_RANK" ] && GM_LOCK_MAX_RANK=$_gm_r
  done
  return 0
}

_gm_lock_path_of() { # the path stored for a reserved descriptor
  case "$1" in
    5) printf '%s' "$_GM_PATH_5" ;;
    6) printf '%s' "$_GM_PATH_6" ;;
    7) printf '%s' "$_GM_PATH_7" ;;
    8) printf '%s' "$_GM_PATH_8" ;;
    9) printf '%s' "$_GM_PATH_9" ;;
  esac
}

_gm_lock_set_path() { # <fd> <path> - literal slots, no dynamic variable names
  case "$1" in
    5) _GM_PATH_5=$2 ;;
    6) _GM_PATH_6=$2 ;;
    7) _GM_PATH_7=$2 ;;
    8) _GM_PATH_8=$2 ;;
    9) _GM_PATH_9=$2 ;;
  esac
}

_gm_lock_track() { # <name> <fd> <path>
  _gm_lock_set_path "$2" "$3"
  if [ -n "$GM_LOCK_STACK" ]; then
    GM_LOCK_STACK="$GM_LOCK_STACK $1=$2"
  else
    GM_LOCK_STACK="$1=$2"
  fi
  _gm_lock_recalc_rank
}

_gm_lock_forget() { # <name> <fd>
  _gm_lock_set_path "$2" ''
  _gm_new=''
  for _gm_t in $GM_LOCK_STACK; do
    case "$_gm_t" in
      "$1"=*) : ;;
      *) _gm_new="${_gm_new:+$_gm_new }$_gm_t" ;;
    esac
  done
  GM_LOCK_STACK=$_gm_new
  _gm_lock_recalc_rank
}

_gm_lock_free_fd() {
  for _gm_c in $GM_LOCK_FDS; do
    _gm_lock_fd_used "$_gm_c" && continue
    printf '%s' "$_gm_c"
    return 0
  done
  return 1
}

# Open <fd> on <path> with a literal `exec`. A plain `: >>path` first creates the file and
# proves writability, so a redirection error is reported by us (rc=2) instead of possibly
# terminating a non-interactive shell on the `exec` line.
_gm_lock_open() { # <fd> <path>
  { : >>"$2"; } 2>/dev/null || return 1
  case "$1" in
    5) exec 5<>"$2" 2>/dev/null ;;
    6) exec 6<>"$2" 2>/dev/null ;;
    7) exec 7<>"$2" 2>/dev/null ;;
    8) exec 8<>"$2" 2>/dev/null ;;
    9) exec 9<>"$2" 2>/dev/null ;;
    *) return 1 ;;
  esac
}

_gm_lock_close_fd() { # <fd>
  case "$1" in
    5) exec 5>&- 2>/dev/null ;;
    6) exec 6>&- 2>/dev/null ;;
    7) exec 7>&- 2>/dev/null ;;
    8) exec 8>&- 2>/dev/null ;;
    9) exec 9>&- 2>/dev/null ;;
  esac
  return 0
}

# Acquire <name>. rc: 0 held, 1 busy/timeout, 2 primitive unavailable / bad input (fail
# closed), 3 already held by this shell, 4 lock order violated. On 1/2/3/4 nothing is held.
gm_lock_acquire() { # gm_lock_acquire <name> [wait-seconds] [path]
  _gm_name=$1
  _gm_wait=${2:-0}
  case "$_gm_name" in
    ''|[!A-Za-z]*|*[!A-Za-z0-9-]*)
      echo "geomask-lock: invalid lock name '$_gm_name' (letters, digits and '-', must start with a letter)" >&2
      return 2 ;;
  esac
  # A non-numeric budget is a caller bug, not "wait forever": refuse it before the deadline
  # comparison, otherwise `[ N -ge abc ]` errors and the retry loop never terminates.
  case "$_gm_wait" in
    ''|*[!0-9]*)
      echo "geomask-lock: wait budget for '$_gm_name' must be a non-negative integer, got '$_gm_wait'" >&2
      return 2 ;;
  esac
  [ "$_gm_wait" -gt 3600 ] && _gm_wait=3600
  _gm_lock_fds_ok || {
    echo "geomask-lock: GM_LOCK_FDS='$GM_LOCK_FDS' is not a subset of 5 6 7 8 9 - refusing to lock" >&2
    return 2
  }
  # Reject a newline in the path SOURCE: command substitution would silently drop a trailing
  # newline, so checking only the composed path is not enough. The path is data, not code.
  _gm_src=${3:-}
  if [ -z "$_gm_src" ]; then
    if [ "$_gm_name" = config-tx ]; then
      _gm_src=$GM_LOCK_TX_FILE
    else
      _gm_src=$GM_LOCK_DIR
    fi
  fi
  case "$_gm_src" in
    *'
'*)
      echo "geomask-lock: the lock path of '$_gm_name' contains a newline - refusing to lock" >&2
      return 2 ;;
  esac
  _gm_path=$(gm_lock_path "$_gm_name" "${3:-}")
  _gm_rank=$(gm_lock_rank "$_gm_name")

  if _gm_lock_held "$_gm_name"; then
    echo "geomask-lock: '$GM_LOCK_STACK' already holds '$_gm_name' (re-entrant acquire refused)" >&2
    return 3
  fi
  if [ "$GM_LOCK_MAX_RANK" -ge "$_gm_rank" ]; then
    echo "geomask-lock: lock order violation: '$_gm_name' (rank $_gm_rank) requested while holding '$GM_LOCK_STACK' (max rank $GM_LOCK_MAX_RANK)" >&2
    return 4
  fi

  _gm_backend=$(gm_lock_backend)
  case "$_gm_backend" in
    missing)
      echo "geomask-lock: the flock primitive is missing on Linux ($_gm_name): refusing to mutate without a lock" >&2
      return 2 ;;
  esac

  _gm_dir=$(dirname "$_gm_path")
  ( umask 077; mkdir -p "$_gm_dir" ) 2>/dev/null || {
    echo "geomask-lock: cannot create the lock directory $_gm_dir - refusing to lock $_gm_name" >&2
    return 2
  }
  _gm_fd=$(_gm_lock_free_fd) || {
    echo "geomask-lock: no free reserved descriptor for '$_gm_name' (GM_LOCK_FDS='$GM_LOCK_FDS')" >&2
    return 2
  }

  _gm_try=0
  while :; do
    if [ "$_gm_backend" = portable ]; then
      # noclobber create: the file appears exactly once, atomically. Never reclaimed.
      if ( set -C; : > "$_gm_path" ) 2>/dev/null; then
        _gm_lock_track "$_gm_name" "$_gm_fd" "$_gm_path"
        return 0
      fi
    else
      if _gm_lock_open "$_gm_fd" "$_gm_path"; then
        if flock -n "$_gm_fd" 2>/dev/null; then
          _gm_lock_track "$_gm_name" "$_gm_fd" "$_gm_path"
          return 0
        fi
        _gm_lock_close_fd "$_gm_fd"
      else
        echo "geomask-lock: cannot open the lock file $_gm_path - refusing to lock $_gm_name" >&2
        return 2
      fi
    fi
    if [ "$_gm_try" -ge "$_gm_wait" ]; then
      return 1
    fi
    _gm_try=$((_gm_try+1))
    sleep 1
  done
}

gm_lock_release() { # gm_lock_release <name>
  _gm_name=$1
  _gm_fd=$(_gm_lock_fd_of "$_gm_name") || return 0
  _gm_path=$(_gm_lock_path_of "$_gm_fd")
  if [ "$(gm_lock_backend)" = portable ]; then
    [ -f "$_gm_path" ] && rm -f "$_gm_path" 2>/dev/null
  else
    flock -u "$_gm_fd" 2>/dev/null
    _gm_lock_close_fd "$_gm_fd"
  fi
  _gm_lock_forget "$_gm_name" "$_gm_fd"
  return 0
}

gm_lock_release_all() {
  for _gm_t in $GM_LOCK_STACK; do
    gm_lock_release "${_gm_t%%=*}"
  done
}

# Report whether another process holds <name>: 0 busy, 1 free, 2 primitive unavailable.
gm_lock_busy() { # gm_lock_busy <name> [path]
  _gm_name=$1
  if gm_lock_acquire "$_gm_name" 0 "${2:-}"; then
    gm_lock_release "$_gm_name"
    return 1
  else
    _gm_rc=$?
    [ "$_gm_rc" = 1 ] && return 0
    return 2
  fi
}

# Close the reserved descriptors in this process WITHOUT unlocking: flock lives on the open
# file description, so another process (the updater runner) still holds the lock. Literal
# descriptors only - descriptors 0/1/2 and anything the caller opened are never touched.
gm_lock_close_inherited() {
  exec 5>&- 2>/dev/null
  exec 6>&- 2>/dev/null
  exec 7>&- 2>/dev/null
  exec 8>&- 2>/dev/null
  exec 9>&- 2>/dev/null
  _GM_PATH_5=''; _GM_PATH_6=''; _GM_PATH_7=''; _GM_PATH_8=''; _GM_PATH_9=''
  GM_LOCK_STACK=''
  GM_LOCK_MAX_RANK=0
  return 0
}

# Run a command (init script, service) so it does not inherit the lock descriptors. A daemon
# spawned with them would keep the lock after the writer exits and block every later writer.
gm_lock_safe_exec() {
  ( gm_lock_close_inherited; "$@" )
}

save_stream() { # save_stream <target-path> <mode>  (content on stdin)
  if module_skip_path "$1"; then
    cat >/dev/null 2>&1 || true
    info "skip $1: module '$(module_owns_path "$1")' not selected"
    return 0
  fi
  _t="$(P "$1")"; _m="$2"
  mkdir -p "$(dirname "$_t")" || { SAVE_FAIL=$((SAVE_FAIL+1)); return 1; }
  # A fixed `.zmnew` is shared by every writer: two runs interleaving on it could publish one
  # run's bytes through the other's `mv` (audit I09). mkstemp-style unique temps remove that.
  _tmp=$(mktemp "$_t.zmnew.XXXXXX" 2>/dev/null) || _tmp="$_t.zmnew.$$"
  cat > "$_tmp" || { rm -f "$_tmp"; SAVE_FAIL=$((SAVE_FAIL+1)); return 1; }
  if [ -f "$_t" ] && cmp -s "$_tmp" "$_t"; then
    # identical bytes: keep the file, but repair a lost mode. Returning before chmod left an
    # entrypoint non-executable forever after a restore or a botched copy.
    chmod "$_m" "$_t" 2>/dev/null || true
    rm -f "$_tmp"
    info "unchanged: $1"
    return 0
  fi
  _want=$(wc -c < "$_tmp" 2>/dev/null | tr -d ' ')
  if [ -f "$_t" ]; then
    cp -p "$_t" "$_t.bak_geomask_$(date +%s 2>/dev/null || echo bak)" 2>/dev/null || true
  fi
  chmod "$_m" "$_tmp" 2>/dev/null || true
  mv -f "$_tmp" "$_t" || { rm -f "$_tmp"; SAVE_FAIL=$((SAVE_FAIL+1)); return 1; }
  # Trust the published bytes, not the exit of `mv`: a short write or a filesystem that
  # silently truncated the file used to be reported as "written".
  _got=$(wc -c < "$_t" 2>/dev/null | tr -d ' ')
  if [ -n "${_want:-}" ] && [ "$_want" != "$_got" ]; then
    SAVE_FAIL=$((SAVE_FAIL+1))
    bad "written size mismatch for $1 (${_got:-?} of ${_want} bytes)"
    return 1
  fi
  info "written: $1 (mode $_m)"
  return 0
}

# ---- optional modules: gates shared by check and apply ---------------------
# A module the owner did not select is never written, so every check that used to fail
# the install for its missing piece asks mod_skipped first. Cron entries are the trap:
# creation lives in step5_apply, verification in step5_check, and verification used to
# abort the whole run - so both halves go through cron_ensure / cron_verify, which read
# the same module flag. Never wrap only one half.
mod_skipped() { # mod_skipped <module> -> 0 (and a note) when the module is not selected
  module_selected "$1" && return 1
  info "пропущен: модуль '$1' не выбран"
  return 0
}

# Every rewrite of /etc/crontabs/root is a read-modify-write: the panel (nodes_set,
# sync_set), the installer and uninstall must take the same kernel `cron` lock or one writer
# silently drops the other's line (report R09). cron_ensure is used by step5 many times.
# Nesting matters: uninstall/restore run with the `cron` lock already held by an outer caller,
# and the kernel lock treats a second acquire as refusal (rc 3). The depth counter makes the
# pair re-entrant inside one shell while still releasing exactly once.
_CRON_LOCK_DEPTH=${_CRON_LOCK_DEPTH:-0}
_cron_begin() {
  command -v gm_lock_acquire >/dev/null 2>&1 || return 1
  gm_lock_acquire cron 20
  _cbl_rc=$?
  case "$_cbl_rc" in
    0|3) _CRON_LOCK_DEPTH=$(( ${_CRON_LOCK_DEPTH:-0} + 1 )); return 0 ;;
  esac
  return 1
}
_cron_end() {
  [ "${_CRON_LOCK_DEPTH:-0}" -gt 0 ] || return 0
  _CRON_LOCK_DEPTH=$(( ${_CRON_LOCK_DEPTH:-0} - 1 ))
  [ "$_CRON_LOCK_DEPTH" -eq 0 ] || return 0
  command -v gm_lock_release >/dev/null 2>&1 && gm_lock_release cron
  return 0
}

cron_ensure() { # cron_ensure <module> <marker-ere> <cron-line>
  mod_skipped "$1" && return 0
  if crontab -l 2>/dev/null | grep -qE -- "$2"; then info "cron: уже есть ($2)"; return 0; fi
  if ! _cron_begin; then
    warn "cron: блокировка недоступна ($2) - строка не добавлена"
    return 1
  fi
  ( crontab -l 2>/dev/null; printf '%s\n' "$3" ) | crontab - 2>/dev/null \
    && info "cron: добавлен ($2)" || warn "cron: не удалось записать ($2)"
  _cron_end
  return 0
}

cron_verify() { # cron_verify <module> <marker-ere> <label> [soft]
  mod_skipped "$1" && return 0
  if crontab -l 2>/dev/null | grep -qE -- "$2"; then info "$3: present"; return 0; fi
  if [ "${4:-hard}" = soft ]; then warn "$3: отсутствует"
  else bad "$3: отсутствует"; _need=1; fi
}

ruleset_stub() { # ruleset_stub <module> <install-path> - keep `mihomo -t` valid without the module
  mod_skipped "$1" >/dev/null || return 0
  [ -s "$(P "$2")" ] && return 0
  mkdir -p "$(dirname "$(P "$2")")" 2>/dev/null
  printf '%s\n%s\n' "# module '$1' is not selected: ruleset kept empty" 'payload: []' > "$(P "$2")"
  info "ruleset: $2 kept empty (module '$1' not selected)"
}

# ---- the selection is remembered on the router ------------------------------
# /etc/geomask/modules.json is the single source of truth for "which modules does this
# router carry": the installer writes it, the panel and the per-module updater read it.
MODULES_STATE=/etc/geomask/modules.json

modules_state_read() { # prints the stored selection; rc 1 = absent, 2 = damaged, 3 = no python
  # A damaged file used to be indistinguishable from "no selection", and "no selection" means
  # "install everything" - so one broken byte silently widened the install (audit I10).
  [ -e "$(P $MODULES_STATE)" ] || return 1
  [ -s "$(P $MODULES_STATE)" ] || return 2
  command -v python3 >/dev/null 2>&1 || command -v python >/dev/null 2>&1 || return 3
  _msr=$(_mihomo_py "$(P $MODULES_STATE)" <<'PYEOF'
import json, sys
try:
    data = json.load(open(sys.argv[1], encoding='utf-8'))
except Exception:
    raise SystemExit(1)
selected = data.get('selected') if isinstance(data, dict) else None
if not isinstance(selected, list) or not selected:
    raise SystemExit(1)
print(' '.join(str(item) for item in selected))
PYEOF
  ) || return 2
  [ -n "$_msr" ] || return 2
  printf '%s' "$_msr"
}

modules_state_write() { # modules_state_write <module>...
  [ $# -gt 0 ] || return 0
  mkdir -p "$(P /etc/geomask)" 2>/dev/null || true
  # Publish atomically: the panel and the updater read this file, and a truncated write would
  # look like a damaged selection. The temp lives next to the target for an atomic rename.
  _msw_tmp="$(P $MODULES_STATE).tmp.$$"
  _mihomo_py "$_msw_tmp" "$@" <<'PYEOF' || { rm -f "$_msw_tmp" 2>/dev/null; warn "modules: не удалось записать $MODULES_STATE"; return 1; }
import json, sys
with open(sys.argv[1], 'w', encoding='utf-8', newline='\n') as handle:
    json.dump({'selected': sys.argv[2:]}, handle, ensure_ascii=False, indent=2)
    handle.write('\n')
PYEOF
  mv -f "$_msw_tmp" "$(P $MODULES_STATE)" 2>/dev/null \
    || { rm -f "$_msw_tmp" 2>/dev/null; warn "modules: не удалось опубликовать $MODULES_STATE"; return 1; }
}

module_effective_list() { # the modules this run installs (all, unless --modules narrowed it)
  if [ -n "$GM_MODULES" ]; then printf '%s\n' "$GM_MODULES"; else printf '%s\n' "$GM_ALL_MODULES"; fi
}

# I11 (audit 18.11.2026): narrowing the selection used to leave the removed module's runtime
# behind - the guard kept its hotplug hook, its 5-minute cron job and therefore kept re-seating
# rules, AI-DNS kept its two services and its nft table - so a "subset" router went on running
# components it no longer claimed to have. The catalogue already declares what a module owns,
# so removal is data-driven instead of a hardcoded list that drifts from the metadata.
module_owned_resources() { # module_owned_resources <module> -> "<type>|<path>" lines
  _mor_idx="$(P /etc/geomask/modules-index.json)"
  [ -s "$_mor_idx" ] || return 1
  _mihomo_py "$_mor_idx" "$1" <<'PYEOF'
import json, sys
# Windows checkouts run these helpers under a Python whose stdout is CRLF; the shell `read`
# would then carry a trailing CR into every path and `[ -e ]` would fail silently.
try:
    sys.stdout.reconfigure(newline='\n')
except Exception:
    pass
try:
    with open(sys.argv[1], encoding='utf-8') as fh:
        data = json.load(fh)
except Exception:
    raise SystemExit(1)
mods = data.get('modules') if isinstance(data, dict) else None
if isinstance(mods, list):
    mods = {item.get('id'): item for item in mods if isinstance(item, dict)}
if not isinstance(mods, dict):
    raise SystemExit(1)
mod = mods.get(sys.argv[2])
if not isinstance(mod, dict):
    raise SystemExit(1)
for res in mod.get('owned_resources') or []:
    if not isinstance(res, dict):
        continue
    kind, path = res.get('type'), res.get('path')
    if isinstance(kind, str) and isinstance(path, str) and kind and path:
        print('%s|%s' % (kind, path))
PYEOF
}

modules_remove_runtime() { # modules_remove_runtime <module> [reason] -> 0 when something was removed
  _mrr_why=${2:-снят с выбора}
  _mrr_res=$(module_owned_resources "$1") || {
    warn "modules: '$1' $_mrr_why, но каталог модулей не прочитан - runtime не снят"
    return 1
  }
  [ -n "$_mrr_res" ] || return 1
  _mrr_did=0
  while IFS='|' read -r _mrr_kind _mrr_path; do
    _mrr_kind=${_mrr_kind%\r}
    _mrr_path=${_mrr_path%\r}
    [ -n "${_mrr_kind:-}" ] || continue
    case "$_mrr_kind" in
      service)
        _mrr_init="$(P "/etc/init.d/$_mrr_path")"
        if [ -f "$_mrr_init" ]; then
          "$_mrr_init" stop >/dev/null 2>&1
          "$_mrr_init" disable >/dev/null 2>&1
          info "снят сервис $_mrr_path ($1: $_mrr_why)"
          _mrr_did=1
        fi ;;
      file)
        _mrr_f="$(P "$_mrr_path")"
        if [ -e "$_mrr_f" ] || [ -L "$_mrr_f" ]; then
          rm -f "$_mrr_f" 2>/dev/null && { info "снят файл $_mrr_path ($1: $_mrr_why)"; _mrr_did=1; }
        fi ;;
      cron)
        if have crontab; then
          _cron_begin || true
          _mrr_cron=$(crontab -l 2>/dev/null)
          if printf '%s\n' "$_mrr_cron" | grep -q -- "$_mrr_path"; then
            if printf '%s\n' "$_mrr_cron" | grep -v -- "$_mrr_path" | crontab - 2>/dev/null; then
              info "снята cron-запись $_mrr_path ($1: $_mrr_why)"
              _mrr_did=1
            fi
          fi
          _cron_end
        fi ;;
      nft)
        if have nft && nft list table inet "$_mrr_path" >/dev/null 2>&1; then
          if nft delete table inet "$_mrr_path" >/dev/null 2>&1; then
            info "снята nft-таблица $_mrr_path ($1: $_mrr_why)"
            _mrr_did=1
          fi
        fi ;;
      *)
        info "ресурс '$_mrr_kind $_mrr_path' модуля $1 не снят автоматически - проверьте вручную" ;;
    esac
  done <<EOF
$_mrr_res
EOF
  [ "$_mrr_did" = 1 ]
}

modules_prune_selection() { # modules_prune_selection <old selection> <new selection>
  _mps_did=0
  for _mps_mod in $1; do
    case " $2 " in
      *" $_mps_mod "*) continue ;;
    esac
    modules_remove_runtime "$_mps_mod" "снят с выбора" && _mps_did=1
  done
  [ "$_mps_did" = 1 ]
}

modules_state_sync() { # remember the effective selection, only when it changed
  _want=$(module_effective_list)
  _msr_rc=0
  _have=$(modules_state_read) || _msr_rc=$?
  if [ "$_msr_rc" = 2 ]; then
    # Refuse: overwriting a damaged selection would erase the owner's choice on a guess.
    bad "modules: $MODULES_STATE повреждён - выбор не меняю (исправьте файл или удалите его для выбора всех модулей)"
    return 1
  fi
  if [ "$_msr_rc" = 3 ]; then
    warn "modules: python недоступен - сохранённый выбор не проверен"
    return 0
  fi
  [ "$_want" = "$_have" ] && return 0
  # Narrowing the selection now removes what the dropped modules own (files, services, cron
  # entries, nft tables) instead of leaving the runtime running behind a smaller claim. Owner
  # state and config files are not in owned_resources, so they stay.
  modules_prune_selection "$_have" "$_want" || true
  modules_state_write $_want
}

choose_modules() { # interactive picker; required modules are always installed
  _cm_rc=0
  _cur=$(modules_state_read) || _cm_rc=$?
  if [ "$_cm_rc" = 2 ]; then
    bad "modules: $MODULES_STATE повреждён - выбор не начинаю (исправьте файл или удалите его)"
    return 1
  fi
  if [ "$_cm_rc" = 3 ]; then
    warn "modules: python недоступен - показываю полный список"
  fi
  if [ "$_cm_rc" = 1 ] || [ -z "$_cur" ]; then _cur="$GM_ALL_MODULES"; fi
  echo
  printf '%sМодули%s: обязательные ставятся всегда, остальные — по выбору.\n' "$C_Y" "$NC"
  _i=0
  for _m in $GM_ALL_MODULES; do
    _i=$((_i+1))
    if module_required "$_m"; then _mk="обязательный"; _mc="$C_G"
    else
      case " $_cur " in
        *" $_m "*) _mk="выбран"; _mc="$C_G" ;;
        *)         _mk="по выбору"; _mc="$C_DIM" ;;
      esac
    fi
    printf '  %s%2d)%s %-18s %s  %s[%s]%s\n' "$C_B" "$_i" "$NC" "$_m" "$(module_label "$_m")" "$_mc" "$_mk" "$NC"
  done
  printf 'Номера через запятую [Enter = оставить текущий выбор, all = все]: '
  read -r _ans || _ans=""
  case "$_ans" in
    "") GM_MODULES=$_cur ;;
    all|ALL|все|ВСЕ|Все) GM_MODULES="$GM_ALL_MODULES" ;;
    *)
      _sel=""
      for _tok in $(printf '%s' "$_ans" | tr ',' ' '); do
        case "$_tok" in
          *[!0-9]*) warn "не номер: $_tok"; continue ;;
        esac
        _m=$(printf '%s\n' $GM_ALL_MODULES | sed -n "${_tok}p")
        if [ -z "$_m" ]; then warn "нет модуля с номером $_tok"; continue; fi
        case " $_sel " in *" $_m "*) ;; *) _sel="$_sel $_m" ;; esac
      done
      for _m in $GM_REQUIRED_MODULES; do
        case " $_sel " in *" $_m "*) ;; *) _sel="$_sel $_m" ;; esac
      done
      GM_MODULES=$(printf '%s' "$_sel" | sed 's/^ *//;s/  */ /g')
      ;;
  esac
  info "модули: $GM_MODULES"
}

modules_maybe_prompt() { # ask at most once per run, and only when the run can install
  [ -n "$GM_MODULES" ] && return 0
  [ "${GM_MODULES_ASKED:-0}" = 1 ] && return 0
  # GM_MODULES_ASK=1 lets the sandbox harness drive the picker without a tty.
  if [ "${GM_MODULES_ASK:-0}" != 1 ]; then
    if [ "$GM_YES" = 1 ] || [ "$GM_AUTO" = 1 ] || [ "$GM_CHECK_ONLY" = 1 ]; then
      # unattended runs keep the router's own selection; "no --modules" used to mean "all",
      # which made an update re-install modules the owner had deliberately left out
      _stored=$(modules_state_read 2>/dev/null || true)
      [ -n "$_stored" ] && GM_MODULES="$_stored"
      return 0
    fi
    [ -t 0 ] || return 0
  fi
  GM_MODULES_ASKED=1
  choose_modules
}

have() { command -v "$1" >/dev/null 2>&1; }

svc_alive() { pidof "$1" >/dev/null 2>&1; }

initd() { # initd <svc> <action>  - respects GM_PREFIX for tests
  # Never execute an init script through a symlinked component: the restore refuses unsafe
  # paths up front, and this guard keeps every other caller fail-closed as well.
  if command -v _rs_safe_exec >/dev/null 2>&1; then
    if ! _rs_safe_exec "/etc/init.d/$1"; then
      warn "initd: /etc/init.d/$1 is behind an unsafe or unpinned symlink - refusing to execute it"
      return 1
    fi
  else
    if [ -L "$(P /etc/init.d/$1)" ]; then
      warn "initd: /etc/init.d/$1 is a symlink - refusing to execute it"
      return 1
    fi
  fi
  # Run the init script without the lock descriptors: a service that daemonizes directly (or a
  # procd fallback) must not inherit the maintenance lock and hold it until reboot.
  if command -v gm_lock_safe_exec >/dev/null 2>&1; then
    gm_lock_safe_exec "$(P /etc/init.d/$1)" "$2" 2>/dev/null
  else
    "$(P /etc/init.d/$1)" "$2" 2>/dev/null
  fi
}

# ============================================================ PREFLIGHT
# R04: the lock primitive is a mandatory dependency of every writer, on the normal install as
# well as on the reinstall preflight. Echoes the missing piece (Linux only); rc=1 when usable.
# Without flock every writer refuses to mutate, and the copied helper file must not exist.
lock_primitive_missing() {
  [ "$(uname -s 2>/dev/null)" = Linux ] || return 0
  have flock || { printf 'flock applet (BusyBox; upstream OpenWrt 24.10 ships it)'; return 0; }
  if have python3 && ! python3 -c 'import fcntl' >/dev/null 2>&1; then
    printf 'python3 fcntl (the config transaction lock is fail-closed without it)'
    return 0
  fi
  return 1
}

# Everything that can only fail later is checked here, before the first byte is written:
# a reset router must not end up with a panel and no working mihomo config.
preflight() {
  _need=0
  _c="$(P $MIHOMO_CONF)"
  if [ -z "$GM_VPN_URL" ]; then
    _u=""
    [ -s "$_c" ] && _u=$(_prov_url "$_c" sub)
    if [ -z "$_u" ] && [ -s "$_c" ]; then _u=$(any_provider_url "$_c"); fi
    if [ -z "$_u" ]; then
      _mo=0
      [ -s "$_c" ] && { geomask_config_verdict "$_c" || _mo=$?; }
      if [ "$_mo" = 2 ]; then
        # N04: an unreadable file is not "somebody else's config" - say what is missing.
        bad "preflight: конфиг mihomo не читается (python3-yaml отсутствует или файл повреждён)"
        info "  Владение конфигом определить нельзя; установка не начинается."
      elif [ "$_mo" = 1 ] && [ "${GM_ADOPT:-0}" != 1 ] && [ "${GM_REPLACE:-0}" != 1 ]; then
        bad "preflight: на роутере свой конфиг mihomo, подписка не задана"
        info "  Либо --vpn-url '<ссылка>' (геомаск перепишет конфиг по шаблону),"
        info "  либо --adopt-config (взять текущий конфиг под управление, сохранив его),"
        info "  либо --replace-config (явная замена шаблоном)."
      else
        bad "preflight: не задана ссылка VPN-подписки"
        info "  Запустите: sh $0 --vpn-url 'https://...' --auto"
      fi
      _need=1
    fi
  fi
  if have python3 && ! python3 -c 'import yaml' >/dev/null 2>&1; then
    have apk || have opkg || { bad "preflight: нет apk/opkg - python3-yaml не поставить"; _need=1; }
  fi
  _lpm=$(lock_primitive_missing)
  [ -z "$_lpm" ] || { bad "preflight: нет примитива блокировки: $_lpm"; info "  Без него писатели отказываются изменять конфиг (fail-closed), а не работают без lock."; _need=1; }
  [ -n "$(lan_ip)" ] || { bad "preflight: не определён адрес LAN ($(lan_iface)) - слушатели некуда привязать"; _need=1; }
  return $_need
}

# ============================================================ STEP 1: env
step1_check() {
  _need=0
  # Reset first: the flag is a property of THIS check, not a sticky state from an earlier run.
  GM_STEP1_FATAL=0
  [ -f "$(P /etc/openwrt_release)" ] && info "OpenWrt: $(grep '^DISTRIB_RELEASE=' "$(P /etc/openwrt_release)" 2>/dev/null | cut -d"'" -f2)" || { bad "not OpenWrt (/etc/openwrt_release missing)"; _need=1; }
  if have apk; then info "pkg manager: apk"; elif have opkg; then info "pkg manager: opkg"; else bad "no apk/opkg"; _need=1; fi
  # v1.30.5: geomask is an overlay over mihomo, not a standalone product. Saying so here
  # means a bare/reset router stops at step 1, before a single file is written, instead of
  # installing the panel and only then reporting "mihomo binary missing" at step 3.
  if have mihomo; then info "mihomo: present"
  else bad "mihomo: MISSING - geomask is an overlay over mihomo; install mihomo first (its config, subscriptions and TUN come from it)"; _need=1; fi
  if have magitrickled || [ -f "$(P /etc/init.d/magitrickle)" ]; then info "magitrickle: present"
  else bad "magitrickle: MISSING - domain lists and per-domain routing live there; install magitrickle first"; _need=1; fi
  for c in python3 curl; do
    if have "$c"; then info "$c: present"; else warn "$c: MISSING - will be installed at apply (apk/opkg)"; _need=1; fi
  done
  # v1.30.15: PyYAML is a hard runtime dependency (slot patcher, audit state, node audit).
  # CI installed it on the runner, so a reset router without python3-yaml was never tested.
  if have python3; then
    if python3 -c 'import yaml' >/dev/null 2>&1; then info "python3-yaml: present"
    else warn "python3-yaml: MISSING - will be installed at apply (apk/opkg)"; _need=1; fi
  fi
  # R04: a fresh install must fail before step 2 if the lock primitive is missing, otherwise
  # every writer installed by the run would refuse to mutate. This is a hard refusal: the
  # interactive wizard must not go on applying steps 2-7 after it (see run_step).
  _lpm=$(lock_primitive_missing)
  [ -z "$_lpm" ] || { GM_STEP1_FATAL=1; bad "flock: MISSING ($_lpm) - geomask writers are fail-closed without it"; _need=1; }
  # the AI lane is a second hev-socks5-tunnel instance; without the binary it cannot exist
  if module_selected path_ai || module_selected ai_dns; then
    if have hev-socks5-tunnel || [ -x "$(P /usr/bin/hev-socks5-tunnel)" ]; then info "hev-socks5-tunnel: present"
    else warn "hev-socks5-tunnel: MISSING - нужен для AI-пути и AI-DNS; в фидах его нет, ставится с базовым стеком"; fi
  else
    info "hev-socks5-tunnel: не требуется выбранными модулями"
  fi
  _tmp=$(df -m "$(P /tmp)" 2>/dev/null | awk 'NR==2{print $4}')
  if [ -n "${_tmp:-}" ] && [ "$_tmp" -ge 20 ] 2>/dev/null; then info "/tmp free: ${_tmp}MB"; else warn "/tmp free low or unknown"; _need=1; fi
  _root=$(df -m "$(P /)" 2>/dev/null | awk 'NR==2{print $4}')
  if [ -n "${_root:-}" ] && [ "$_root" -ge 30 ] 2>/dev/null; then info "root free: ${_root}MB"; else warn "root free low or unknown"; _need=1; fi
  _code=$(curl -m 5 -s -o /dev/null -w '%{http_code}' http://www.gstatic.com/generate_204 2>/dev/null)
  if [ "$_code" = "204" ]; then info "internet: OK (204 via router path)"; else warn "internet check: HTTP ${_code:-none} (WAN may be down)"; _need=1; fi
  return $_need
}
# v1.30.6: python3 and curl are installed by the installer itself. A reset router has
# neither, and the owner should not have to know package names - the rest of geomask
# (sync, module updater, doctor, backend) does not run without python3.
step1_apply() {
  _missing=""
  for _c in python3 curl; do have "$_c" || _missing="$_missing $_c"; done
  # package name differs from the import name: python3-yaml provides `import yaml`.
  # Checked even when python3 itself is absent: requiring python3 first installed python3
  # and then failed the yaml verification on a bare router.
  if ! have python3 || ! python3 -c 'import yaml' >/dev/null 2>&1; then
    _missing="$_missing python3-yaml"
  fi
  if [ -z "$_missing" ]; then
    info "packages: python3 and curl already present"
    return 0
  fi
  _missing=$(echo "$_missing" | sed 's/^ *//')
  if have apk; then
    info "installing: $_missing (apk)"
    apk update >/dev/null 2>&1 || warn "apk update failed - trying the current index"
    if apk add $_missing >/dev/null 2>&1; then info "installed: $_missing"
    else bad "apk add $_missing failed - check the internet and free space"; return 1; fi
  elif have opkg; then
    info "installing: $_missing (opkg)"
    opkg update >/dev/null 2>&1 || warn "opkg update failed - trying the current index"
    if opkg install $_missing >/dev/null 2>&1; then info "installed: $_missing"
    else bad "opkg install $_missing failed - check the internet and free space"; return 1; fi
  else
    bad "no apk/opkg - install $_missing manually, then re-run"
    return 1
  fi
  for _c in python3 curl; do
    have "$_c" || { bad "$_c still missing after install"; return 1; }
  done
  if ! python3 -c 'import yaml' >/dev/null 2>&1; then
    bad "python3-yaml still missing after install - панель не сможет назначать подписки"
    return 1
  fi
  info "packages: python3, python3-yaml and curl ready"
  return 0
}
step1_verify() { step1_check; }

# ============================================================ STEP 2: geo overlay (ours)

# ============================================================ STEP 2: geo overlay (ours)
step2_check() {
  _need=0
  for f in /usr/lib/geomask/geomask-node-audit.py \
           /usr/lib/geomask/geomask-audit-state.py \
           /usr/lib/geomask/geomask-config-tx.py \
           /usr/lib/geomask/geomask-config-owner.py \
           /usr/lib/geomask/geomask-apply.py \
           /usr/lib/geomask/geomask-lane-torrent.py \
           /usr/lib/geomask/geomask-sync-youtube.py \
           /usr/lib/geomask/geomask-audit-scheduler.py \
           /usr/lib/geomask/geomask-subscription-status.py \
           /usr/lib/geomask/geomask-slot-patch.py \
           /usr/lib/geomask/geomask-console.py \
           /usr/lib/geomask/geomask-dnsguard.sh \
           /usr/lib/geomask/geomask-routes.sh; do
    if [ -s "$(P "$f")" ]; then info "present: $f"; else bad "missing: $f"; _need=1; fi
  done
  # v1.30.0: the panel is its own module; without it there is nothing to register in ubus
  if module_selected luci; then
    for f in /usr/bin/geo-backend.sh /usr/libexec/rpcd/geo-sync \
             /usr/share/rpcd/acl.d/luci-app-geo-sync.json \
             /usr/share/luci/menu.d/luci-app-geo-sync.json \
             /www/luci-static/resources/view/geo-sync/main.js; do
      if [ -s "$(P "$f")" ]; then info "present: $f"; else bad "missing: $f"; _need=1; fi
    done
    if have ubus && ubus list 2>/dev/null | grep -qx 'geo-sync'; then info "ubus geo-sync: registered"; else bad "ubus geo-sync not registered"; _need=1; fi
  else
    mod_skipped luci
  fi
  # v1.29.0: what this router is supposed to carry, and what the owner left out
  _sel=$(modules_state_read 2>/dev/null || true)
  if [ -n "$_sel" ]; then
    _off=""
    for _m in $GM_ALL_MODULES; do
      case " $_sel " in *" $_m "*) ;; *) _off="$_off $_m" ;; esac
    done
    info "модули: $_sel${_off:+ (не выбраны:$_off)}"
  else
    info "модули: выбор не записан - считаем, что выбраны все"
  fi
  if module_selected backup_share; then
    if [ -e "$(P /etc/ksmbd/ksmbd.conf)" ]; then
      # The share is published only after an explicit opt-in. Without the marker its absence
      # is the expected state: requiring it here made --auto fail step 2 on every fresh
      # system with ksmbd installed, because apply deliberately creates nothing (F15).
      if [ -f "$(P $SMB_SHARE_ENABLE)" ]; then
        if grep -qF "[$SMB_SHARE_NAME]" "$(P /etc/ksmbd/ksmbd.conf)" 2>/dev/null; then
          info "SMB share $SMB_SHARE_NAME: present"
        else
          bad "SMB share $SMB_SHARE_NAME missing (opt-in marker exists)"; _need=1
        fi
      else
        info "SMB share: автопубликация выключена (opt-in: touch $SMB_SHARE_ENABLE) - проверка пропущена"
      fi
    fi
  else
    info "пропущен: SMB-шар с бэкапами (модуль 'backup_share' не выбран)"
  fi
  return $_need
}
# R10b: the guard now reports a missing /etc/geo-devices.list as "per-device state unknown"
# (rc 2) instead of silently skipping the device blocks. The list used to appear only on the
# first dev_add, so a fresh install had no file at all and "damaged" was indistinguishable
# from "normal". Create an EMPTY list on install; an existing list is owner data and is never
# truncated - install and reinstall both only fill the gap.
ensure_devices_list() {
  _edl=$(P /etc/geo-devices.list)
  if [ -L "$_edl" ]; then
    warn "$_edl is a symlink - refusing to create the device list through it"
    return 1
  fi
  if [ -e "$_edl" ]; then
    chmod 600 "$_edl" 2>/dev/null || true
    return 0
  fi
  ( umask 077; : > "$_edl" ) 2>/dev/null || {
    warn "cannot create the empty device list $_edl"
    return 1
  }
  chmod 600 "$_edl" 2>/dev/null || true
  chown root:root "$_edl" 2>/dev/null || true
  return 0
}

step2_apply() {
  _save_before=${SAVE_FAIL:-0}
  # Before the assets, so a failure here aborts before any service file is replaced.
  ensure_devices_list || { bad "не удалось создать пустой список устройств"; return 1; }
  save_stream /usr/lib/geomask/geomask-node-audit.py 755 <<'ASSET_EOF'
#!/usr/bin/env python3
"""Independent desired country filters and isolated service-egress observations.
Schema v2: independent path revisions, source bindings, events, immutable pools.
Never applies filters to production. Unknown service geography is not admission.
"""
import argparse
import contextlib
import datetime
import hashlib
import ipaddress
import json
import os
from pathlib import Path
import re
import secrets
import shutil
import socket
import subprocess
import sys
import tempfile
import time
import urllib.parse
import urllib.request

# Load state module
import importlib.util
STATE_MODULE_PATH = Path(__file__).with_name('geomask-audit-state.py')
_state_spec = importlib.util.spec_from_file_location('audit_state', STATE_MODULE_PATH)
_state = importlib.util.module_from_spec(_state_spec)
_state_spec.loader.exec_module(_state)

# Path constants (can be patched by tests)
STORE = Path(os.environ.get('GM_AUDIT_STORE', '/etc/geomask/node-audit.json'))
STATE = Path(os.environ.get('GM_AUDIT_STATE', '/etc/geomask/node-audit/state'))
STATE = STATE  # alias for backward compat
CONFIG = Path(os.environ.get('GM_AUDIT_CONFIG', '/etc/mihomo/config.yaml'))
RECEIPT = Path(os.environ.get('GM_AUDIT_RECEIPT', '/tmp/geomask-node-audit-receipt.json'))
EVENTS = Path(os.environ.get('GM_AUDIT_EVENTS', '/etc/geomask/node-audit/events.jsonl'))
POOLS_DIR = Path(os.environ.get('GM_AUDIT_POOLS', '/etc/geomask/node-audit/pools'))
MAX_NODES = _state.MAX_NODES
REGISTRY = Path(os.environ.get('GM_AUDIT_REGISTRY', '/etc/geomask-subs.list'))

# Re-export from state module
PATHS = _state.PATHS

# Backward compat: atomic function
atomic = _state.atomic_write

AuditError = _state.AuditError
stamp = _state.stamp
_save_node_snapshot = _state.save_node_snapshot
load_node_snapshot = _state.load_node_snapshot
digest = _state.digest
encode = _state.encode
canonical_json = _state.canonical_json
strict_json = _state.strict_json
path_id = _state.path_id
countries = _state.countries
locked = _state.locked
atomic_write = _state.atomic_write

# State module functions with explicit path parameters
def _load_store():
    return _state.load_store(STORE)

def _save_store(data):
    return _state.save_store(data, STORE)

def _append_event(event):
    return _state.append_event(event, EVENTS)

def _get_events(path=None, before=None, limit=50):
    return _state.get_events(path, before, limit, EVENTS)

def _load_pool(path_id, generation):
    return _state.load_pool(path_id, generation, POOLS_DIR)

def _save_pool(path_id, generation, pool_data):
    return _state.save_pool(path_id, generation, pool_data, POOLS_DIR)

def _resolve_source_binding(config, ident, providers=None):
    return _state.resolve_source_binding(config, ident, providers)

def _compute_path_revision(path_data):
    return _state.compute_path_revision(path_data)

# Backward compat: expose load_store
load_store = _load_store

# Reports directory
REPORTS_DIR = Path(os.environ.get('GM_AUDIT_REPORTS', '/etc/geomask/node-audit/reports'))

# State module functions with explicit path parameters
def _save_report(report):
    return _state.save_report(report, REPORTS_DIR)

def _list_reports(path_id=None, limit=50):
    return _state.list_reports(path_id, limit, REPORTS_DIR)

# Legacy constants for backward compatibility
REVISION_KEY = 'revision'  # whole-store digest for legacy RPC

def boot_id():
    return Path('/proc/sys/kernel/random/boot_id').read_text().strip()

def render_save(data, ident, allow):
    """Legacy render for backward compatibility with prepare-save."""
    result = json.loads(json.dumps(data))
    result['paths'].setdefault(ident, {})['countries_allow'] = allow
    result['generation'] = result.get('generation', 0) + 1
    return encode(result)

def prepare_save(ident, value, expected):
    """Legacy prepare-save: validates countries, returns candidate info using path_revision."""
    ident, allow = path_id(ident), countries(value)
    data, original_raw = _load_store()
    # Legacy: expected is whole-store revision, but we now use path_revision
    # Compute current whole-store digest for backward compat
    current_revision = digest(original_raw) if original_raw else digest(encode(data))
    if expected != current_revision:
        raise AuditError('STALE: reload settings before saving')
    # Check if change would actually modify anything
    current_allow = data['paths'].get(ident, {}).get('countries_allow', PATHS[ident][1])
    changed = current_allow != allow
    candidate = render_save(data, ident, allow) if changed else None
    return {'ok': True, 'before_sha256': current_revision,
            'candidate_sha256': digest(candidate) if candidate else '',
            'boot_id': boot_id(), 'path_id': ident, 'changed': changed}

def save(ident, value, expected):
    """Save countries for a path using path_revision (v2) or whole-store revision (legacy)."""
    ident, allow = path_id(ident), countries(value)
    with locked('settings'):
        data, original_raw = _load_store()
        # Check revision: try path_revision first, fall back to whole-store for legacy
        current_revision = digest(original_raw) if original_raw else digest(encode(data))
        path_rev = data['paths'].get(ident, {}).get('path_revision', '')
        
        revision_ok = False
        if expected == path_rev:
            revision_ok = True
        elif expected == current_revision:
            # Legacy whole-store revision
            revision_ok = True
        if not revision_ok:
            raise AuditError('STALE: reload settings before saving')
        
        # No-op check
        current_allow = data['paths'].get(ident, {}).get('countries_allow', PATHS[ident][1])
        if current_allow == allow:
            return {'ok': True, 'changed': False, 'revision': path_rev or current_revision, 'applied': False}
        
        # Update path data
        data['paths'][ident]['countries_allow'] = allow
        data['paths'][ident]['path_revision'] = _compute_path_revision(data['paths'][ident])
        data['paths'][ident]['path_generation'] = data['paths'][ident].get('path_generation', 0) + 1
        data['paths'][ident]['configured'] = True
        
        _save_store(data)
        _append_event({
            'path': ident,
            'actor': 'luci',
            'action': 'save',
            'old_countries': current_allow,
            'new_countries': allow,
            'path_revision': data['paths'][ident]['path_revision'],
            'path_generation': data['paths'][ident]['path_generation'],
            'result': 'success'
        })
        return {'ok': True, 'changed': True, 'revision': data['paths'][ident]['path_revision'], 'applied': False}

def yaml_load(raw):
    import yaml
    try:
        value = _state.yaml12_load(raw)
        if not isinstance(value, dict):
            raise AuditError('expected YAML mapping')
        return value
    except yaml.YAMLError:
        raise AuditError('invalid YAML source') from None

def resolve_source(config, ident):
    """Legacy: returns group_name and provider_ids."""
    group_name = PATHS[path_id(ident)][0]
    matches = [g for g in config.get('proxy-groups', []) if g.get('name') == group_name]
    if len(matches) != 1:
        raise AuditError('missing or duplicate target group')
    providers = matches[0].get('use')
    if not isinstance(providers, list) or not 1 <= len(providers) <= 3 or any(not isinstance(p, str) for p in providers):
        raise AuditError('target group requires provider use list')
    registry = config.get('proxy-providers') or {}
    if any(p not in registry for p in providers):
        raise AuditError('target provider missing')
    return group_name, list(dict.fromkeys(providers))

MANAGED_PREFIX = 'audit-'

def resolve_audit_source(config, ident, path_data=None, previous_report=None):
    """Resolve the subscription this path audits, even while it is applied.

    An apply replaces the group's source with a managed file provider. Resolving naively
    would then point the next check at our own frozen pool, so an applied path could never
    be audited again -- and the nightly run would fail on it forever. The original
    providers are recorded at apply time and in the last report; use those.
    """
    group_name, providers = resolve_source(config, ident)
    managed = [p for p in providers if p.startswith(MANAGED_PREFIX)]
    if not managed:
        return group_name, providers

    recorded = ((path_data or {}).get('applied') or {}).get('previous_use') or []
    if not recorded and previous_report:
        recorded = [p for p in (previous_report.get('providers') or [])
                    if not str(p).startswith(MANAGED_PREFIX)]
    registry = config.get('proxy-providers') or {}
    usable = [p for p in recorded if p in registry]
    if not usable:
        raise AuditError('path is applied to a managed pool and its original source is not '
                         'recorded in the mihomo config; refusing to audit the frozen pool')
    return group_name, list(dict.fromkeys(usable))

def get():
    """Get all paths with v2 state: path_revision, source_binding, schedule, applied."""
    data, original_raw = _load_store()
    current_source = None
    config = {}
    try:
        current_raw = CONFIG.read_bytes()
        current_source = digest(current_raw)
        config = yaml_load(current_raw)
    except (OSError, AuditError):
        pass

    # The revision handed to the UI must be the same value save() compares against,
    # otherwise an un-migrated store can never be written.
    revision = digest(original_raw) if original_raw else digest(encode(data))

    result = []
    for ident, (label, defaults) in PATHS.items():
        path_data = data['paths'].get(ident, {})
        configured = path_data.get('configured', False)

        report = None
        state_file = STATE / (ident + '.json')
        if state_file.exists():
            try:
                report = strict_json(state_file.read_bytes())
            except (AuditError, OSError):
                report = {'status': 'error', 'error': 'unreadable report'}

        try:
            # Resolve the subscription this path audits, not our own frozen pool.
            _, providers = resolve_audit_source(config, ident, path_data, report)
            binding = _resolve_source_binding(config, ident, providers)
            source_revision = binding.get('source_fingerprint') if binding else None
        except AuditError:
            providers = []
            binding = None
            source_revision = None

        if report and report.get('status') != 'error':
            stale = False
            if report.get('settings_revision') != path_data.get('path_revision', ''):
                stale = True
            if current_source and report.get('source_revision') != current_source:
                stale = True
            if stale:
                report = dict(report, stale=True)

        applied = path_data.get('applied', {})
        applied_bool = applied.get('status') in ('applied', 'applying')
        result.append({
            'id': ident,
            'label': label,
            'providers': providers,
            'source_binding': binding,
            'source_revision': source_revision,
            'configured': configured,
            'countries_allow': path_data.get('countries_allow', defaults),
            'path_revision': path_data.get('path_revision', ''),
            'path_generation': path_data.get('path_generation', 0),
            'schedule': path_data.get('schedule', {'enabled': False, 'time': '03:30',
                                                   'mode': 'check-only'}),
            'applied': applied_bool,
            'applied_detail': {
                'generation': applied.get('generation', 0),
                'path_revision': applied.get('path_revision', ''),
                'runtime_verified': applied.get('runtime_verified', False),
                'status': applied.get('status', 'never'),
                'applied_at': applied.get('applied_at', ''),
                'node_count': applied.get('node_count', 0),
                'pool_digest': applied.get('pool_digest', ''),
                'acting_countries': applied.get('acting_countries') or [],
                'provider_id': applied.get('provider_id', ''),
            },
            'report': report,
        })

    return {
        'ok': True,
        'api_schema': 2,
        'revision': revision,
        'paths': result,
        'apply_supported': True,
        'scope': 'desired filters, isolated observations, and explicit per-path apply',
    }

def fetch_nodes(provider):
    url = provider.get('url', '')
    if not isinstance(url, str) or urllib.parse.urlsplit(url).scheme != 'https':
        raise AuditError('provider must use HTTPS for the isolated audit')
    parsed = urllib.parse.urlsplit(url)
    if not parsed.hostname or parsed.username or parsed.password:
        raise AuditError('invalid provider endpoint')
    try:
        addresses = socket.getaddrinfo(parsed.hostname, parsed.port or 443, type=socket.SOCK_STREAM)
        if not addresses or any(not ipaddress.ip_address(item[4][0]).is_global for item in addresses):
            raise AuditError('non-public subscription endpoint is not supported')
    except OSError:
        raise AuditError('subscription hostname could not be resolved') from None
    headers = {'User-Agent': 'clash-meta'}
    for key, value in (provider.get('header') or {}).items():
        headers[key] = str(value[0] if isinstance(value, list) else value)
    headers['User-Agent'] = 'clash-meta'
    try:
        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, req, fp, code, msg, hdrs, newurl):
                raise AuditError('subscription redirect refused; no credentials forwarded')
        opener = urllib.request.build_opener(NoRedirect)
        with opener.open(urllib.request.Request(url, headers=headers), timeout=30) as response:
            raw = response.read(2_000_001)
        if len(raw) > 2_000_000:
            raise AuditError('subscription too large')
        nodes = yaml_load(raw).get('proxies')
    except Exception as exc:
        if isinstance(exc, AuditError):
            raise
        raise AuditError('subscription request failed (' + type(exc).__name__ + ')') from None
    if not isinstance(nodes, list) or not 3 <= len(nodes) <= MAX_NODES:
        raise AuditError('unexpected subscription node count (expected 3..100)')
    names = set()
    for node in nodes:
        if not isinstance(node, dict) or not isinstance(node.get('name'), str) or not node.get('server'):
            raise AuditError('malformed subscription node')
        name = node['name']
        if name in names or any(ord(char) < 32 for char in name):
            raise AuditError('duplicate or invalid node name')
        names.add(name)
    return nodes, digest(raw)

# AI admission criterion, decided by the owner on 09.11.2026: a node is judged by the
# services whose geography it can actually report. Google does not disclose a country in any
# machine-readable form -- a real SERP fetched through a verified node carried no uule, no
# region/countryCode/country/gl field, no data-country and no "Google offered in" -- so
# requiring it would block every node forever while proving nothing about where it exits.
AI_REQUIRED_SERVICES = ['cloudflare', 'chatgpt']
# Probed and recorded, never used as a gate. The report says "unmeasurable", not "failed".
AI_INFORMATIONAL_SERVICES = ['google']

# Bumped when the measuring method changes; a report carries it so a later reader can tell
# which findings were produced by which method instead of comparing unlike numbers.
PROBE_VERSION = 'service-egress-2'

def classify(ident, allow, probes):
    required = AI_REQUIRED_SERVICES if ident == 'ai' else ['cloudflare']
    reasons = []
    unknown = False
    failed = False
    for service in required:
        probe = probes.get(service, {})
        country = probe.get('country')
        if probe.get('status') != 'ok' or not country:
            unknown = True
            reasons.append(service + ': geography unknown or probe failed')
        elif country not in allow:
            failed = True
            reasons.append(service + ': ' + country + ' not allowed')
    status = 'excluded' if failed else 'unknown' if unknown else 'eligible'
    result = {'status': status, 'reasons': reasons, 'admitted': status == 'eligible'}
    if ident == 'ai':
        # Recorded so the panel can say what is known and what simply cannot be measured.
        informational = {}
        for service in AI_INFORMATIONAL_SERVICES:
            probe = probes.get(service) or {}
            country = probe.get('country')
            informational[service] = {
                'measured': bool(country),
                'country': country or None,
                'policy': 'not-required',
            }
        result['informational'] = informational
    return result

def free_port():
    with socket.socket() as sock:
        sock.bind(('127.0.0.1', 0))
        return sock.getsockname()[1]

class IsolatedProbe:
    def __init__(self, nodes):
        self.nodes = nodes
        self.work = None
        self.process = None
        self.watchdog = None
        self.port = free_port()
        self.api_port = free_port()
        self.secret = secrets.token_hex(24)

    def api(self, path, value=None):
        headers = {'Authorization': 'Bearer ' + self.secret}
        if value is not None:
            headers['Content-Type'] = 'application/json'
        request = urllib.request.Request('http://127.0.0.1:' + str(self.api_port) + path,
            data=json.dumps(value).encode() if value is not None else None,
            method='PUT' if value is not None else 'GET', headers=headers)
        with urllib.request.urlopen(request, timeout=8) as response:
            raw = response.read()
            return json.loads(raw) if raw else {}

    def __enter__(self):
        import yaml
        self.work = Path(tempfile.mkdtemp(prefix='geomask-egress-', dir=str(STATE)))
        try:
            os.chmod(self.work, 0o700)
            config = {'mixed-port': 0, 'allow-lan': False, 'bind-address': '127.0.0.1',
                'external-controller': '127.0.0.1:' + str(self.api_port), 'secret': self.secret,
                'mode': 'rule', 'log-level': 'silent', 'ipv6': False,
                'listeners': [{'name': 'isolated-audit', 'type': 'mixed', 'listen': '127.0.0.1',
                               'port': self.port, 'proxy': 'AUDIT'}],
                'proxies': self.nodes,
                'proxy-groups': [{'name': 'AUDIT', 'type': 'select', 'proxies': [n['name'] for n in self.nodes]}],
                'rules': ['MATCH,AUDIT']}
            candidate = self.work / 'config.yaml'
            candidate.write_text(yaml.safe_dump(config, allow_unicode=True, sort_keys=False), encoding='utf-8')
            os.chmod(candidate, 0o600)
            checked = subprocess.run(['mihomo', '-d', str(self.work), '-f', str(candidate), '-t'],
                                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=45)
            if checked.returncode:
                raise AuditError('isolated candidate validation failed')
            self.process = subprocess.Popen(['mihomo', '-d', str(self.work), '-f', str(candidate)],
                                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            self._watch()
            for _ in range(40):
                if self.process.poll() is not None:
                    break
                try:
                    self.api('/version')
                    return self
                except Exception:
                    time.sleep(0.2)
            raise AuditError('isolated controller did not start')
        except Exception:
            self.__exit__(None, None, None)
            raise

    def _watch(self):
        pid = self.process.pid
        proc = Path('/proc') / str(pid)
        identity = (proc / 'stat').read_text().split(') ', 1)[1].split()[19]
        work = str(self.work)
        child = os.fork()
        if child == 0:
            try:
                time.sleep(900)
                current = (proc / 'stat').read_text().split(') ', 1)[1].split()[19]
                command = (proc / 'cmdline').read_bytes()
                if current == identity and work.encode() in command and b'mihomo' in command:
                    os.kill(pid, 15)
                    time.sleep(5)
                    current = (proc / 'stat').read_text().split(') ', 1)[1].split()[19]
                    command = (proc / 'cmdline').read_bytes()
                    if current == identity and work.encode() in command and b'mihomo' in command:
                        os.kill(pid, 9)
            except (OSError, ValueError):
                pass
            finally:
                shutil.rmtree(work, ignore_errors=True)
            os._exit(0)
        self.watchdog = child

    def probe(self, node, service):
        endpoints = {'cloudflare': 'https://www.cloudflare.com/cdn-cgi/trace',
                     'chatgpt': 'https://chatgpt.com/cdn-cgi/trace',
                     'google': 'https://www.google.com/generate_204'}
        self.api('/proxies/AUDIT', {'name': node})
        args = ['curl', '--disable', '--silent', '--show-error', '--noproxy', '', '--connect-timeout', '6',
                '--max-time', '12', '--max-filesize', '16000', '--proxy',
                'socks5h://127.0.0.1:' + str(self.port), '--write-out', '\nhttp_code=%{http_code}\n',
                endpoints[service] + '?_=' + secrets.token_hex(6)]
        result = subprocess.run(args, capture_output=True, text=True, timeout=15)
        fields = dict(re.findall(r'(?m)^(ip|loc|colo|http_code)=([^\r\n]+)', result.stdout))
        code = fields.get('http_code')
        if service == 'google':
            return {'status': 'unknown', 'availability': result.returncode == 0 and code == '204',
                    'country': None, 'http_code': code, 'reason': 'HTTP 204 does not prove Google geography',
                    'dns_context': 'remote SOCKS5h', 'time': stamp()}
        country = fields.get('loc')
        if result.returncode or code != '200' or not re.fullmatch(r'[A-Z]{2}', country or ''):
            return {'status': 'unknown', 'country': None, 'http_code': code,
                    'reason': 'trace unavailable or malformed', 'time': stamp()}
        try:
            ipaddress.ip_address(fields.get('ip', ''))
        except ValueError:
            return {'status': 'unknown', 'country': None, 'reason': 'invalid observed exit IP'}
        return {'status': 'ok', 'country': country, 'ip': fields['ip'], 'colo': fields.get('colo'),
                'http_code': code, 'dns_context': 'remote SOCKS5h', 'time': stamp(), 'tls_verified': True}

    def __exit__(self, *unused):
        if self.process is not None and self.process.poll() is None:
            self.process.terminate()
            try:
                self.process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                self.process.kill()
                self.process.wait()
        if self.watchdog:
            try:
                os.kill(self.watchdog, 15)
                os.waitpid(self.watchdog, 0)
            except ProcessLookupError:
                pass
        if self.work:
            shutil.rmtree(self.work, ignore_errors=True)

@contextlib.contextmanager
def job_budget(seconds):
    import signal
    deadline = time.monotonic() + seconds
    if not hasattr(signal, 'SIGALRM'):
        yield deadline
        return
    def expired(signum, frame):
        raise AuditError('whole-job time budget exceeded; partial results are not a pass')
    previous = signal.signal(signal.SIGALRM, expired)
    signal.alarm(seconds)
    try:
        yield deadline
    finally:
        signal.alarm(0)
        signal.signal(signal.SIGALRM, previous)

@contextlib.contextmanager
def audit_locks(ident):
    with locked('runtime', nonblocking=True), locked('job-' + ident, nonblocking=True):
        yield

def check(ident, owns_lock=False, job_id=None, actor='cli'):
    path_id(ident)
    lock = contextlib.nullcontext() if owns_lock else audit_locks(ident)
    with lock, job_budget(720) as deadline:
        data, _ = _load_store()
        path_data = data['paths'].get(ident, {})
        raw = CONFIG.read_bytes()
        config = yaml_load(raw)
        target = STATE / (ident + '.json')
        previous_report = None
        try:
            previous_report = strict_json(target.read_bytes()) if target.exists() else None
        except (OSError, AuditError):
            previous_report = None
        group, providers = resolve_audit_source(config, ident, path_data, previous_report)
        allow = path_data.get('countries_allow', PATHS[ident][1])
        path_rev = path_data.get('path_revision', '')
        binding = _resolve_source_binding(config, ident, providers)
        source_fingerprint = binding.get('source_fingerprint') if binding else None
        # Use whole config digest for staleness (matches original behavior and tests)
        config_digest = digest(raw)
        
        report = {'job_id': job_id or secrets.token_hex(12), 'path_id': ident, 'group': group, 'providers': providers, 
                  'settings_revision': path_rev, 'source_revision': config_digest, 'countries_allow': allow, 'started': stamp(),
                  'status': 'running', 'applied': False, 'nodes': [],
                  'configured': ident in data['paths'],
                  'probe_version': PROBE_VERSION,
                  'probe_context': {'dns': 'remote SOCKS5h', 'services': (
                      AI_REQUIRED_SERVICES + AI_INFORMATIONAL_SERVICES if ident == 'ai'
                      else ['cloudflare']),
                      'admission': ('chatgpt+cloudflare' if ident == 'ai' else 'cloudflare')},
                  'scope': 'observed service egress with remote DNS; not actual client/hosts route',
                  'limit': 'No automatic apply. Google geography is not measurable and is not '
                           'used for admission; AI is judged by ChatGPT and Cloudflare. '
                           'No claim for untested services.'}
        atomic_write(target, encode(report))
        audited_definitions = {}
        try:
            for provider_name in providers:
                nodes, source = fetch_nodes(config['proxy-providers'][provider_name])
                with IsolatedProbe(nodes) as probe:
                    for node in nodes:
                        if time.monotonic() > deadline:
                            raise AuditError('audit time budget exceeded; partial results are not a pass')
                        # Check for cancellation request
                        try:
                            current_report = strict_json(target.read_bytes())
                            if current_report.get('status') == 'cancelled':
                                report['status'] = 'cancelled'
                                report['ok'] = False
                                report['error'] = 'cancelled by user'
                                report['finished'] = stamp()
                                atomic_write(target, encode(report))
                                _append_event({
                                    'path': ident,
                                    'actor': actor,
                                    'action': 'cancel',
                                    'job_id': report['job_id'],
                                    'result': 'success'
                                })
                                return report
                        except (OSError, AuditError):
                            pass
                        services = (AI_REQUIRED_SERVICES + AI_INFORMATIONAL_SERVICES
                                    if ident == 'ai' else ['cloudflare'])
                        observations = {}
                        for service in services:
                            try:
                                observations[service] = probe.probe(node['name'], service)
                            except Exception as exc:
                                observations[service] = {'status': 'unknown', 'country': None,
                                                         'reason': 'probe error (' + type(exc).__name__ + ')'}
                        # Compute node identity fingerprint. The whole definition is covered:
                        # a hand-picked subset would let a rewritten credential keep the
                        # fingerprint of the node that was actually measured.
                        node_identity = {
                            'definition': node,
                            'provider_id': provider_name,
                        }
                        node_fingerprint = digest(canonical_json(node_identity))
                        audited_definitions[node['name']] = {
                            'provider': provider_name,
                            'node_fingerprint': node_fingerprint[:16],
                            'definition': node,
                        }
                        report['nodes'].append({'name': node['name'], 'provider': provider_name,
                            'node_fingerprint': node_fingerprint[:16], 'source_digest': source, 'probes': observations, **classify(ident, allow, observations)})
                        atomic_write(target, encode(report))
            # Check staleness using path_revision and config digest (matches original behavior)
            current_data, _ = _load_store()
            current_path_rev = current_data['paths'].get(ident, {}).get('path_revision', '')
            current_config_raw = CONFIG.read_bytes()
            current_config_digest = digest(current_config_raw)
            stale = current_path_rev != path_rev or current_config_digest != config_digest
            report['stale'] = stale
            report['status'] = 'stale' if stale else 'complete'
            report['counts'] = {key: sum(n['status'] == key for n in report['nodes'])
                                for key in ('eligible', 'excluded', 'unknown')}
            present = {p.get('country') for n in report['nodes'] for p in n['probes'].values()}
            report['missing_countries'] = sorted(set(allow) - present)
            report['ok'] = not stale
        except Exception as exc:
            report['status'] = 'error'
            report['ok'] = False
            report['error'] = str(exc) if isinstance(exc, AuditError) else type(exc).__name__
        report['finished'] = stamp()
        atomic_write(target, encode(report))
        # Save immutable report
        _save_report(report)
        # Persist the exact definitions that were probed, so an apply can build a managed
        # provider from what was actually measured instead of re-reading a moving source.
        if report.get('status') in ('complete', 'stale') and audited_definitions:
            # Keep the snapshots an applied manifest or the previous report still refer to;
            # retention must not delete material a pending preview or a pool depends on.
            protected = [path_data.get('applied', {}).get('job_id', '')]
            if previous_report:
                protected.append(previous_report.get('job_id', ''))
            _save_node_snapshot(ident, report['job_id'], audited_definitions,
                                protect=protected)
        # Append event
        _append_event({
            'path': ident,
            'actor': actor,
            'action': 'check',
            'job_id': report['job_id'],
            'status': report['status'],
            'counts': report.get('counts', {}),
            'stale': report.get('stale', False),
            'result': 'success' if report.get('ok') else 'failed'
        })
        return report

def start(ident, actor='luci'):
    path_id(ident)
    with audit_locks(ident):
        data, _ = _load_store()
        path_data = data['paths'].get(ident, {})
        raw = CONFIG.read_bytes()
        config = yaml_load(raw)
        resolve_source(config, ident)
        job_id = secrets.token_hex(12)
        queued = {'job_id': job_id, 'path_id': ident, 'status': 'queued', 'started': stamp(),
                  'settings_revision': path_data.get('path_revision', ''), 'source_revision': digest(raw), 'applied': False}
        atomic_write(STATE / (ident + '.json'), encode(queued))
        try:
            child = os.fork()
        except OSError:
            queued.update(status='error', ok=False, finished=stamp(), error='worker fork failed')
            atomic_write(STATE / (ident + '.json'), encode(queued))
            raise AuditError('worker fork failed') from None
        if child == 0:
            try:
                os.setsid()
                with open(os.devnull, 'r+b', buffering=0) as null:
                    for descriptor in (0, 1, 2):
                        os.dup2(null.fileno(), descriptor)
                # The parent releases its reservation when start() returns, so the worker
                # waits for it rather than racing it, then owns the slot for its own run.
                with locked('runtime'), locked('job-' + ident):
                    check(ident, owns_lock=True, job_id=job_id, actor=actor)
            except Exception as exc:
                queued.update(status='error', ok=False, finished=stamp(),
                              error=str(exc) if isinstance(exc, AuditError) else type(exc).__name__)
                atomic_write(STATE / (ident + '.json'), encode(queued))
            finally:
                os._exit(0)
        return {'ok': True, 'started': True, 'job_id': job_id, 'path_id': ident, 'applied': False}

def source_in_use(url):
    """Report whether a subscription URL backs a provider some group actually uses.

    Deleting a registry entry that a path still depends on would leave the group pointing
    at a provider whose source is gone. The caller refuses the delete on a hit.
    """
    if not isinstance(url, str) or not url:
        raise AuditError('source url required')
    try:
        config = yaml_load(CONFIG.read_bytes())
    except OSError:
        raise AuditError('mihomo config is unreadable') from None
    providers = config.get('proxy-providers') or {}
    used = set()
    for group in config.get('proxy-groups') or []:
        for provider_id in group.get('use') or []:
            used.add(provider_id)
    hits = sorted(pid for pid, spec in providers.items()
                  if isinstance(spec, dict) and spec.get('url') == url and pid in used)
    return {'ok': True, 'in_use': bool(hits), 'providers': hits}


def audit_events_get(path_id=None, before=None, limit=50):
    """Get paginated audit events."""
    events = _get_events(path_id, before, min(int(limit), 100))
    return {'ok': True, 'events': events}

def audit_job_get(job_id):
    """Get job status by job_id. Searches all path state files."""
    try:
        for state_file in STATE.glob('*.json'):
            report = strict_json(state_file.read_bytes())
            if report.get('job_id') == job_id:
                return {'ok': True, 'job': report}
        return {'ok': False, 'error': 'job not found'}
    except Exception as exc:
        return {'ok': False, 'error': str(exc)}

def audit_cancel(job_id, actor='luci'):
    """Cancel a running job by job_id. Only works for queued/running jobs."""
    try:
        for state_file in STATE.glob('*.json'):
            report = strict_json(state_file.read_bytes())
            if report.get('job_id') == job_id:
                status = report.get('status', '')
                if status in ('queued', 'running'):
                    report['status'] = 'cancelled'
                    report['ok'] = False
                    report['finished'] = stamp()
                    report['error'] = 'cancelled by user'
                    atomic_write(state_file, encode(report))
                    _append_event({
                        'path': report.get('path_id', ''),
                        'actor': actor,
                        'action': 'cancel',
                        'job_id': job_id,
                        'result': 'success'
                    })
                    return {'ok': True, 'cancelled': True}
                else:
                    return {'ok': False, 'error': f'job not cancellable (status: {status})'}
        return {'ok': False, 'error': 'job not found'}
    except Exception as exc:
        return {'ok': False, 'error': str(exc)}

def schedule_get(pid):
    """Get schedule configuration for a path."""
    try:
        path_id(pid)
    except AuditError as e:
        return {'ok': False, 'error': str(e)}
    data, _ = load_store()
    path_data = data['paths'].get(pid, {})
    schedule = path_data.get('schedule', {'enabled': False, 'time': '03:30', 'mode': 'check-only'})
    return {'ok': True, 'schedule': schedule}

def schedule_set(pid, enabled, time, mode):
    """Set schedule configuration for a path."""
    path_id(pid)
    if enabled not in ('true', 'false'):
        raise AuditError('enabled must be true or false')
    if not re.fullmatch(r'([01]?[0-9]|2[0-3]):[0-5][0-9]', time):
        raise AuditError('time must be HH:MM format')
    if mode not in ('check-only', 'check-and-apply'):
        raise AuditError('mode must be check-only or check-and-apply')
    
    with locked('settings'):
        data, _ = load_store()
        path_data = data['paths'].get(pid, {})
        path_data['schedule'] = {
            'enabled': enabled == 'true',
            'time': time,
            'mode': mode,
        }
        _save_store(data)
        _append_event({
            'path': pid,
            'actor': 'luci',
            'action': 'schedule-set',
            'enabled': enabled == 'true',
            'time': time,
            'mode': mode,
            'result': 'success'
        })
        return {'ok': True, 'schedule': path_data['schedule']}

def audit_cancel(job_id, actor='luci'):
    """Cancel a running job by job_id. Only works for queued/running jobs."""
    try:
        for state_file in STATE.glob('*.json'):
            report = strict_json(state_file.read_bytes())
            if report.get('job_id') == job_id:
                status = report.get('status', '')
                if status in ('queued', 'running'):
                    report['status'] = 'cancelled'
                    report['ok'] = False
                    report['finished'] = stamp()
                    report['error'] = 'cancelled by user'
                    atomic_write(state_file, encode(report))
                    _append_event({
                        'path': report.get('path_id', ''),
                        'actor': actor,
                        'action': 'cancel',
                        'job_id': job_id,
                        'result': 'success'
                    })
                    return {'ok': True, 'cancelled': True}
                else:
                    return {'ok': False, 'error': f'job not cancellable (status: {status})'}
        return {'ok': False, 'error': 'job not found'}
    except Exception as exc:
        return {'ok': False, 'error': str(exc)}

def validate_rpc(method, raw):
    if len(raw.encode('utf-8')) > 16384:
        raise AuditError('RPC request too large')
    fields = {'nodes_paths_get': set(), 'nodes_path_check': {'path_id'},
              'nodes_path_save': {'path_id', 'countries', 'expected_revision'},
              'nodes_audit_job_get': {'job_id'},
              'nodes_audit_cancel': {'job_id'},
              'nodes_audit_events_get': {'path_id', 'before', 'limit'},
              'nodes_audit_schedule_get': {'path_id'},
              'nodes_audit_schedule_set': {'path_id', 'enabled', 'time', 'mode'}}
    if method not in fields:
        raise AuditError('unknown audit RPC')
    request = strict_json(raw)
    if not isinstance(request, dict):
        raise AuditError('invalid RPC object')
    has_session = 'ubus_rpc_session' in request
    session = request.pop('ubus_rpc_session', None)
    if has_session and (not isinstance(session, str) or not re.fullmatch(r'[a-f0-9]{32}', session)):
        raise AuditError('invalid RPC session metadata')
    if set(request) != fields[method]:
        raise AuditError('invalid RPC fields')
    for value in request.values():
        if not isinstance(value, str) or any(ord(char) < 32 or 127 <= ord(char) <= 159 for char in value):
            raise AuditError('RPC values must be strings without controls')
    if 'path_id' in request:
        path_id(request['path_id'])
    if 'countries' in request:
        countries(request['countries'])
        if not re.fullmatch(r'[a-f0-9]{64}', request['expected_revision']):
            raise AuditError('invalid revision')
    if 'job_id' in request and not re.fullmatch(r'[a-f0-9]{24}', request['job_id']):
        raise AuditError('invalid job_id')
    if 'enabled' in request and request['enabled'] not in ('true', 'false'):
        return {'ok': False, 'error': 'enabled must be true or false'}
    if 'time' in request and not re.fullmatch(r'([01]?[0-9]|2[0-3]):[0-5][0-9]', request['time']):
        return {'ok': False, 'error': 'time must be HH:MM format'}
    if 'mode' in request and request['mode'] not in ('check-only', 'check-and-apply'):
        return {'ok': False, 'error': 'mode must be check-only or check-and-apply'}
    return {'ok': True}

def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument('command', choices=['get', 'save', 'check', 'start', 'validate-rpc', 'prepare-save', 'audit-events', 'audit-job', 'audit-cancel', 'schedule-get', 'schedule-set', 'source-in-use'])
    parser.add_argument('args', nargs='*')
    args = parser.parse_args(argv)
    try:
        if args.command == 'validate-rpc' and len(args.args) == 1:
            value = validate_rpc(args.args[0], sys.stdin.read(16385))
        elif args.command == 'get' and not args.args:
            value = get()
        elif args.command == 'prepare-save' and len(args.args) == 3:
            value = prepare_save(*args.args)
        elif args.command == 'save' and len(args.args) == 3:
            value = save(*args.args)
        elif args.command == 'start' and len(args.args) == 1:
            value = start(args.args[0], actor='cli')
        elif args.command == 'check' and len(args.args) == 1:
            value = check(args.args[0], actor='cli')
        elif args.command == 'audit-events' and len(args.args) <= 3:
            path_id = args.args[0] if len(args.args) > 0 else None
            before = args.args[1] if len(args.args) > 1 else None
            limit = args.args[2] if len(args.args) > 2 else '50'
            value = audit_events_get(path_id, before, limit)
        elif args.command == 'audit-job' and len(args.args) == 1:
            value = audit_job_get(args.args[0])
        elif args.command == 'audit-cancel' and len(args.args) == 1:
            value = audit_cancel(args.args[0], actor='cli')
        elif args.command == 'schedule-get' and len(args.args) == 1:
            value = schedule_get(args.args[0])
        elif args.command == 'schedule-set' and len(args.args) == 4:
            value = schedule_set(*args.args)
        elif args.command == 'source-in-use' and len(args.args) == 1:
            value = source_in_use(args.args[0])
        else:
            raise AuditError('invalid command arguments')
        print(json.dumps(value, ensure_ascii=False))
        return 0 if value.get('ok', True) else 1
    except Exception as exc:
        error = str(exc) if isinstance(exc, AuditError) else type(exc).__name__
        print(json.dumps({'ok': False, 'error': error, 'applied': False}))
        return 1

if __name__ == '__main__':
    sys.exit(main())
