        print(json.dumps(result, ensure_ascii=False))
    elif args.command == 'torrent-disable':
        result = torrent_set_listener(False)
        print(json.dumps(result, ensure_ascii=False))
    elif args.command == 'mtrickle-sync':
        result = mtrickle_sync()
        print(json.dumps(result, ensure_ascii=False))
