        base['vpn_url'] = urls['vpn']
        base['vpn_nop2p_url'] = urls['vpn_nop2p']
        base['ai_url'] = urls['ai']
    print(json.dumps(base, ensure_ascii=False))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))
