}

# Byte-exact restore for a failed commit. Only valid when the preimage itself is intact.
restore_preimage() {
  state_values_ok || return 1
  state_preimage_ok || return 1
  _pre=$(state_get preimage)
  _sha=$(state_get preimage_sha256)
  _restore_tmp="$CONFIG_DIR/.dhcp.restore.$$"
  cp -p "$_pre" "$_restore_tmp" 2>/dev/null || { rm -f "$_restore_tmp"; return 1; }
  [ "$(sha256sum "$_restore_tmp" 2>/dev/null | awk '{print $1}')" = "$_sha" ] || {
    rm -f "$_restore_tmp"
    return 1
  }
  mv -f "$_restore_tmp" "$LIVE_DHCP" 2>/dev/null || {
    rm -f "$_restore_tmp"
    return 1
  }
  [ "$(sha256sum "$LIVE_DHCP" 2>/dev/null | awk '{print $1}')" = "$_sha" ] || return 1
  return 0
}

# Private backup of the live file before a live restore, and an atomic put-back. If the restore
# cannot reproduce the record exactly, the applied policy is still there instead of a half-write.
live_backup() {
  _backup="$STATE.rollback"
  cp -p "$LIVE_DHCP" "$_backup" 2>/dev/null || return 1
  return 0
}

live_backup_restore() {
  [ -f "$_backup" ] || return 1
  _rb_tmp="$CONFIG_DIR/.dhcp.rollback.$$"
  cp -p "$_backup" "$_rb_tmp" 2>/dev/null || { rm -f "$_rb_tmp"; return 1; }
  mv -f "$_rb_tmp" "$LIVE_DHCP" 2>/dev/null || { rm -f "$_rb_tmp"; return 1; }
  rm -f "$_backup"
  return 0
}

# Returns 0 when the record was reproduced; on failure `_restore_backup_ok` says whether the
# pre-restore live file was put back.
safe_state_restore() {
  _restore_backup_ok=0
  live_backup || return 1
  if state_restore; then
    rm -f "$_backup"
    return 0
  fi
  if live_backup_restore; then
    _restore_backup_ok=1
  fi
  return 1
}

# Restore the recorded TYPE, then commit and verify:
#   list   -> delete + one add_list per value
#   string -> set server=<value>
#   absent -> delete server
# strictorder is handled the same way. Values are read line by line.
state_restore() {
  state_values_ok || return 1
  _type=$(state_type)
  _current=$(dhcp_scan_live) || return 1
  _cur_type=$(scan_field "$_current" server_type)
  case "$_type" in
    list)
      if [ "$_cur_type" != absent ]; then
        uci_live -q delete dhcp.@dnsmasq[0].server 2>/dev/null || return 1
      fi
      state_servers > "$STATE.values.$$" 2>/dev/null || return 1
      while IFS= read -r _v; do
        uci_live -q add_list "dhcp.@dnsmasq[0].server=$_v" 2>/dev/null || return 1
      done < "$STATE.values.$$"
      ;;
    string)
      _v=$(state_get_all server | head -1)
      uci_live -q set "dhcp.@dnsmasq[0].server=$_v" 2>/dev/null || return 1
      ;;
    absent)
      if [ "$_cur_type" != absent ]; then
        uci_live -q delete dhcp.@dnsmasq[0].server 2>/dev/null || return 1
      fi
      ;;
    *) return 1 ;;
  esac
  _stype=$(state_stype)
  _cur_stype=$(scan_field "$_current" strictorder_type)
  case "$_stype" in
    list)
      if [ "$_cur_stype" != absent ]; then
        uci_live -q delete dhcp.@dnsmasq[0].strictorder 2>/dev/null || return 1
      fi
      state_get_all strictorder > "$STATE.strict.$$" 2>/dev/null || return 1
      while IFS= read -r _v; do
        uci_live -q add_list "dhcp.@dnsmasq[0].strictorder=$_v" 2>/dev/null || return 1
      done < "$STATE.strict.$$"
      ;;
    string)
      _v=$(state_get_all strictorder | head -1)
      uci_live -q set "dhcp.@dnsmasq[0].strictorder=$_v" 2>/dev/null || return 1
      ;;
    absent)
      if [ "$_cur_stype" != absent ]; then
        uci_live -q delete dhcp.@dnsmasq[0].strictorder 2>/dev/null || return 1
      fi
      ;;
    *) return 1 ;;
  esac
  uci_live -q commit dhcp 2>/dev/null || return 1
  state_verify
}

# ---------------------------------------------------------------- candidate + verification
verify_scan() {
  _vscan=$1
  _vwant=$2
  _vscoped=$3
  [ "$(scan_field "$_vscan" server_type)" = list ] || {
    _verr="server is not a list option"
    return 1
  }
  if scan_has "$_vscan" has_option_server=1; then
    _verr="an option server line is still present"
    return 1
  fi
  [ "$(scan_values "$_vscan" server)" = "$(cat "$_vwant")" ] || {
    _verr="server values are not exactly the requested list"
    return 1
  }
  [ "$(scoped_from_scan "$_vscan")" = "$(cat "$_vscoped")" ] || {
    _verr="scoped zone entries changed"
    return 1
  }
  [ "$(scan_field "$_vscan" strictorder_type)" = string ] || {
    _verr="strictorder is not a string option"
    return 1
  }
  [ "$(scan_values "$_vscan" strictorder)" = 1 ] || {
    _verr="strictorder is not 1"
    return 1
  }
  return 0
}

verify_config() {
  _vscan=$(dhcp_scan_dir "$CAND") || { _verr="cannot read the candidate configuration"; return 1; }
  verify_scan "$_vscan" "$NEW_VALUES" "$SCOPED_VALUES"
}

verify_live() {
  _vscan=$(dhcp_scan_live) || { _verr="cannot read the live configuration"; return 1; }
  verify_scan "$_vscan" "$NEW_VALUES" "$SCOPED_VALUES"
}

# Build the new list in the private copy: delete, one add_list per value, strictorder, commit,
# then read the candidate FILE back and verify it.
candidate_build() {
  _cand_err=
  _stage=
  _cscan=$(dhcp_scan_dir "$CAND") || { _cand_err="cannot read the candidate copy"; return 1; }
  if [ "$(scan_field "$_cscan" server_type)" != absent ]; then
    _stage=delete
    uci_cand -q delete dhcp.@dnsmasq[0].server 2>/dev/null || {
      _cand_err="uci delete failed"
      return 1
    }
  fi
  _stage=add_list
  while IFS= read -r _v; do
    uci_cand -q add_list "dhcp.@dnsmasq[0].server=$_v" 2>/dev/null || {
      _cand_err="uci add_list $_v failed"
      return 1
    }
  done < "$NEW_VALUES"
  _stage=set
  uci_cand -q set dhcp.@dnsmasq[0].strictorder=1 2>/dev/null || {
    _cand_err="uci set strictorder failed"
    return 1
  }
  _stage=commit
  uci_cand -q commit dhcp 2>/dev/null || { _cand_err="uci commit failed"; return 1; }
  _stage=verify
  verify_config || return 1
  _stage=
  return 0
}

# The live sequence is the same. `_live_stage` records how far the live file was touched:
#   none   -> only our private delta exists, the live file is untouched
#   commit -> a commit was attempted
#   verify -> the commit returned 0, verification is in progress
apply_live() {
  _stage=
  _live_stage=none
  _lscan=$(dhcp_scan_live) || { _stage=read; return 1; }
  if [ "$(scan_field "$_lscan" server_type)" != absent ]; then
    _stage=delete
    uci_live -q delete dhcp.@dnsmasq[0].server 2>/dev/null || return 1
  fi
  _stage=add_list
  while IFS= read -r _v; do
    uci_live -q add_list "dhcp.@dnsmasq[0].server=$_v" 2>/dev/null || return 1
  done < "$NEW_VALUES"
  _stage=set
  uci_live -q set dhcp.@dnsmasq[0].strictorder=1 2>/dev/null || return 1
  _stage=commit
  _live_stage=commit
  uci_live -q commit dhcp 2>/dev/null || return 1
  _live_stage=verify
  _stage=verify
  verify_live || return 1
  _live_stage=done
  _stage=
  return 0
}

candidate_matches_live() {
  [ -f "$CAND/dhcp" ] || return 1
  [ -f "$LIVE_DHCP" ] || return 1
  [ "$(sha256sum "$LIVE_DHCP" 2>/dev/null | awk '{print $1}')" = \
    "$(sha256sum "$CAND/dhcp" 2>/dev/null | awk '{print $1}')" ] || return 1
  return 0
}

# A preimage from an earlier apply is stale: restoring those bytes would erase edits made
# between the two applies. Only the snapshot this candidate was built from is byte-restorable.
preimage_matches_base() {
  state_preimage_ok || return 1
  [ -f "$CAND/base" ] || return 1
  [ "$(sha256sum "$(state_get preimage)" 2>/dev/null | awk '{print $1}')" = \
    "$(sha256sum "$CAND/base" 2>/dev/null | awk '{print $1}')" ] || return 1
  return 0
}

live_write_failed() {
  _why=$1
  live_revert
  case "$_live_stage" in
    none)
      fail "$_why at the ${_stage:-unknown} stage - live config untouched"
      ;;
    commit|verify)
      if candidate_matches_live; then
        if preimage_matches_base && restore_preimage; then
          restart_dnsmasq >/dev/null 2>&1 || true
          fail "$_why at the ${_stage:-unknown} stage - the preimage was restored"
        elif safe_state_restore; then
          restart_dnsmasq >/dev/null 2>&1 || true
          fail "$_why at the ${_stage:-unknown} stage - the recorded values were restored"
        elif [ "${_restore_backup_ok:-0}" = 1 ]; then
          restart_dnsmasq >/dev/null 2>&1 || true
          fail "$_why at the ${_stage:-unknown} stage - live restored to the pre-revert state, record kept"
        else
          fail "$_why at the ${_stage:-unknown} stage - could not restore, check $LIVE_DHCP"
        fi
      else
        fail "$_why at the ${_stage:-unknown} stage - the live file is not the one we wrote; record kept"
      fi
      ;;
    *)
      fail "$_why at the ${_stage:-unknown} stage - live config untouched"
      ;;
  esac
}

# ---------------------------------------------------------------- probes
# Only an answer that follows the `Name:` line counts. The first `Address:` line of BusyBox
# nslookup is the address of the SERVER; reading it as an answer made SERVFAIL look healthy.
resolve_local() {
  _out=$(nslookup "$TEST_HOST" 127.0.0.1 2>/dev/null) || return 1
  printf '%s\n' "$_out" | awk '
    /^Name:/ { seen = 1; next }
    seen && match($0, /[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+/) {
      ip = substr($0, RSTART, RLENGTH)
      if (ip != "0.0.0.0") { print ip; found = 1; exit }
    }
    END { exit found ? 0 : 1 }'
}

# Ask the DoH worker directly on its own port. rc 0 = it answered, 1 = it did not,
# 2 = cannot tell (no python3). Never guess in the caller.
doh_probe() {
  _port=$1
  command -v "$PROBE_PY" >/dev/null 2>&1 || return 2
  "$PROBE_PY" - "$_port" "$TEST_HOST" <<'PY' >/dev/null 2>&1
import random, socket, struct, sys
port, host = int(sys.argv[1]), sys.argv[2]
qid = random.randrange(0, 65536)
name = b''.join(bytes([len(p)]) + p.encode() for p in host.split('.')) + b'\0'
query = struct.pack('!HHHHHH', qid, 0x0100, 1, 0, 0, 0) + name + struct.pack('!HH', 1, 1)
s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
s.settimeout(3)
try:
    s.sendto(query, ('127.0.0.1', port))
    data, _ = s.recvfrom(512)
finally:
    s.close()
if len(data) < 12:
    sys.exit(1)
rid, flags, qd, an, ns, ar = struct.unpack('!HHHHHH', data[:12])
if rid != qid or not (flags & 0x8000) or (flags & 0x000F) != 0 or an < 1:
    sys.exit(1)
sys.exit(0)
PY
}

restart_dnsmasq() {
  [ -x "$DNSMASQ_INIT" ] || return 1
  "$DNSMASQ_INIT" restart >/dev/null 2>&1
}

# Undo a half-applied policy and report it. Used by every failure path in apply().
rollback() {
  live_revert
  if safe_state_restore; then
    restart_dnsmasq >/dev/null 2>&1 || true
    fail "$1 - previous DNS settings restored"
  elif [ "${_restore_backup_ok:-0}" = 1 ]; then
    restart_dnsmasq >/dev/null 2>&1 || true
    fail "$1 - live restored to the pre-revert state, record kept"
  else
    fail "$1 - could not restore the previous DNS settings, record kept"
  fi
}

# ---------------------------------------------------------------- status
status() {
  _scan=$(dhcp_scan_live) || {
    fail "cannot read $LIVE_DHCP"
    return 1
  }
  _list=$(value_tokens "$_scan" | awk 'BEGIN { ORS = " " } { print }' | sed 's/ $//')
  _so=$(scan_field "$_scan" strictorder)
  _reserve=0
  for _e in $EMERGENCY; do
    if value_tokens "$_scan" | grep -Fqx -e "$_e"; then _reserve=1; fi
  done
  _resolved=0
  resolve_local >/dev/null 2>&1 && _resolved=1
  _doh=unknown
  _port=$(local_doh_port "$_scan" 2>/dev/null) && {
    doh_probe "$_port"
    case "$?" in 0) _doh=ok ;; 1) _doh=fail ;; *) _doh=unknown ;; esac
  }
  _mode=off
  if [ "$_reserve" = 1 ] && [ "$_so" = 1 ]; then
    if [ "$_resolved" = 0 ]; then _mode=degraded
    elif [ "$_doh" = ok ]; then _mode=strict
    elif [ "$_doh" = fail ]; then _mode=emergency
    else _mode=applied
    fi
  fi
  printf '{"ok":true,"mode":"%s","resolution":%s,"doh_probe":"%s","reserve":%s,"strictorder":%s,"upstreams":"%s"}\n' \
    "$_mode" "$([ "$_resolved" = 1 ] && echo true || echo false)" "$_doh" \
    "$([ "$_reserve" = 1 ] && echo true || echo false)" \
    "$([ "$_so" = 1 ] && echo true || echo false)" \
    "$(json_escape "$_list")"
}

# ---------------------------------------------------------------- apply / revert
apply() {
  mkdir -p "$LIVE_DELTA" 2>/dev/null || true
  live_revert
  CAND=$(mktemp -d "${TMPDIR:-/tmp}/geomask-dnsguard.XXXXXX") || {
    fail "cannot create a private candidate directory"
    return 1
  }
  mkdir -p "$CAND/delta" 2>/dev/null || {
    fail "cannot create the candidate delta directory"
    return 1
  }
  cp -p "$LIVE_DHCP" "$CAND/dhcp" 2>/dev/null || {
    fail "cannot read $LIVE_DHCP - nothing changed"
    return 1
  }
  cp -p "$CAND/dhcp" "$CAND/base" 2>/dev/null || {
    fail "cannot snapshot $LIVE_DHCP - nothing changed"
    return 1
  }
  _scan=$(dhcp_scan_dir "$CAND") || {
    fail "cannot parse $LIVE_DHCP - nothing changed"
    return 1
  }
  _doh_port=$(local_doh_port "$_scan" 2>/dev/null) || {
    fail "no local DoH upstream in dnsmasq - strict mode would have nothing to trust"
    return 1
  }

  NEW_VALUES="$CAND/new.values"
  SCOPED_VALUES="$CAND/scoped.values"
  : > "$NEW_VALUES" || { fail "cannot create the value snapshot"; return 1; }
  value_tokens "$_scan" | grep '^/' > "$SCOPED_VALUES" 2>/dev/null || true

  # Order: DoH worker, then the emergency reserve, then anything else the owner had, without
  # duplicates; the domain-scoped zones stay last and must survive exactly.
  doh_values "$_scan" > "$CAND/doh.values"
  while IFS= read -r _s; do add_new "$_s"; done < "$CAND/doh.values"
  for _e in $EMERGENCY; do add_new "$_e"; done
  value_tokens "$_scan" > "$CAND/all.values"
  while IFS= read -r _s; do
    case "$_s" in
      127.0.0.1#*|localhost#*) continue ;;
      /*) continue ;;
    esac
    is_emergency "$_s" && continue
    add_new "$_s"
  done < "$CAND/all.values"
  while IFS= read -r _s; do add_new "$_s"; done < "$SCOPED_VALUES"

  if ! candidate_build; then
    fail "candidate configuration rejected at the ${_stage:-unknown} stage - live config untouched${_cand_err:+: $_cand_err}"
    return 1
  fi
  # Record only after the candidate is known good, so a candidate failure leaves no record.
  state_save "$_scan" || {
    fail "cannot record the current DNS settings at $STATE - nothing changed; if the file is unusable run: geomask-dnsguard.sh revert --force"
    return 1
  }
  if ! apply_live; then
    live_write_failed "cannot rewrite the dnsmasq server list"
    return 1
  fi

  restart_dnsmasq || { rollback "dnsmasq did not restart"; return 1; }
  _i=0
  while [ "$_i" -lt 5 ]; do
    resolve_local >/dev/null 2>&1 && break
    sleep 1; _i=$((_i + 1))
  done
  # A policy that leaves the router unable to resolve is worse than the state we found.
  resolve_local >/dev/null 2>&1 || {
    rollback "the resolver does not answer after the change"
    return 1
  }

  drop_live_delta
  doh_probe "$_doh_port"
  case "$?" in
    0) say '{"ok":true,"mode":"strict"}' ;;
    1) say '{"ok":true,"mode":"emergency","warn":"DoH worker does not answer - resolution uses the emergency reserve"}' ;;
    *) say '{"ok":true,"mode":"applied","warn":"policy applied, but the DoH worker could not be probed"}' ;;
  esac
}

revert() {
  _force=${1:-}
  mkdir -p "$LIVE_DELTA" 2>/dev/null || true
  live_revert
  if [ -f "$STATE" ] && ! state_values_ok; then
    if [ "$_force" = --force ]; then
      rm -f "$STATE" "$STATE.preimage" "$STATE.rollback" 2>/dev/null
      say '{"ok":true,"mode":"off","note":"unusable record dropped, live config untouched"}'
      return 0
    fi
    fail "the DNS record at $STATE is incomplete - nothing changed; run: geomask-dnsguard.sh revert --force to drop it"
    return 1
  fi
  if ! state_values_ok; then
    say '{"ok":true,"mode":"off","note":"no recorded policy - nothing to revert"}'
    return 0
  fi
  _had_preimage=0
  state_preimage_ok && _had_preimage=1
  _was_v1=0
  [ "$(state_get version)" = 1 ] && _was_v1=1
  if ! safe_state_restore; then
    if [ "${_restore_backup_ok:-0}" = 1 ]; then
      fail "cannot restore the previous DNS settings - live restored to the pre-revert state, record kept"
    else
      fail "cannot restore the previous DNS settings - record kept"
    fi
    return 1
  fi
  restart_dnsmasq || { fail "dnsmasq did not restart - previous list written, record kept"; return 1; }
  _i=0
  while [ "$_i" -lt 5 ]; do
    resolve_local >/dev/null 2>&1 && break
    sleep 1; _i=$((_i + 1))
  done
  resolve_local >/dev/null 2>&1 || {
    fail "the resolver does not answer after revert - record kept"
    return 1
  }
  rm -f "$STATE" "$STATE.preimage" "$STATE.rollback" 2>/dev/null
  drop_live_delta
  if [ "$_was_v1" = 1 ]; then
    say '{"ok":true,"mode":"off","note":"version 1 record upgraded and restored from its values"}'
  elif [ "$_had_preimage" = 0 ]; then
    say '{"ok":true,"mode":"off","note":"preimage missing - restored from the recorded values"}'
  else
    say '{"ok":true,"mode":"off"}'
  fi
}

case "${1:-status}" in
  status) status ;;
  apply)
    logmsg "apply start"
    apply
    _rc=$?
    logmsg "apply rc=$_rc"
    exit "$_rc" ;;
  revert)
    logmsg "revert start"
    revert "${2:-}"
    _rc=$?
    logmsg "revert rc=$_rc"
    exit "$_rc" ;;
  *) say '{"ok":false,"error":"usage: geomask-dnsguard.sh status|apply|revert [--force]"}'; exit 2 ;;
esac
ASSET_EOF
  # v1.31.0: the console lane patcher (provider + select group + listener in one place).
  save_stream /usr/lib/geomask/geomask-console.py 755 <<'ASSET_EOF'
#!/usr/bin/env python3
"""Console lane for geomask: a fourth tunnel that belongs to one game console.

Why a separate lane and not just rules: a console needs ONE stable egress for the whole
session (auth + game + UDP). Rules keyed on domain names cannot promise that — the console
talks to CDN and API hosts that also belong to every other device. The AI lane solved the
same problem with a dedicated hev tunnel + a listener pinned to one group; this does the
same for a console, so the egress is chosen by the listener and no rule can steal it.

Commands:
  apply  <config> [--url URL|default|-] [--countries TR,DE] [--port N]   create or update
  remove <config>                                                remove what we own
  status <config>                                                JSON state, read-only

Ownership: the provider is named `console`, the group `CONSOLE`, the listener `console`.
Anything with those exact names is ours; nothing else is touched. `remove` restores the
config to the state it had before `apply`, which is what the panel's kill switch calls.
"""
import json
import copy
import os
import re
import sys

import yaml

PROVIDER = 'console'
GROUP = 'CONSOLE'
LISTENER = 'console'
DEFAULT_PORT = 7893
# `--url default` is not a URL: it means "as the VPN" and discards the pinned subscription.
RESET_URL = 'default'

# Node names in this subscription carry the country in Russian and/or English. The filter is a
# regex over names, so a country is the union of the spellings actually seen in the wild.
COUNTRIES = {
    'TR': ('Турция', 'Turkey'),
    'DE': ('Германия', 'Germany'),
    'NL': ('Нидерланды', 'Netherlands', 'Holland'),
    'FI': ('Финляндия', 'Finland'),
    'SE': ('Швеция', 'Sweden'),
    'NO': ('Норвегия', 'Norway'),
    'DK': ('Дания', 'Denmark'),
    'PL': ('Польша', 'Poland'),
    'CZ': ('Чехия', 'Czech'),
    'AT': ('Австрия', 'Austria'),
    'CH': ('Швейцария', 'Switzerland'),
    'FR': ('Франция', 'France'),
    'IT': ('Италия', 'Italy'),
    'ES': ('Испания', 'Spain'),
    'GB': ('Великобритания', 'United Kingdom', 'Britain'),
    'IE': ('Ирландия', 'Ireland'),
    'US': ('США', 'USA', 'United States'),
    'CA': ('Канада', 'Canada'),
    'JP': ('Япония', 'Japan'),
    'KR': ('Корея', 'Korea'),
    'SG': ('Сингапур', 'Singapore'),
    'HK': ('Гонконг', 'Hong Kong'),
    'AE': ('ОАЭ', 'Emirates', 'UAE'),
    'IL': ('Израиль', 'Israel'),
    'KZ': ('Казахстан', 'Kazakhstan'),
    'AM': ('Армения', 'Armenia'),
    'GE': ('Грузия', 'Georgia'),
    'MD': ('Молдова', 'Moldova'),
    'RS': ('Сербия', 'Serbia'),
    'BG': ('Болгария', 'Bulgaria'),
    'RO': ('Румыния', 'Romania'),
    'HU': ('Венгрия', 'Hungary'),
    'GR': ('Греция', 'Greece'),
    'PT': ('Португалия', 'Portugal'),
    'LV': ('Латвия', 'Latvia'),
    'LT': ('Литва', 'Lithuania'),
    'EE': ('Эстония', 'Estonia'),
    'BR': ('Бразилия', 'Brazil'),
    'IN': ('Индия', 'India'),
    'AU': ('Австралия', 'Australia'),
}


class ConsoleError(Exception):
    pass


def loader():
    """PyYAML follows YAML 1.1, where off/on/yes/no are booleans; mihomo uses 1.2."""
    class Loader(yaml.SafeLoader):
        pass

    resolutions = {}
    for first, rules in yaml.SafeLoader.yaml_implicit_resolvers.items():
        kept = [(tag, regexp) for tag, regexp in rules
                if tag not in ('tag:yaml.org,2002:bool', 'tag:yaml.org,2002:timestamp')]
        if kept:
            resolutions[first] = kept
    Loader.yaml_implicit_resolvers = resolutions
    bool_re = re.compile(r'^(?:true|True|TRUE|false|False|FALSE)$')
    for first in 'tTfF':
        Loader.add_implicit_resolver('tag:yaml.org,2002:bool', bool_re, [first])
    return Loader


def dumper():
    """The matching dumper: without this, `ipv6: off` is written as `ipv6: 'off'`.

    PyYAML quotes any string that its YAML 1.1 resolvers would read back as a boolean, and a
    quoted `'off'` is not the boolean mihomo expects. Removing the same resolvers on the way
    out keeps the file byte-stable across a round trip.
    """
    class Dumper(yaml.SafeDumper):
        pass

    resolutions = {}
    for first, rules in yaml.SafeDumper.yaml_implicit_resolvers.items():
        kept = [(tag, regexp) for tag, regexp in rules
                if tag not in ('tag:yaml.org,2002:bool', 'tag:yaml.org,2002:timestamp')]
        if kept:
            resolutions[first] = kept
    Dumper.yaml_implicit_resolvers = resolutions
    bool_re = re.compile(r'^(?:true|True|TRUE|false|False|FALSE)$')
    for first in 'tTfF':
        Dumper.add_implicit_resolver('tag:yaml.org,2002:bool', bool_re, [first])
    return Dumper


def read_config(path):
    try:
        with open(path, encoding='utf-8') as handle:
            text = handle.read()
    except OSError as exc:
        raise ConsoleError('cannot read %s: %s' % (path, exc))
    doc = yaml.load(text, Loader=loader())
    if not isinstance(doc, dict):
        raise ConsoleError('mihomo config is not a mapping')
    return doc


def write_config(path, doc):
    """Atomic replace, same permissions: a half-written config stops mihomo on restart."""
    tmp = '%s.console-tmp.%d' % (path, os.getpid())
    body = yaml.dump(doc, Dumper=dumper(), allow_unicode=True, sort_keys=False)
    with open(tmp, 'w', encoding='utf-8', newline='\n') as handle:
        handle.write(body)
    try:
        os.chmod(tmp, os.stat(path).st_mode & 0o777)
    except OSError:
        os.chmod(tmp, 0o600)
    os.replace(tmp, path)


def country_filter(codes):
    """Regex for the node filter: every spelling of every allowed country."""
    parts = []
    for code in codes:
        names = COUNTRIES.get(code)
        if not names:
            raise ConsoleError('unknown country code: %s' % code)
        parts.extend(re.escape(name) for name in names)
    # `filter` is a regexp2 pattern; alternation without anchors matches anywhere in the name.
    return '|'.join(parts)


def find_group(doc):
    for entry in doc.get('proxy-groups') or []:
        if isinstance(entry, dict) and entry.get('name') == GROUP:
            return entry
    return None


def find_listener(doc):
    for entry in doc.get('listeners') or []:
        if isinstance(entry, dict) and entry.get('name') == LISTENER:
            return entry
    return None


def default_provider(doc):
    """The provider the VPN really rides on, else the legacy sub/slot/sub2 order.

    Point 10 of the 15.11 review: the console borrowed the first provider named `sub`, so on a
    split registry it silently left through the restricted (VPN-noP2P) subscription while the
    console needs the one the VPN group uses. `VPN` wins over `VPN-noP2P`; the first provider
    of that group's `use` list that actually has a URL is the answer.
    """
    providers = doc.get('proxy-providers')
    if not isinstance(providers, dict):
        return None
    groups = doc.get('proxy-groups')
    if isinstance(groups, list):
        for name in ('VPN', 'VPN-noP2P'):
            group = next((g for g in groups
                          if isinstance(g, dict) and g.get('name') == name), None)
            if group is None:
                continue
            for provider_name in group.get('use') or []:
                candidate = providers.get(provider_name)
                if isinstance(candidate, dict) and candidate.get('url'):
                    return candidate
    # No VPN lane on this config (or it has no usable provider): keep the old behaviour, or the
    # very first switch-on fails on a router that is already working.
    for name in ('sub', 'slot', 'sub2'):
        candidate = providers.get(name)
        if isinstance(candidate, dict) and candidate.get('url'):
            return candidate
    return None


def default_provider_url(doc):
    provider = default_provider(doc)
    return provider.get('url') if provider else None


def ensure_provider(doc, url):
    providers = doc.get('proxy-providers')
    if not isinstance(providers, dict):
        providers = {}
        doc['proxy-providers'] = providers
    current = providers.get(PROVIDER)
    spec = {'type': 'http', 'interval': 3600}
    if isinstance(current, dict):
        # keep whatever the owner's provider block already had (header, proxy, interval)
        spec = dict(current)
    if url == RESET_URL:
        # "As the VPN again": drop the pinned URL and the header that was copied with it, then
        # re-derive both below. Without the reset an explicit `--url` could never be undone.
        url = ''
        spec.pop('url', None)
        spec.pop('header', None)
    if url:
        spec['url'] = url
    if not spec.get('url'):
        source = default_provider(doc)
        if source is not None:
            spec['url'] = source['url']
            if isinstance(source.get('header'), dict) and source['header']:
                spec['header'] = copy.deepcopy(source['header'])
    if not spec.get('url'):
        raise ConsoleError('no subscription URL: the console provider has none and none was given')
    # A provider-level health check makes mihomo drop nodes from the group; the console lane
    # must keep its node even when one check fails mid-match.
    for key in ('health-check', 'lazy'):
        spec.pop(key, None)
    providers[PROVIDER] = spec
    return spec


def ensure_group(doc, countries, port):
    groups = doc.get('proxy-groups')
    if not isinstance(groups, list):
        groups = []
        doc['proxy-groups'] = groups
    group = find_group(doc)
    if group is None:
        group = {'name': GROUP}
        groups.append(group)
    group['type'] = 'select'
    group['use'] = [PROVIDER]
    if countries:
        group['filter'] = country_filter(countries)
    else:
        group.pop('filter', None)
    # A select group needs no health-check settings; leaving stale ones behind would make the
    # next reader think the lane is auto-switching.
    for key in ('url', 'interval', 'tolerance', 'lazy', 'expected-status'):
        group.pop(key, None)
    return group


def ensure_listener(doc, port):
    listeners = doc.get('listeners')
    if not isinstance(listeners, list):
        listeners = []
        doc['listeners'] = listeners
    entry = find_listener(doc)
    if entry is None:
        entry = {'name': LISTENER, 'type': 'mixed'}
        listeners.append(entry)
    entry.update({'type': 'mixed', 'port': int(port), 'listen': '127.0.0.1', 'proxy': GROUP})
    return entry


def apply(args):
    path, url, countries, port = args['config'], args['url'], args['countries'], args['port']
    doc = read_config(path)
    if url == '-':
        url = sys.stdin.readline().strip()
    ensure_provider(doc, url)
    ensure_group(doc, countries, port)
    ensure_listener(doc, port)
    write_config(path, doc)
    return {'ok': True, 'group': GROUP, 'provider': PROVIDER, 'listener': LISTENER,
            'port': int(port), 'countries': countries}


def remove(args):
    path = args['config']
    doc = read_config(path)
    changed = []
    groups = doc.get('proxy-groups')
    if isinstance(groups, list):
        kept = [g for g in groups if not (isinstance(g, dict) and g.get('name') == GROUP)]
        if len(kept) != len(groups):
            doc['proxy-groups'] = kept
            changed.append('group')
    listeners = doc.get('listeners')
    if isinstance(listeners, list):
        kept = [l for l in listeners if not (isinstance(l, dict) and l.get('name') == LISTENER)]
        if len(kept) != len(listeners):
            doc['listeners'] = kept
            changed.append('listener')
    providers = doc.get('proxy-providers')
    if isinstance(providers, dict) and PROVIDER in providers:
        providers.pop(PROVIDER, None)
        changed.append('provider')
    if changed:
        write_config(path, doc)
    return {'ok': True, 'removed': changed}


def status(args):
    doc = read_config(args['config'])
    group = find_group(doc)
    listener = find_listener(doc)
    providers = doc.get('proxy-providers') or {}
    provider = providers.get(PROVIDER) if isinstance(providers, dict) else None
    return {'ok': True,
            'present': bool(group and listener and provider),
            'group': {'type': (group or {}).get('type'),
                      'filter': (group or {}).get('filter'),
                      'use': (group or {}).get('use')} if group else None,
            'listener': {'port': (listener or {}).get('port'),
                         'proxy': (listener or {}).get('proxy')} if listener else None,
            'provider': {'has_url': bool((provider or {}).get('url'))} if provider else None}


def parse(argv):
    if not argv:
        raise ConsoleError('usage: geomask-console.py apply|remove|status <config> [options]')
    command, rest = argv[0], argv[1:]
    config = None
    url = ''
    countries = []
    port = DEFAULT_PORT
    index = 0
    while index < len(rest):
        item = rest[index]
        if item == '--url':
            index += 1
            url = rest[index] if index < len(rest) else ''
        elif item.startswith('--url='):
            url = item.split('=', 1)[1]
        elif item == '--countries':
            index += 1
            value = rest[index] if index < len(rest) else ''
            countries = [part.strip().upper() for part in value.split(',') if part.strip()]
        elif item.startswith('--countries='):
            value = item.split('=', 1)[1]
            countries = [part.strip().upper() for part in value.split(',') if part.strip()]
        elif item == '--port':
            index += 1
            port = int(rest[index])
        elif item.startswith('--port='):
            port = int(item.split('=', 1)[1])
        elif config is None:
            config = item
        else:
            raise ConsoleError('unexpected argument: %s' % item)
        index += 1
    if not config:
        raise ConsoleError('config path is required')
    return command, {'config': config, 'url': url, 'countries': countries, 'port': port}


def main(argv):
    try:
        command, args = parse(argv)
        handler = {'apply': apply, 'remove': remove, 'status': status}.get(command)
        if handler is None:
            raise ConsoleError('unknown command: %s' % command)
        result = handler(args)
    except ConsoleError as exc:
        print(json.dumps({'ok': False, 'error': str(exc)}, ensure_ascii=False))
        return 1
    except (OSError, ValueError, yaml.YAMLError) as exc:
        print(json.dumps({'ok': False, 'error': '%s: %s' % (type(exc).__name__, exc)},
                         ensure_ascii=False))
        return 1
    print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
