			domLog.textContent = '';
			callDiagDomain(name, domLive.checked ? 'live' : '').then(function(res) {
				if (!res || res.ok === false) {
					domOut.textContent = 'Ошибка: ' + ((res || {}).error || 'нет ответа');
					return;
				}
				domOut.textContent = (res.lines || []).join('\n');
				domLog.textContent = 'лог: ' + (res.log || '');
			}).catch(function(e) {
				domOut.textContent = 'Ошибка: ' + e;
			});
		}

