#!/bin/sh
# geomask-torrent.sh - manage the torrent/tracker DIRECT bypass (geomask v1.15.0+).
#
#   geomask-torrent.sh --status                 JSON for the panel
#   geomask-torrent.sh --refresh                rebuild the ruleset from the public lists + extras
#   geomask-torrent.sh --listener enable|off    toggle the SOCKS5/HTTP listener that pins torrents to DIRECT
#   geomask-torrent.sh --extra "a.org b.org"    replace the user-added tracker hosts (then rebuild)
#
# Everything it writes is validated with `mihomo -t` and rolled back on failure; reload goes
# through the local controller API with the bearer token, never via argv.
exec python3 - "$@" <<'PYEOF'
import contextlib, json, os, re, subprocess, sys, time, urllib.request

# The config transaction (geomask-config-tx.py) and this script write the same file. The lock
# is the transaction's own lock file - the same kernel flock(2) the Python transaction and the
# shell helper (geomask-lock.sh, rank config-tx) use, so no writer can interleave a commit
# between our read and our write. The file is never deleted or recreated.
TXLOCK=os.environ.get('GM_CONFIG_TX_LOCK','/etc/geomask/node-audit/state/.config-tx.lock')

@contextlib.contextmanager
def tx_lock():
    try:
        import fcntl
    except ImportError:
        if sys.platform.startswith('linux'):
            sys.exit('geomask-torrent: the fcntl/flock primitive is missing - refusing to write the live config')
        yield
        return
    os.makedirs(os.path.dirname(TXLOCK), exist_ok=True)
    fd=os.open(TXLOCK, os.O_CREAT | os.O_RDWR | getattr(os, 'O_NOFOLLOW', 0), 0o600)
    try:
        # Bounded wait like the Python transaction (30s) and the lane helper (15s): a blocking
        # LOCK_EX could hang the panel call forever on a stuck/malicious holder (review round 2).
        deadline=time.monotonic()+30.0
        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except OSError:
                if time.monotonic()>=deadline:
                    sys.exit('geomask-torrent: the config transaction lock is busy for 30s - retry later')
                time.sleep(0.1)
        yield
    finally:
        try: fcntl.flock(fd, fcntl.LOCK_UN)
        except OSError: pass
        os.close(fd)

CFG='/etc/mihomo/config.yaml'
RS='/etc/mihomo/ruleset/torrentdirect.yaml'
DIR='/etc/geomask/torrent'
SOURCES=DIR+'/sources.conf'
EXTRA=DIR+'/extra.txt'
SITES=DIR+'/sites.txt'
RSS='/etc/mihomo/ruleset/torrentsites.yaml'
JOURNAL='/root/geo-sync.log'
LISTENER_PORT='7894'

def log(msg):
    try:
        with open(JOURNAL,'a',encoding='utf-8') as f:
            f.write('%s TORRENT %s\n' % (time.strftime('%F %T'), msg))
    except Exception:
        pass

def read(p, default=''):
    try:
        return open(p, encoding='utf-8').read()
    except Exception:
        return default

def sources():
    s=[l.strip() for l in read(SOURCES).splitlines() if l.strip() and not l.strip().startswith('#')]
    return s or ['https://raw.githubusercontent.com/ngosang/trackerslist/master/trackers_all.txt',
                 'https://raw.githubusercontent.com/XIU2/TrackersListCollection/master/all.txt']

def extras():
    out=set()
    for l in read(EXTRA).splitlines():
        l=l.strip().lower().strip('.').rstrip('/')
        if l and not l.startswith('#'): out.add(l)
    return out

# ---------- controller ----------
def secret():
    for ln in read(CFG).splitlines():
        m=re.match(r'^secret:\s*["\']?([^"\'\s]+)', ln)
        if m: return m.group(1)
    return ''

def api(method, path, body=None):
    req=urllib.request.Request('http://127.0.0.1:9090'+path, method=method,
                               data=(json.dumps(body).encode() if body is not None else None))
    s=secret()
    if s: req.add_header('Authorization','Bearer '+s)
    if body is not None: req.add_header('Content-Type','application/json')
    try:
        return urllib.request.urlopen(req, timeout=10).getcode()
    except Exception as e:
        log('controller %s %s failed: %s' % (method, path, e)); return 0

def validate():
    return subprocess.run(['/usr/bin/mihomo','-t','-d','/etc/mihomo'],
                          capture_output=True, timeout=60).returncode == 0

# ---------- ruleset build ----------
def fetch(url):
    try:
        r=urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent':'geomask'}), timeout=25)
        return r.read().decode('utf-8','replace')
    except Exception as e:
        log('source fetch failed %s: %s' % (url, e)); return ''

def build_sites():
    """Torrent FORUM/CATALOG sites go to DIRECT, trackers and P2P to the VPN lane.
    Measured on the owner's router (01.11): Cloudflare-fronted sites such as rutracker.org,
    thepiratebay.org and 1337x.to answer 502 through the VPN exit but 301/200 directly - the
    block is against datacentre exit IPs, so routing them to a VPN makes them unreachable.
    Trackers are unaffected by that and belong on the P2P-tolerant lane, which is what the
    owner asked for."""
    hosts=set()
    if os.path.exists(SITES):
        for ln in open(SITES, encoding='utf-8', errors='replace'):
            ln=ln.strip().lower().lstrip('.')
            if not ln or ln.startswith('#'): continue
            if re.fullmatch(r'[a-z0-9]([a-z0-9\-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9\-]*[a-z0-9])?)+', ln):
                hosts.add(ln)
    hosts={h for h in hosts if not any(h!=a and h.endswith('.'+a) for a in hosts)}
    body=('# AUTO-GENERATED by geomask-torrent.sh from %s - DO NOT EDIT\n' % SITES)
    body+='payload:\n'
    for h in sorted(hosts): body+='  - DOMAIN-SUFFIX,%s\n' % h
    os.makedirs('/etc/mihomo/ruleset', exist_ok=True)
    tmp=RSS+'.tmp'
    with open(tmp,'w',encoding='utf-8',newline='\n') as f: f.write(body)
    os.replace(tmp,RSS)
    return len(hosts)

def build_ruleset():
    import ipaddress
    hosts=set(); ips=set(); bad=0
    for u in sources():
        for ln in fetch(u).splitlines():
            ln=ln.strip()
            if not ln: continue
            m=re.match(r'^(?:udp|https?)://([^/]+)', ln, re.I)
            if not m: bad+=1; continue
            h=re.sub(r':\d+$','',m.group(1)).strip('.').lower()
            if not h: continue
            try:
                ipaddress.ip_address(h); ips.add(h); continue
            except ValueError:
                pass
            if re.fullmatch(r'[a-z0-9]([a-z0-9\-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9\-]*[a-z0-9])?)+', h):
                hosts.add(h)
            else:
                bad+=1
    hosts |= extras()
    hosts = {h for h in hosts if not any(h != a and h.endswith('.'+a) for a in hosts)}
    body=('# AUTO-GENERATED by geomask-torrent.sh from the public tracker lists + user extras - DO NOT EDIT\n'
          '# regenerate: geomask-torrent.sh --refresh ; user hosts: %s\n' % EXTRA)
    body+='payload:\n'
    for h in sorted(hosts): body+='  - DOMAIN-SUFFIX,%s\n' % h
    for i in sorted(ips, key=lambda x: tuple(int(o) for o in x.split('.'))): body+='  - IP-CIDR,%s/32,no-resolve\n' % i
    os.makedirs('/etc/mihomo/ruleset', exist_ok=True)
    tmp=RS+'.tmp'
    open(tmp,'w',encoding='utf-8',newline='').write(body)
    old=read(RS)
    if old == body:
        os.remove(tmp)
        return len(hosts), len(ips), False
    open(RS+'.bak','w',encoding='utf-8',newline='').write(old) if old else None
    os.replace(tmp, RS)
    if not validate():
        if old: open(RS,'w',encoding='utf-8',newline='').write(old)
        log('ruleset rejected by mihomo -t, restored previous'); return len(hosts), len(ips), False
    return len(hosts), len(ips), True

# ---------- listener toggle ----------
# The listener is the torrent client's egress. Policy (v1.23.1, owner decision 02.11):
#   P2P must NEVER reach node-relay (the provider that banned the sub for BitTorrent). The
#   torrent client is told to proxy ALL traffic (peers/DHT/trackers) through this SOCKS listener,
#   so MagiTrickle never sees a raw peer IP to fwmark. The listener is therefore pinned to the
#   P2P-TOLERANT lane: "proxy: VPN" (the sub2/vlessi group). If that lane is absent, fall back to
#   "proxy: DIRECT" (real IP, but off the forbidden subscription). It is NEVER left rule-based
#   (that let AI domains through) and NEVER pinned to AI (node-relay = instant ban).
def lan_ip():
    """The router's own LAN address - 192.168.0.1 is only the owner's network."""
    dev = ''
    for key in ('network.lan.device', 'network.lan.ifname'):
        try:
            dev = subprocess.run(['uci', '-q', 'get', key], capture_output=True,
                                 text=True, timeout=5).stdout.strip()
        except Exception:
            dev = ''
        if dev:
            break
    dev = dev or 'br-lan'
    try:
        out = subprocess.run(['ip', '-4', 'addr', 'show', dev], capture_output=True,
                             text=True, timeout=5).stdout
    except Exception:
        return ''
    match = re.search(r'inet (\d+\.\d+\.\d+\.\d+)/', out)
    return match.group(1) if match else ''


LISTENER_BLOCK=['  - name: torrent-direct','    type: mixed','    port: %s' % LISTENER_PORT,
                '    listen: %s' % (lan_ip() or '127.0.0.1')]

def tolerant_lane():
    """The P2P-tolerant mihomo group: 'VPN' (sub2). Absent on a single-lane box."""
    t = read(CFG)
    return 'VPN' if re.search(r'(?m)^  - name: VPN\s*$', t) else ''

def listener_policy_target():
    """Where the torrent listener is pinned: the tolerant lane, else DIRECT. Never AI."""
    return tolerant_lane() or 'DIRECT'

def listener_block():
    return LISTENER_BLOCK + ['    proxy: %s' % listener_policy_target()]

def listener_policy():
    t=read(CFG)
    m=re.search(r'(?m)^  - name: torrent-direct\n(?:[ ]{4}.*\n)*?[ ]{4}proxy:\s*(\S+)', t)
    return m.group(1) if m else ''

def listener_present():
    return 'torrent-direct' in read(CFG)

def set_listener(on):
    t=read(CFG); lines=t.splitlines(True)
    if on:
        if listener_present():
            # v1.23.1 repair: an existing listener must be pinned to the tolerant lane
            # (never rule-based, never AI). Rewrite its proxy line to the required target.
            tgt=listener_policy_target()
            if listener_policy()==tgt: return False
            def fix(m):
                blk=m.group(0)
                if re.search(r'(?m)^\s{4}proxy:\s*\S+\s*$', blk):
                    blk=re.sub(r'(?m)^(\s{4})proxy:\s*\S+\s*$', r'\g<1>proxy: '+tgt, blk, count=1)
                else:
                    blk=blk.rstrip('\n')+'\n    proxy: '+tgt+'\n'
                return blk
            new=re.sub(r'(?m)^  - name: torrent-direct\n(?:[ ]{4}.*\n)+', fix, t, count=1)
            if new==t: log('could not locate torrent-direct block to repair'); return False
            return _commit_listener(t,new,'policy -> %s'%tgt)
        idx=next((i for i,l in enumerate(lines) if re.match(r'^\s+proxy: AI\s*$', l)), None)
        if idx is None: log('no ai-devices listener to anchor to'); return False
        lines.insert(idx+1, ''.join(x+'\n' for x in listener_block()))
    else:
        if not listener_present(): return False
        out=[]; i=0
        while i < len(lines):
            if re.match(r'^\s*-\s*name:\s*torrent-direct\s*$', lines[i]):
                i+=1
                while i < len(lines) and (lines[i].startswith('    ') or lines[i].strip()==''):
                    if i+1 < len(lines) and re.match(r'^\s*-\s*name:', lines[i+1]): break
                    if lines[i].strip()=='' and i+1 < len(lines) and not lines[i+1].startswith(' '): break
                    i+=1
                continue
            out.append(lines[i]); i+=1
        lines=out
    return _commit_listener(t, ''.join(lines), 'enabled' if on else 'disabled')

def _put(data):
    """Atomic replace of the live config (a crash cannot leave a truncated file)."""
    tmp=CFG+'.tmp.torrent.%d' % os.getpid()
    open(tmp,'w',encoding='utf-8',newline='').write(data)
    os.replace(tmp,CFG)

def _commit_listener(old, new, why):
    if new==old: return False
    # Read-modify-write under the transaction lock, with a compare-and-swap: `old` is what the
    # patch was derived from. A concurrent console/panel commit is refused, never overwritten.
    with tx_lock():
        if read(CFG)!=old:
            log('listener change refused: config changed since it was read (another writer won)')
            return False
        bak=CFG+'.bak_torrent.%d' % os.getpid()
        open(bak,'w',encoding='utf-8',newline='').write(old)
        _put(new)
        if not validate():
            _put(old)
            log('listener change rejected by mihomo -t, config restored'); return False
        try: os.remove(bak)
        except OSError: pass
    api('PUT','/configs?force=true', {'path': CFG})
    log('listener %s' % why)
    return True

# ---------- commands ----------
def status():
    prov=0
    try:
        req=urllib.request.Request('http://127.0.0.1:9090/providers/rules')
        s=secret()
        if s: req.add_header('Authorization','Bearer '+s)
        d=json.load(urllib.request.urlopen(req, timeout=8))
        prov=(d.get('providers') or d).get('torrentdirect',{}).get('ruleCount',0)
    except Exception:
        pass
    rs=read(RS)
    return {
        'ok': True,
        'listener_present': listener_present(),
        'listener_policy': listener_policy(),
        'listener_port': int(LISTENER_PORT),
        'ruleset_present': bool(rs.strip()),
        'domains': len(re.findall(r'DOMAIN-SUFFIX,', rs)),
        'raw_ips': len(re.findall(r'IP-CIDR,', rs)),
        'provider_loaded': prov,
        'extras': sorted(extras()),
        'sources': sources(),
        'proxy_hint': 'socks5h://%s:%s' % (lan_ip() or '<LAN IP>', LISTENER_PORT),
    }

args=sys.argv[1:]
if '--status' in args:
    print(json.dumps(status(), ensure_ascii=False)); sys.exit(0)
if '--listener' in args:
    i=args.index('--listener'); want=args[i+1] if i+1 < len(args) else 'enable'
    ok=set_listener(want in ('enable','on','true','1'))
    print(json.dumps({'ok': ok, 'listener_present': listener_present()})); sys.exit(0 if ok else 1)
if '--extra' in args:
    i=args.index('--extra'); val=args[i+1] if i+1 < len(args) else ''
    os.makedirs(DIR, exist_ok=True)
    hosts=[h.strip().lower().strip('.') for h in re.split(r'[\s,;]+', val) if h.strip()]
    bad=[h for h in hosts if not re.fullmatch(r'[a-z0-9]([a-z0-9\-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9\-]*[a-z0-9])?)+', h)]
    if bad:
        print(json.dumps({'ok': False, 'rejected': bad})); sys.exit(1)
    open(EXTRA,'w',encoding='utf-8',newline='').write('\n'.join(sorted(set(hosts)))+'\n' if hosts else '')
    d,i2,changed=build_ruleset()
    nsites=build_sites()
    if changed: api('PUT','/configs?force=true', {'path': CFG})
    log('extras set: %d host(s)' % len(hosts))
    print(json.dumps({'ok': True, 'domains': d, 'raw_ips': i2, 'sites': nsites, 'changed': changed})); sys.exit(0)
# default: --refresh
os.makedirs(DIR, exist_ok=True)
if not os.path.exists(SITES):
    open(SITES,'w',encoding='utf-8',newline='').write(
        '# torrent forum/catalog sites - these go DIRECT (Cloudflare rejects the VPN exit IPs)\n'
        '# one hostname per line; trackers belong in extra.txt and go to the P2P-tolerant VPN\n')
if not os.path.exists(SOURCES):
    open(SOURCES,'w',encoding='utf-8',newline='').write(
        '# tracker announce lists used to build the VPN ruleset\n'
        + '\n'.join(sources()) + '\n')
d,i2,changed=build_ruleset()
nsites=build_sites()
if changed:
    time.sleep(1)
    api('PUT','/configs?force=true', {'path': CFG})
    log('ruleset refreshed: %d domains, %d raw ips' % (d, i2))
else:
    log('ruleset refresh: nothing changed (%d domains)' % d)
print(json.dumps({'ok': True, 'domains': d, 'raw_ips': i2, 'changed': changed}))
PYEOF
ASSET_EOF
  # v1.21.4: keep an existing lane across reinstalls - it carries an interface the owner may have
  # assigned MagiTrickle lists to, and losing it silently reroutes those lists.
  if [ -e "$(P /sys/class/net/VPN-noP2P)" ] && [ -x "$(P /usr/bin/geomask-lane.sh)" ]; then
    info "lane VPN-noP2P: already present, left untouched"
  elif [ -x "$(P /usr/bin/geomask-lane.sh)" ] && [ -n "${GM_AUTO_LANE:-}" ]; then
    "$(P /usr/bin/geomask-lane.sh)" install >/dev/null 2>&1 || warn "lane install failed"
  fi
  # v1.22.1: DNS safety audit - read-only, explains "site address not found" before it happens
  save_stream /usr/bin/geomask-dnscheck.sh 755 <<'ASSET_EOF'
#!/bin/sh
# geomask-dnscheck.sh - read-only DNS safety audit (geomask v1.22.1+).
#
#   geomask-dnscheck.sh            full audit (probes the network)
#   geomask-dnscheck.sh --quick    configuration only: NO network calls at all
#
# Exit contract (R10a):
#   0  every check this mode performs ran and passed (warnings do not fail the audit)
#   1  at least one performed check found a problem (FAIL)
#   2  UNKNOWN: a check could not be performed (no nslookup, no usable LAN address,
#      no python3, no mihomo config, an unreadable /etc/hosts) - never a silent OK
#
# It exists because of two incidents seen on routers of this kind:
#   1) a DoH proxy and an ad blocker both force-redirect port 53, the proxy bootstraps its
#      own server name through that redirected port, and LAN DNS stops answering entirely
#      (symptom: "site address not found", fixed by turning any VPN on);
#   2) a "bypass" address pinned into /etc/hosts goes stale, so every client keeps dialling
#      a dead IP and the site breaks even though the tunnel itself is fine.
# Nothing here changes anything: it only reports.
#
# R10a fixes:
#   * the nslookup exit code is checked, and the answer is read only AFTER `Name:` - the
#     server `Address:` line is never an answer; both `Address:` and BusyBox `Address N:`
#     shapes are understood;
#   * the LAN resolver address comes from UCI `network.lan.device`/`ifname` + `ip -4 addr
#     show` (fallback `br-lan`), never from a hardcoded 192.168.0.1;
#   * `--quick` really makes no outbound probe (the old code still ran two nslookups);
#   * a missing python3 or a missing /etc/mihomo/config.yaml is UNKNOWN (rc 2), not "working".
#
# Environment overrides exist for the Windows-hosted tests only; the router never sets them:
#   GM_MIHOMO_CONFIG  mihomo config (default /etc/mihomo/config.yaml)
#   GM_HOSTS          hosts file (default /etc/hosts)
#   GM_NET_DIR        tunnel sysfs directory (default /sys/class/net)
#   GM_RULESET_DIR    mihomo ruleset directory (default /etc/mihomo/ruleset)
#   GM_PYTHON         python3 binary (default python3)
QUICK=${1:-}
FAIL=0; WARN=0; UNKNOWN=0
ok()   { printf '  OK    %s\n' "$1"; }
warn() { printf '  WARN  %s\n' "$1"; WARN=$((WARN+1)); }
bad()  { printf '  FAIL  %s\n' "$1"; FAIL=$((FAIL+1)); }
unknown() { printf '  UNKNOWN  %s\n' "$1"; UNKNOWN=$((UNKNOWN+1)); }
skip() { printf '  SKIP  %s\n' "$1"; }

MIHOMO_CONF=${GM_MIHOMO_CONFIG:-/etc/mihomo/config.yaml}
HOSTS_FILE=${GM_HOSTS:-/etc/hosts}
NET_DIR=${GM_NET_DIR:-/sys/class/net}
PYTHON=${GM_PYTHON:-python3}

echo "=== DNS safety check  $(date '+%F %T') ==="

echo
echo "--- 1) is the resolver actually alive ---"
# The answer is a line AFTER `Name:`. The first `Address:` line of nslookup output is the
# server that was asked; taking it made a SERVFAIL look like a working resolver (G01).
resolver_answer() { # <server>; prints the answer address, empty when the exchange failed
  _out=$(nslookup yandex.ru "$1" 2>/dev/null)
  _rc=$?
  [ "$_rc" -eq 0 ] || return 1
  printf '%s\n' "$_out" | awk '
    /^Name:/ { seen = 1; next }
    seen && /^Address[ \t]*[0-9]*:/ {
      sub(/^Address[ \t]*[0-9]*:[ \t]*/, "")
      if ($1 != "") { print $1; exit }
    }'
}
check_resolver() { # <server> <label>
  _ans=$(resolver_answer "$1")
  if [ -n "$_ans" ]; then
    ok "dnsmasq answers on $2 ($_ans)"
  else
    bad "dnsmasq does NOT answer on $2 - LAN clients cannot resolve anything"
  fi
}
if [ "$QUICK" = "--quick" ]; then
  skip "resolver liveness probes (--quick makes no network calls)"
else
  if ! command -v nslookup >/dev/null 2>&1; then
    unknown "nslookup is missing - the resolver cannot be probed"
  else
    check_resolver 127.0.0.1 "127.0.0.1:53"
    LAN_DEV=$(uci get network.lan.device 2>/dev/null)
    [ -n "$LAN_DEV" ] || LAN_DEV=$(uci get network.lan.ifname 2>/dev/null)
    for _lan in $LAN_DEV; do LAN_DEV=$_lan; break; done
    [ -n "$LAN_DEV" ] || LAN_DEV=br-lan
    LAN_IP=''
    if command -v ip >/dev/null 2>&1; then
      LAN_IP=$(ip -4 addr show dev "$LAN_DEV" 2>/dev/null \
        | awk '/^[[:space:]]*inet /{sub(/\/.*/, "", $2); print $2; exit}')
    fi
    if [ -n "$LAN_IP" ]; then
      check_resolver "$LAN_IP" "$LAN_IP:53 (LAN $LAN_DEV)"
    else
      unknown "cannot determine the LAN address of $LAN_DEV via UCI/ip - the LAN probe did not run"
    fi
  fi
  if command -v pgrep >/dev/null 2>&1; then
    if ! pgrep -f dnsmasq >/dev/null 2>&1; then bad "no dnsmasq process at all"; fi
  else
    unknown "pgrep is missing - cannot check that dnsmasq runs"
  fi
fi

echo
echo "--- 2) who owns port 53, and is anything redirected into a loop ---"
if ! command -v netstat >/dev/null 2>&1; then
  unknown "netstat is missing - cannot check who listens on :53"
else
  LIST=$(netstat -lntu 2>/dev/null | grep -cE ':53[[:space:]]')
  [ -n "$LIST" ] || LIST=0
  if [ "$LIST" -gt 0 ]; then ok "port 53 has a listener ($LIST socket(s))"
  else bad "nothing listens on :53"; fi
fi
DOH_PORT=$(uci get https-dns-proxy.@https-dns-proxy[0].listen_port 2>/dev/null)
[ -n "$DOH_PORT" ] && echo "  https-dns-proxy listens on :$DOH_PORT"
# the loop shape: a redirect of :53 that lands on the DoH proxy, while the proxy resolves its
# own server names through :53
NFORCE=0
for pkg in https-dns-proxy adblock-fast; do
  v=$(uci get $pkg.config.force_dns 2>/dev/null)
  [ "$v" = "1" ] && { NFORCE=$((NFORCE+1)); echo "  $pkg claims force_dns"; }
done
# NOTE: use if/elif here. The old `cond && warn ... || ok ...` chain printed BOTH lines,
# because warn() succeeds, so the following || branch still ran.
if [ "$NFORCE" -gt 1 ]; then
  warn "$NFORCE packages both force-redirect DNS - one of them must win, and the usual outcome is a loop"
elif [ "$NFORCE" = "1" ]; then
  ok "exactly one package forces DNS redirection"
else
  ok "no package forces DNS redirection"
fi
if [ -n "$DOH_PORT" ]; then
  if ! command -v nft >/dev/null 2>&1; then
    unknown "nft is missing - cannot check the :53 redirect into https-dns-proxy"
  else
    REDIR=$(nft list ruleset 2>/dev/null | grep -E 'dport 53' | grep -c "redirect to :$DOH_PORT")
    [ -n "$REDIR" ] || REDIR=0
    if [ "$REDIR" -gt 0 ]; then
      warn "port 53 is redirected to the DoH proxy :$DOH_PORT - if its bootstrap also uses :53, DNS dies"
    else
      ok "no :53 -> :$DOH_PORT redirect (proxy is not in the resolution path)"
    fi
  fi
fi

echo
echo "--- 3) can the DoH proxy bootstrap at all (this is what breaks silently) ---"
