tunneled=set()
for f in os.listdir(ruleset_dir) if os.path.isdir(ruleset_dir) else []:
    if not f.endswith('.yaml'): continue
    try: txt=open(os.path.join(ruleset_dir, f), encoding='utf-8', errors='replace').read()
