import re, sys
p, name, port, grp = sys.argv[1:5]
t = open(p, encoding='utf-8').read()
blk = ('  - name: %s\n    type: mixed\n    port: %s\n    listen: 127.0.0.1\n'
       '    proxy: %s\n' % (name, port, grp))
