echo "=== geomask morning check  $(date '+%F %T') ==="

echo
echo "--- 1. invariants: can P2P reach the restricted slot? ---"
N=$(awk '/^rules:/{f=1;next} f&&/^[^ ]/{exit} f' $CFG | grep -c 'VPN-noP2P')
