blanket_permanent=1

# Hard cap on automatically pinned hosts; when reached the watcher stops pinning and logs
max_pins=40

# MagiTrickle group that feeds ytvpn.yaml (created by geomask, editable at :8080)
group_name=GoogleVideo VPN
