      info "mihomo group VPN-noP2P: in API"
    else
      bad "mihomo group VPN-noP2P missing"; _sg_need=1
    fi
    if printf '%s' "$_sg_px" | grep -q '"AI"'; then
      info "mihomo group AI: in API"
    else
      bad "mihomo group AI missing"; _sg_need=1
    fi
    if printf '%s' "$_sg_px" | grep -q '"VPN"'; then
      info "mihomo group VPN: in API"
    elif grep -qE '^[[:space:]]*- name: VPN$' "$(P "$MIHOMO_CONF")" 2>/dev/null; then
      bad "mihomo group VPN: declared in the config but missing from the API"; _sg_need=1
    else
      info "mihomo group VPN: not used (single tunnel - main lists ride VPN-noP2P)"
    fi
  else
    bad "mihomo controller request failed (check authentication/connectivity)"; _sg_need=1
  fi
  return $_sg_need
}

step7_check() {
  _need=0
  _r=$(nslookup ya.ru 127.0.0.1 2>/dev/null | awk '/^Address: /{print $2}' | tail -1)
  if [ -n "$_r" ] && [ "$_r" != "127.0.0.1" ]; then info "DNS normal (ya.ru -> $_r)"; else bad "DNS broken for normal domains"; _need=1; fi
  _b=$(nslookup doubleclick.net 127.0.0.1 2>/dev/null | awk '/^Address: /{print $2}' | tail -1)
  case "$_b" in
    ""|0.0.0.0|::) info "DNS adblock (doubleclick.net -> ${_b:-NXDOMAIN})" ;;
    *) warn "adblock: doubleclick.net resolves to $_b (adblock-fast may be off)" ;;
  esac
  _code=$(curl -m 5 -s -o /dev/null -w '%{http_code}' http://www.gstatic.com/generate_204 2>/dev/null)
  [ "$_code" = "204" ] && info "connectivity: 204 OK" || { bad "connectivity: HTTP ${_code:-none}"; _need=1; }
  _step7_groups || _need=1
  if have ubus && module_selected luci; then
    ubus list 2>/dev/null | grep -qx 'geo-sync' && info "geo ubus: OK" || { bad "geo ubus: missing"; _need=1; }
  elif ! module_selected luci; then
    info "geo ubus: панель (модуль luci) не выбрана - проверка пропущена"
  fi
  if ip rule show 2>/dev/null | grep -q "iif $(lan_iface) ipproto icmp"; then info "ICMP bypass rule: present"; else warn "ICMP bypass rule absent - LAN ping may die in TUN"; fi
  # Routing depends on the hotplug script and its shared helper; a missing helper silently
  # disables the tunnel policy after the next ifup (audit follow-up, N01/N02).
  for _rf in /etc/hotplug.d/iface/99-default-vpn-route /usr/lib/geomask/geomask-routes.sh; do
    if [ -s "$(P "$_rf")" ]; then info "routing: $_rf present"
    else bad "routing: $_rf missing - VPN policy will not be applied on ifup"; _need=1; fi
  done
  # The route queue worker writes error-<table> in GM_ROUTE_STATE_DIR (default /tmp/...).
  # step 7 keeps reporting the last failed sync, but through the injectable root (R05).
  _rq_dir=${GM_ROUTE_STATE_DIR:-$(P /tmp/geomask-routes)}
  if [ -f "$_rq_dir/error-100" ]; then
    bad "routing: last route sync failed ($(cat "$_rq_dir/error-100" 2>/dev/null)) - LAN may go direct"
    _need=1
  fi
  # IPv6 is not tunnelled (mihomo ipv6: false, IPv4-only policy): if the router or the LAN
  # still has global IPv6, services see the real address. OFF is the default now, so the check
  # reports a live leak as a failure and a merely-latent one as a warning (audit follow-up, N00).
  _v6_global=$(ip -6 addr show scope global 2>/dev/null | grep -c 'inet6 ')
  [ -n "$_v6_global" ] || _v6_global=0
  _v6_assign=$(uci -q get network.lan.ip6assign 2>/dev/null)
  _v6_ra=$(uci -q get dhcp.lan.ra 2>/dev/null)
  if [ "$GM_IPV6" = keep ]; then
    info "IPv6: сохранён по --ipv6=keep (глобальных адресов: $_v6_global)"
  elif [ "$_v6_global" -gt 0 ]; then
    bad "IPv6: $_v6_global глобальных адресов - реальный IP уходит мимо VPN (панель -> IPv6 -> Отключить)"
    _need=1
  elif [ "$_v6_assign" = 0 ] && [ "$_v6_ra" = disabled ]; then
    info "IPv6: выключен (ядро + LAN + firewall)"
  else
    # A warning here used to be skipped by run_step ("check: ALL GOOD"), so the default
    # "IPv6 off everywhere" was never applied on a router that had no global address yet but
    # still handed out IPv6 on the LAN. Latent leak is still a leak: fail the check so the
    # step actually runs.
    bad "IPv6: глобальных адресов нет, но LAN по-прежнему раздаёт IPv6 (ip6assign=${_v6_assign:-не задан}, ra=${_v6_ra:-не задан}) - префикс появится при подъёме WAN"
    _need=1
  fi
  # Console lane: while it is switched on, the rule is the only thing that keeps the console
  # off the normal path. A missing rule looks like "the game broke", so it is a failure here.
  _cs="$(P /etc/geomask/console.state)"
  if [ -f "$_cs" ] && [ "$(sed -n 's/^enabled=//p' "$_cs" 2>/dev/null | head -1)" = 1 ]; then
    _cip=$(sed -n 's/^ip=//p' "$_cs" 2>/dev/null | head -1)
    if ip rule show 2>/dev/null | grep -q "from $_cip lookup 102" \
       && ip route show table 102 2>/dev/null | grep -q '^default'; then
      info "console: отдельный выход включён для $_cip"
    else
      bad "console: правило для $_cip пропало - консоль идёт напрямую (панель -> «Включить путь консоли»)"
      _need=1
    fi
  fi
  # AI-DNS: client DNS of AI devices must be intercepted AND exit through the AI tunnel.
  # Checking only the fwmark route proved nothing about the clients: the DNAT rule can be
  # absent while this line still printed "no leak" (audit 14.11.2026, F08).
  if [ -f "$(P /etc/geomask-aidns.off)" ] || [ ! -f "$(P /etc/geomask-aidns.uid)" ]; then
    info "AI-DNS: not installed (DNS of AI devices resolves via router - run the aidns step)"
  else
    _rt=$(ip route get 1.1.1.1 mark 0x64 2>/dev/null)
    if [ -z "$_rt" ]; then
      warn "AI-DNS: routing check returned nothing (ip route unavailable?)"
    elif printf '%s' "$_rt" | grep -q 'dev AI'; then
      info "AI-DNS: marked DNS exits via AI tunnel"
    else
      bad "AI-DNS: marked DNS does NOT route via AI tunnel (leak!)"; _need=1
    fi
    _aip=$(aidns_ip)
    _aiips=$(awk '$2=="ai" && $1 !~ /^#/ {print $1}' "$(P /etc/geo-devices.list)" 2>/dev/null)
    if [ -z "$_aip" ]; then
      bad "AI-DNS: listen address cannot be determined - clients are not intercepted"; _need=1
    elif [ -n "$_aiips" ]; then
      _tbl=$(nft list table inet geomask_ai_dns 2>/dev/null)
      if printf '%s' "$_tbl" | grep -q "dnat ip to $_aip:$AIDNS_DNS_PORT"; then
        info "AI-DNS: client DNS for ai devices is redirected to $_aip:$AIDNS_DNS_PORT"
      else
        bad "AI-DNS: client DNAT to $_aip:$AIDNS_DNS_PORT is missing - ai devices use the router DNS"; _need=1
      fi
    fi
  fi
  return $_need
}
# Turning IPv6 off is the only writing action of the final step. It goes through the installed
# backend so the three layers (kernel, LAN/odhcpd, forwarding guard) live in exactly one place.
apply_ipv6_default() {
  if [ "$GM_IPV6" = keep ]; then
    info "IPv6: оставлен как есть (--ipv6=keep)"
    return 0
  fi
  _be="$(P /usr/bin/geo-backend.sh)"
  if [ ! -x "$_be" ]; then
    # With --modules core,path_vpn the backend is not installed. Reporting success here made
    # the installer believe IPv6 was handled while nothing was changed.
    bad "IPv6: backend не установлен - выключение IPv6 не выполнено (нужен модуль luci/core с geo-backend.sh)"
    return 1
  fi
  # No uci means this is not a router we can manage network settings on (a test sandbox or a
  # broken image). Saying "not applicable" is honest; failing the whole run is not.
  if ! command -v uci >/dev/null 2>&1; then
    warn "IPv6: uci недоступен в этом окружении - состояние IPv6 не менялось"
    return 0
  fi
  # The backend keeps its own defaults for the marker and the backup tree; hand it the paths
  # this installer actually uses, so a prefixed/test root and the real router agree.
  _out=$(GM_BACKUP_OK="$(P /etc/geomask/backup-ok)" GM_BACKUP_DIR="$(P $BACKUP_DIR)" \
         "$_be" ipv6 off 2>&1)
  case "$_out" in
    *'"ok":true'*) info "IPv6: выключен (ядро + LAN + firewall)"; return 0 ;;
    *) bad "IPv6: выключить не удалось: $(printf '%s' "$_out" | tail -1)"; return 1 ;;
  esac
}

step7_apply() { apply_ipv6_default; }
step7_verify() { step7_check; }

# ============================================================ runner
STEP_NAMES="env geo subs aidns sync services verify"

step_desc() {
  case "$1" in
    env)      printf 'проверка окружения: версия OpenWrt, место на диске, зависимости (только чтение)' ;;
    geo)      printf 'гео-оверлей: панель "Гео-маскировка и AI" в LuCI + бэкенд geo-sync' ;;
    subs)     printf 'подписки: ссылки VPN/AI и группы VPN/AI в mihomo (проверка доступности)' ;;
    aidns)    printf 'AI-DNS: DNS AI-устройств через их же туннель — нет утечки DNS (ставится по умолчанию)' ;;
    sync)     printf 'sync: синк magitrickle→mihomo: watchdog (секунды) + cron-страховка' ;;
    services) printf 'сервисы: mihomo, magitrickle, hev-туннели, dnsmasq, веб-интерфейс' ;;
    verify)   printf 'сквозная проверка: выходы VPN/AI, DNS, группа AI, интернет (ничего не меняет)' ;;
    *)        printf '' ;;
  esac
}

step_fn() { # step_fn N action -> call stepN_action
  _n=$1; _a=$2
  case "$_n-$_a" in
    1-check) step1_check ;; 1-apply) step1_apply ;; 1-verify) step1_verify ;;
    2-check) step2_check ;; 2-apply) step2_apply ;; 2-verify) step2_verify ;;
    3-check) step3_check ;; 3-apply) step3_apply ;; 3-verify) step3_verify ;;
    4-check) step4_check ;; 4-apply) step4_apply ;; 4-verify) step4_verify ;;
    5-check) step5_check ;; 5-apply) step5_apply ;; 5-verify) step5_verify ;;
    6-check) step6_check ;; 6-apply) step6_apply ;; 6-verify) step6_verify ;;
    7-check) step7_check ;; 7-apply) step7_apply ;; 7-verify) step7_verify ;;
    *) bad "unknown step $_n"; return 1 ;;
  esac
}

run_step() { # run_step N  (interactive/auto common logic)
  _n=$1
  _name=$(echo "$STEP_NAMES" | cut -d' ' -f"$_n")
  hdr "$_n/7" "$_name"
  _fc_before=$FAILCNT
  if step_fn "$_n" check; then
    info "check: ALL GOOD"
    PASS=$((PASS+1))
    SKIP=$((SKIP+1))
    return 0
  fi
  info "check: issues found - apply needed"
  # A missing lock primitive (step 1 sets GM_STEP1_FATAL) is not something "apply" can fix:
  # refuse to apply ANY step, in the interactive wizard as well as in --auto. Without this the
  # wizard printed the step-1 error and still installed steps 2-7 into a system whose writers
  # are all fail-closed.
  # `--step N` and menu item 3 run a step in a fresh process where step1_check never ran, so
  # the sticky flag alone is not enough: probe the primitive directly for every other step.
  if [ "$_n" != 1 ] && [ "${GM_STEP1_FATAL:-0}" != 1 ]; then
    _rs_lpm=$(lock_primitive_missing)
    [ -z "$_rs_lpm" ] || GM_STEP1_FATAL=1
  fi
  if [ "${GM_STEP1_FATAL:-0}" = 1 ] && [ "$GM_CHECK_ONLY" != 1 ]; then
    bad "step $_n: step 1 did not pass its mandatory lock-primitive check - refusing to apply"
    return 1
  fi
  if [ "$GM_CHECK_ONLY" = 1 ]; then
    info "(check-only mode: not applying)"
    return 1
  fi
  if [ "$GM_AUTO" = 1 ] || [ "$GM_YES" = 1 ] || ask "Apply step $_n ($_name)?"; then
    # every step below writes to the router: one verified full backup per run, before it.
    # Step 1 installs packages (apk/opkg), so it is a writing step too - it used to run
    # before any backup existed (audit 14.11.2026, F13). Step 6 starts the services, which is
    # just as much of a change and was the only writing step without the gate (review 15.11).
    case "$_n" in
     1|2|3|4|5|6|7) backup_gate || return 1 ;;
    esac
    # v1.29.0: an installing step is the right moment to ask which modules to carry.
    case "$_n" in 2|4|5) modules_maybe_prompt ;; esac
    if step_fn "$_n" apply; then
      info "--- verify ---"
      if step_fn "$_n" verify; then
        info "verify: PASS"
        # check-phase failures were fixed by apply - drop them from the global count
        FAILCNT=$_fc_before
        return 0
      else
        bad "verify: FAILED after apply"
        return 1
      fi
    else
      bad "apply failed or was skipped"
      return 1
    fi
  else
    info "skipped by user"
    SKIP=$((SKIP+1))
    return 2
  fi
}

# R05: the installer holds `maintenance` and applies the queued ifup route events INLINE.
# It must not spawn a detached worker: the result has to be visible before step 7 reads
# error-<table>, and a child would outlive the maintenance section that authorised the change.
drain_route_queue() {
  _dr_lib=${GM_ROUTES_LIB:-$(P /usr/lib/geomask/geomask-routes.sh)}
  [ -r "$_dr_lib" ] || return 0
  _dr_state=${GM_ROUTE_STATE_DIR:-$(P /tmp/geomask-routes)}
  (
    GM_ROUTE_STATE_DIR=$_dr_state
    GM_ROUTE_DRAIN=1
    GM_ROUTE_TUN_WAIT=0
    export GM_ROUTE_STATE_DIR GM_ROUTE_DRAIN GM_ROUTE_TUN_WAIT
    . "$_dr_lib" 2>/dev/null || exit 0
    command -v gm_route_drain >/dev/null 2>&1 || exit 0
    gm_route_drain
  ) >/dev/null 2>&1
  return $?
}

# ============================================================ terminal UI
if [ -t 1 ]; then
  C_R="$(printf '\033[1;31m')"; C_G="$(printf '\033[1;32m')"; C_Y="$(printf '\033[1;33m')"
  C_B="$(printf '\033[1;36m')"; C_M="$(printf '\033[1;35m')"; C_DIM="$(printf '\033[38;5;244m')"
  NC="$(printf '\033[0m')"
else
  C_R=""; C_G=""; C_Y=""; C_B=""; C_M=""; C_DIM=""; NC=""
fi

clr()   { [ -t 1 ] && command -v clear >/dev/null 2>&1 && clear; return 0; }
PAUSE() { [ "$GM_YES" = 1 ] && return 0; [ -t 0 ] || return 0; printf '%sНажмите Enter...%s' "$C_DIM" "$NC"; read -r _p || true; echo; }

_maskurl()  { printf '%s' "${1:-}" | sed 's|/[^/]*$|/...|'; }
_row()      { printf '%s%-20s%s %s\n' "$C_Y" "$1:" "$NC" "$2"; }
_api_node() { controller_curl -s -m2 "http://127.0.0.1:9090/proxies/$1" 2>/dev/null | grep -oE '"now":"[^"]*"' | head -1 | sed 's/"now":"//;s/"$//'; }

_svc_row() { # _svc_row <label> <initd> <pidof-name>
  if [ ! -f "$(P /etc/init.d/$2)" ]; then _row "$1" "${C_DIM}не установлен${NC}"; return; fi
  if pidof "${3:-$2}" >/dev/null 2>&1; then _row "$1" "${C_G}запущен${NC}"; else _row "$1" "${C_R}остановлен${NC}"; fi
}

dashboard() {
  _model=$(cat "$(P /tmp/sysinfo/model)" 2>/dev/null)
  _rel=$(grep '^DISTRIB_RELEASE=' "$(P /etc/openwrt_release)" 2>/dev/null | cut -d"'" -f2)
  _row "Роутер" "${_model:-OpenWrt}${_rel:+ ${C_DIM}/ OpenWrt $_rel${NC}}"
  _svc_row "Zapret" zapret nfqws
  _svc_row "Mihomo" mihomo
  _svc_row "MagiTrickle" magitrickle magitrickled
  _svc_row "HevSocks5" hev-socks5-tunnel
  _svc_row "Dnsmasq" dnsmasq
  if [ -x "$(P /etc/init.d/adblock-fast)" ]; then
    _ab=$(grep -c 'server=/' "$(P /var/run/adblock-fast/dnsmasq.servers)" 2>/dev/null)
    _row "Adblock" "${C_G}${_ab:-0} доменов${NC}"
  fi
  _vpn=$(_api_node VPN); _ai=$(_api_node AI)
  _row "VPN узел" "${_vpn:-${C_DIM}нет ответа API${NC}}"
  _row "AI узел"  "${_ai:-${C_DIM}нет ответа API${NC}}"
  if [ -s "$(P /usr/bin/geo-backend.sh)" ] && ubus list 2>/dev/null | grep -qx 'geo-sync'; then
    _row "Geo LuCI" "${C_G}установлена${NC}"
  else
    _row "Geo LuCI" "${C_R}не установлена${NC}"
  fi
  if ip link show AI >/dev/null 2>&1; then _ait="${C_G}поднят${NC}"; else _ait="${C_DIM}нет${NC}"; fi
  _naic=$(grep -c ' ai ' "$(P /etc/geo-devices.list)" 2>/dev/null)
  _row "AI-туннель" "$_ait${_naic:+ · устройств: ${_naic:-0}}"
  _mt=$(grep -c 'DOMAIN-SUFFIX' "$(P /etc/mihomo/ruleset/mtrickle.yaml)" 2>/dev/null)
  _row "Sync правил" "${_mt:-0} в mtrickle.yaml"
  if [ -f "$(P /root/.geomask-norestart)" ]; then
    _row "VPN-рестарты" "${C_G}запрещены (pin)${NC}"
  else
    _row "VPN-рестарты" "${C_Y}разрешены${NC}"
  fi
}

print_banner() {
  printf '%s+========================================+%s\n' "$C_M" "$NC"
  printf '%s|%s      %sGEOMASK%s  -  geo-masking stack   %s|%s\n' "$C_M" "$NC" "$C_B" "$NC" "$C_M" "$NC"
  printf '%s+========================================+%s %sv%s%s\n' "$C_M" "$NC" "$C_DIM" "$GM_VERSION" "$NC"
}

show_menu() {
  echo
  printf '%s1)%s %sБыстрая диагностика%s %s(только чтение)%s\n'    "$C_B" "$NC" "$C_G" "$NC" "$C_DIM" "$NC"
  printf '%s2)%s %sПошаговый мастер%s %s(статус шагов, запуск любого отдельно)%s\n' "$C_B" "$NC" "$C_G" "$NC" "$C_DIM" "$NC"
  printf '%s3)%s %sПанель Гео%s %s(переустановить / обновить)%s\n'  "$C_B" "$NC" "$C_G" "$NC" "$C_DIM" "$NC"
  printf '%sf)%s %sУдалить -> установить -> настроить geomask%s\n'  "$C_B" "$NC" "$C_Y" "$NC"
  printf '%s0)%s Выход\n'                                          "$C_B" "$NC"
}

diag_quick() {
  PASS=0; FAILCNT=0; SKIP=0
  GM_CHECK_ONLY=1
  for n in 1 2 3 4 5 6 7; do run_step "$n" || true; done
  GM_CHECK_ONLY=0
  echo
  log "${C_DIM}== ДИАГНОСТИКА: pass=$PASS fail=$FAILCNT ==$NC"
}

# human-readable description of each step (bypasses ANY memory of "what is what")
step_desc() {
  case "$1" in
    env)      printf 'проверка окружения: версия OpenWrt, место на диске, зависимости (только чтение)' ;;
    geo)      printf 'гео-оверлей: панель "Гео-маскировка и AI" в LuCI + бэкенд geo-sync' ;;
    subs)     printf 'подписки: ссылки VPN/AI и группы VPN/AI в mihomo (проверка доступности)' ;;
    sync)     printf 'sync: синк magitrickle→mihomo: watchdog (секунды) + cron-страховка' ;;
    services) printf 'сервисы: mihomo, magitrickle, hev-туннели, dnsmasq, веб-интерфейс' ;;
    verify)   printf 'сквозная проверка: выходы VPN/AI, DNS, группа AI, интернет (ничего не меняет)' ;;
    *)        printf '' ;;
  esac
}

# step-by-step master: show status of every step, let the user run any single step
menu_master() {
  while :; do
    _n=1
    for _nm in $STEP_NAMES; do
      _d=$(step_desc "$_nm")
      if step_fn "$_n" check >/dev/null 2>&1; then
        printf '  %s%d)%s %s%-9s%s %s — %s %sвыполнено%s\n' "$C_B" "$_n" "$NC" "$C_Y" "$_nm" "$NC" "$_d" "$C_G" "$NC"
      else
        printf '  %s%d)%s %s%-9s%s %s — %s %sтребует внимания%s\n' "$C_B" "$_n" "$NC" "$C_Y" "$_nm" "$NC" "$_d" "$C_R" "$NC"
      fi
      _n=$((_n+1))
    done
    echo
    printf 'Номер шага для запуска (Enter - назад): '
    read -r _sel || return
    case "$_sel" in
      ''|q|Q) return ;;
      [1-7]) run_step "$_sel" || true; PAUSE ;;
      *) printf '%sнет такого шага%s\n' "$C_R" "$NC"; sleep 1 ;;
    esac
  done
}

# prompt for a subscription URL; keeps current value on Enter; honors flags/--yes
# A prompt belongs on the terminal: stdout is the function's return value (the URL), and the
# installer captures stdout. Printing the question there put `VPN URL [Enter ...]: ` in front of
# the URL (audit I06). GM_PROMPT_TTY lets a fixture exercise the interactive path without a tty.
_prompt_tty() { [ -t 0 ] || [ "${GM_PROMPT_TTY:-}" = 1 ]; }

prompt_url() { # prompt_url <label> <current> <flag-value>  -> prints url, rc=1 if none
  _lbl="$1"; _cur="$2"; _flag="$3"
  if [ -n "$_flag" ]; then printf '%s' "$_flag"; return 0; fi
  if [ -n "$_cur" ]; then
    if [ "$GM_YES" = 1 ] || ! _prompt_tty; then printf '%s' "$_cur"; return 0; fi
    printf '%s [Enter = оставить %s]: ' "$_lbl" "$(_maskurl "$_cur")" >&2
    read -r _v || _v=""
    printf '%s' "${_v:-$_cur}"
    return 0
  fi
  if [ "$GM_YES" = 1 ] || ! _prompt_tty; then return 1; fi
  while :; do
    printf '%s: ' "$_lbl" >&2
    read -r _v || return 1
    case "$_v" in
      http://*|https://*) printf '%s' "$_v"; return 0 ;;
      '') return 1 ;;
      *) printf '  URL должен начинаться с http:// или https://\n' >&2 ;;
    esac
  done
}

# remove geomask parts (geo overlay, sync script, cron); keeps mihomo config
# $1 = noreload: skip the rpcd reload (caller re-registers right after install)
geomask_uninstall() {
  # Every crontab rewrite below is a read-modify-write. Hold the shared `cron` lock for the
  # whole removal so a panel nodes_set/sync_set cannot re-add a line from a stale read while
  # the uninstall removes it (report R09). --reinstall calls this with the maintenance lock
  # already held; the fixed order allows maintenance(10) -> cron(50).
  _un_cron=0
  if _cron_begin; then
    _un_cron=1
  else
    warn "cron: блокировка недоступна - строки cron не трогаю"
  fi
  for f in /usr/bin/geo-backend.sh /usr/libexec/rpcd/geo-sync \
           /usr/share/rpcd/acl.d/luci-app-geo-sync.json \
           /usr/share/luci/menu.d/luci-app-geo-sync.json; do
    if [ -f "$(P "$f")" ]; then rm -f "$(P "$f")"; info "removed: $f"; fi
  done
  rm -f "$(P /www/luci-static/resources/view/geo-sync/main.js)" 2>/dev/null || true
  rmdir "$(P /www/luci-static/resources/view/geo-sync)" 2>/dev/null || true
  if [ -f "$(P /root/sync_mtrickle_mihomo.sh)" ]; then rm -f "$(P /root/sync_mtrickle_mihomo.sh)"; info "removed: sync script"; fi
  # v1.10.0: stop+remove the event sync watchdog
  if [ -x "$(P /etc/init.d/geomask-syncd)" ]; then
    initd geomask-syncd stop >/dev/null 2>&1 || true
    initd geomask-syncd disable >/dev/null 2>&1 || true
    pkill -f geomask-syncd.sh 2>/dev/null || true
    rm -f "$(P /etc/init.d/geomask-syncd)" "$(P /usr/bin/geomask-syncd.sh)"
    info "removed: syncd watchdog"
  fi
  # v1.11.0: node audit removal
  if [ "$_un_cron" = 1 ] && crontab -l 2>/dev/null | grep -q 'geomask-node-scan'; then
    crontab -l 2>/dev/null | grep -v 'geomask-node-scan' | crontab - 2>/dev/null || true
  fi
  rm -f "$(P /usr/bin/geomask-node-scan.sh)"
  info "removed: node-scan (conf /etc/geomask-nodes.conf left for reference)"
  # v1.14.0: youtube edge watchdog removal. Release the auto-pins ONLY on a real uninstall:
  # --reinstall calls this too, and resetting there wiped every accumulated edge pin
  # (observed 31.10 18:21 - a self-update dropped 10 working pins).
  if [ -z "$1" ] && [ -x "$(P /usr/bin/geomask-ytwatch.sh)" ]; then
    "$(P /usr/bin/geomask-ytwatch.sh)" --reset >/dev/null 2>&1
  fi
  if [ "$_un_cron" = 1 ] && crontab -l 2>/dev/null | grep -q 'geomask-ytwatch'; then
    crontab -l 2>/dev/null | grep -v 'geomask-ytwatch' | crontab - 2>/dev/null || true
  fi
  rm -f "$(P /usr/bin/geomask-ytwatch.sh)"
  info "removed: ytwatch (conf /etc/geomask-ytwatch.conf and /etc/geomask/ytwatch.state kept for reference)"
  # v1.15.0: torrent admin removal (ruleset + listener left in place: they belong to mihomo config)
  rm -f "$(P /usr/bin/geomask-torrent.sh)"
  info "removed: torrent admin (lists in /etc/geomask/torrent and the ruleset kept for reference)"
  # v1.18.0: vpnwatch removal (the audit log is kept - it is the evidence the operator collected)
  if [ "$_un_cron" = 1 ] && crontab -l 2>/dev/null | grep -q 'geomask-vpnwatch'; then
    crontab -l 2>/dev/null | grep -v 'geomask-vpnwatch' | crontab - 2>/dev/null || true
  fi
  rm -f "$(P /usr/bin/geomask-vpnwatch.sh)"
  rm -f "$(P /usr/bin/geomask-morning-check.sh)"
  # The lane owns a service and a listener. Remove it ONLY on a real uninstall: --reinstall goes
  # through this function too, and wiping the lane there silently deletes an interface the owner
  # has assigned MagiTrickle lists to (same class of bug as the YouTube pins, fixed in v1.20.x).
  if [ -z "$1" ] && [ -x "$(P /usr/bin/geomask-lane.sh)" ]; then
    "$(P /usr/bin/geomask-lane.sh)" remove >/dev/null 2>&1 || warn "lane removal reported a problem"
  fi
  rm -f "$(P /usr/bin/geomask-lane.sh)"
  rm -f "$(P /usr/bin/geomask-dnscheck.sh)"
  info "removed: vpnwatch (conf /etc/geomask/vpnwatch.conf and the audit log kept)"
  # v1.28.0: node-audit subsystem modules. The settings store (/etc/geomask/node-audit.json),
  # its event log and the immutable report/pool directories are deliberately KEPT - they are
  # the operator's desired policies and the evidence behind them.
  for _m in geomask-node-audit.py geomask-audit-state.py geomask-config-tx.py \
            geomask-config-owner.py geomask-apply.py geomask-lane-torrent.py \
            geomask-sync-youtube.py geomask-audit-scheduler.py geomask-subscription-status.py \
            geomask-slot-patch.py geomask-mihomo-adopt.py geomask-reload-state.py geomask-console.py geomask-dnsguard.sh \
            geomask-diag-spool.py; do
    rm -f "$(P /usr/lib/geomask/$_m)"
  done
  if [ "$_un_cron" = 1 ] && crontab -l 2>/dev/null | grep -q 'geomask-audit-schedule'; then
    crontab -l 2>/dev/null | grep -v 'geomask-audit-schedule' | crontab - 2>/dev/null || true
  fi
  info "removed: node-audit modules (settings, events and reports kept under /etc/geomask)"
  if [ "$_un_cron" = 1 ] && crontab -l 2>/dev/null | grep -q 'sync_mtrickle_mihomo'; then
    crontab -l 2>/dev/null | grep -v 'sync_mtrickle_mihomo' | crontab - 2>/dev/null && info "cron entry removed"
  fi
  # I11 (audit 18.11.2026): the uninstall left the guard (script, hotplug hook, 5-minute cron
  # line) and AI-DNS (two services, their init scripts and the nft table) behind, so an
  # "uninstalled" router kept re-seating rules and answering DNS. The catalogue declares what
  # each module owns, so exactly that is removed - the cron lock is already held here.
  for _un_mod in guard ai_dns; do
    modules_remove_runtime "$_un_mod" "удаление geomask" || true
  done
  [ "$1" = "noreload" ] || initd rpcd reload 2>/dev/null || true
  [ "$_un_cron" = 1 ] && _cron_end
  return 0
}

# ---- reinstall preflight and rollback ---------------------------------------
# geomask_uninstall deletes the panel, backend, RPC registration, cron entries and helper
# scripts. The old flow called it first and only then asked write_mihomo_config, which can
# refuse a foreign config - the refusal arrived after the components were already gone.
#
# R03 phase 2b: the snapshot/rollback is built from the manifest write-set
# (tests/reinstall_write_set.json), not from a hand-picked list. Byte objects come from the
# same table the preflight type-checks (REINSTALL_PREFLIGHT_BYTE_FILES, cross-checked 1:1 by
# tests/reinstall_manifest.py); shared files are restored by their managed subset only; the
# runtime state (services, rc.d links, uci keys, cron, nft/ip rule, per-interface IPv6
# sysctl) is recorded as data, not guessed at restore time. Every restored object is
# verified: bytes, mode, uci values, live nft/ip-rule, enabled AND running services, sysctl.
# An unverified or failed object keeps the snapshot and returns non-zero ("rollback
# incomplete / recovery required"); a concurrent write after the snapshot is a conflict.
#
# Deliberately NOT restored (manifest restore=NR, reported honestly as NR):
#   * mihomo provider cache / the controller API refresh - a network effect, not a file;
#   * network/firewall reload effects - applied and then verified, not "restored";
#   * witness logs (/root/geo-sync.log, node-audit events/pools/reports) and /tmp transients;
#   * MagiTrickle's config.yaml is owned by magitrickled: if it changed during the run the
#     rollback reports "incomplete" instead of pretending it was restored.
# The GM_AUTO_LANE branch (geomask-lane.sh install) creates uci/section ids inside a callee
# that this snapshot cannot journal; the reinstall refuses that branch before any mutation.
REINSTALL_TRACKED=""
REINSTALL_SHARED_APPEND="/etc/passwd|dnsai
/etc/group|dnsai
/opt/zapret/ipset/zapret-hosts-user-exclude.txt|zapret-block
/opt/zapret/ipset/zapret-hosts-user.txt|zapret-force"
REINSTALL_UCI_OBJECTS="network|lanai|section|proto,device,ipaddr,netmask
network|lan|option|ip6assign
dhcp|lan|option|ra,dhcpv6,ndp
ksmbd|geomask-backups|name|name,path,read_only,guest_ok,force_root"
REINSTALL_LIST_DIRS="/usr/bin /usr/lib/geomask /usr/libexec/rpcd /usr/share/rpcd/acl.d
/usr/share/luci/menu.d /usr/share/nftables.d/ruleset-post /etc /etc/config /etc/init.d
/etc/hotplug.d/iface /etc/geomask /etc/geomask/lists /etc/geomask/torrent /etc/mihomo
/etc/mihomo/ruleset /etc/nftables.d /etc/sysctl.d /etc/magitrickle/state
/etc/hev-socks5-tunnel /opt/zapret/ipset /root /www/luci-static/resources/view/geo-sync"
# Temporary names our writers create next to a manifest object (save_stream, the mihomo
# patcher, the lane). Only names that did NOT exist at snapshot time are removed: a backup
# or temp file another writer had before the transaction is never deleted.
REINSTALL_TEMP_SUFFIXES=".zmnew .de5rm .urlnew .tdnew .ecnew .gm.tmp"
# R04: the installer and the scanner now name their temps per process (two writers must not
# share one file), so a crash leaves <object>.zmnew.<pid> instead of <object>.zmnew. These
# globs are pruned only for objects the transaction snapshotted and only for names created
# after the snapshot; a file that was already there is in the listing and is left alone.
# Deliberately no generic `.tmp.*`: `<object>.tmp.<pid>` may be another writer's LIVE temporary
# (node-scan writes config.yaml.tmp.<pid> while the installer runs).
REINSTALL_TEMP_GLOBS=".zmnew.* .de5rm.* .urlnew.* .tdnew.* .ecnew.* .bak_nodescan.* .bak_aiguard.*"
# Objects the manifest marks restore=NR even though a byte preimage exists: the owner
# (a daemon) rewrites them, so a rollback must NOT write stale bytes over live state.
# They are recorded by identity+hash and the restore reports "incomplete" when they
# changed instead of silently restoring them.
REINSTALL_NR_STATE="/etc/magitrickle/state/config.yaml"

_rs_posix_path() { # <host-path> -> POSIX absolute path (drive form normalized)
  # Git Bash may return a native Windows path (Y:\..., //?/Y:/...) from readlink -f;
  # the router only ever has POSIX paths. Normalize before policy/pin comparison so the
  # decision does not depend on the test host's temp drive.
  _rs_pv=$1
  case "$_rs_pv" in
    //?/[A-Za-z]:/*) _rs_pv=$(printf '%s' "$_rs_pv" | sed 's#^//?/##') ;;
  esac
  case "$_rs_pv" in
    [A-Za-z]:*)
      _rs_pd=$(printf '%s' "$_rs_pv" | cut -c1 | tr 'A-Z' 'a-z')
      _rs_pr=${_rs_pv#??}
      _rs_pr=$(printf '%s' "$_rs_pr" | sed 's#\\#/#g')
      printf '/%s%s' "$_rs_pd" "$_rs_pr" ;;
    *) printf '%s' "$_rs_pv" ;;
  esac
}

_rs_readlink_posix() { # <abs-path> -> POSIX form of readlink -f
  _rs_rl=$(readlink -f "$1" 2>/dev/null) || return 1
  _rs_posix_path "$_rs_rl"
}

_rs_trusted_link() { # <resolved-target> -> 0 when the target lives under a trusted root
  _rs_tv=$(_rs_posix_path "$1")
  # Policy (phase 2e): a storage symlink is legitimate when it points into a stable,
  # root-owned tree. /tmp-style trees, arbitrary mounts and user-writable roots are not.
  case "$_rs_tv" in
    /overlay/*|/mnt/*|/opt/*|/usr/*|/www/*|/etc/*) return 0 ;;
  esac
  _rs_troot=$(P / 2>/dev/null) || _rs_troot=""
  _rs_troot=${_rs_troot%/}
  if [ -n "${_rs_troot:-}" ] && [ "$_rs_troot" != "/" ]; then
    # Test/prefix trees: only the same logical roots as above are trusted. A link to an
    # arbitrary directory inside the fixture (rc-outside, init-outside) stays untrusted.
    case "$_rs_tv" in
      "$_rs_troot"/mnt/*|"$_rs_troot"/overlay/*|"$_rs_troot"/opt/*| \
      "$_rs_troot"/usr/*|"$_rs_troot"/www/*|"$_rs_troot"/etc/*) return 0 ;;
    esac
  fi
  return 1
}

_rs_link_ok() { # <logical> <host-path> <dir|file> - policy + pinned identity
  _rs_lh=$(readlink -f "$2" 2>/dev/null) || return 1
  [ -n "${_rs_lh:-}" ] || return 1
  _rs_lr=$(_rs_posix_path "$_rs_lh")
  if [ "$3" = dir ]; then
    [ -d "$_rs_lh" ] || return 1
  else
    [ -f "$_rs_lh" ] || return 1
  fi
  _rs_lu=$(_rs_uid "$_rs_lh") || return 1
  _rs_self=$(id -u 2>/dev/null || printf '0')
  # On the router the installer runs as root, so only uid 0 is accepted. On a non-root
  # test host the fixture owner is the runner; that keeps the policy testable without
  # pretending a Windows temp tree is root-owned.
  if [ "$_rs_lu" != 0 ] && [ "$_rs_lu" != "$_rs_self" ]; then return 1; fi
  _rs_lm=$(_rs_mode "$_rs_lh") || return 1
  if [ $((0$_rs_lm & 2)) -ne 0 ]; then return 1; fi
  _rs_trusted_link "$_rs_lr" || return 1
  _rs_ld=$(_rs_devino "$_rs_lh") || return 1
  if [ "${_rs_pin_mode:-0}" = 1 ] && [ -n "${_rs_snap:-}" ]; then
    _rs_pin=$(awk -F'|' -v l="$1" '$1==l{print $2"|"$3; exit}' \
              "$_rs_snap/symlinks" 2>/dev/null)
    if [ -n "${_rs_pin:-}" ]; then
      [ "$_rs_pin" = "$_rs_lr|$_rs_ld" ] || return 1
      return 0
    fi
    printf '%s|%s|%s\n' "$1" "$_rs_lr" "$_rs_ld" >> "$_rs_snap/symlinks" 2>/dev/null \
      || return 1
    return 0
  fi
  if [ "${_rs_pin_enforce:-0}" = 1 ] && [ -n "${_rs_snap:-}" ] \
     && [ -f "$_rs_snap/symlinks" ]; then
    _rs_pin=$(awk -F'|' -v l="$1" '$1==l{print $2"|"$3; exit}' \
              "$_rs_snap/symlinks" 2>/dev/null)
    [ -n "${_rs_pin:-}" ] || return 1
    [ "$_rs_pin" = "$_rs_lr|$_rs_ld" ] || return 1
  fi
  return 0
}

_rs_safe_walk() { # <install-path> <dir|file|exec>
  _rs_pp=""
  _rs_pr=${1#/}
  while [ -n "$_rs_pr" ]; do
    _rs_pc=${_rs_pr%%/*}
    if [ "$_rs_pc" = "$_rs_pr" ]; then _rs_pr=""; else _rs_pr=${_rs_pr#*/}; fi
    _rs_pp="$_rs_pp/$_rs_pc"
    _rs_pa="$(P "$_rs_pp")"
    if [ -L "$_rs_pa" ]; then
      if [ -z "$_rs_pr" ] && [ "$2" = file ]; then return 1; fi
      _rs_want=dir
      if [ -z "$_rs_pr" ] && [ "$2" = exec ]; then _rs_want=file; fi
      _rs_link_ok "$_rs_pp" "$_rs_pa" "$_rs_want" || return 1
    fi
  done
  return 0
}

_rs_safe_path() { # directories: a symlink component is allowed only by the policy + pin
  _rs_safe_walk "$1" dir
}

_rs_safe_file() { # byte files: the leaf itself must never be a symlink
  _rs_safe_walk "$1" file
}

_rs_safe_exec() { # init scripts: a trusted root-owned file symlink is legible
  _rs_safe_walk "$1" exec
}

_rs_critical_paths_safe() { # every path the rollback writes, reads or executes through
  for _rs_cpp in /etc /etc/init.d /etc/rc.d /etc/config /etc/config/network \
                  /etc/config/dhcp /etc/config/ksmbd /etc/config/firewall \
                  /etc/sysctl.d /etc/geomask /etc/mihomo /etc/nftables.d \
                  /etc/hotplug.d/iface /etc/magitrickle/state \
                  /usr/bin /usr/lib /usr/lib/geomask /usr/libexec/rpcd \
                  /usr/share/nftables.d/ruleset-post /usr/share/rpcd/acl.d \
                  /usr/share/luci/menu.d /root /opt/zapret/ipset \
                  /www/luci-static/resources/view/geo-sync; do
    if ! _rs_safe_path "$_rs_cpp"; then
      bad "conflict: $_rs_cpp is behind an unsafe or unpinned symlink - refusing any write/read/exec through it"
      return 1
    fi
  done
  return 0
}

_rs_iprule_state() { # -> absent | "<pref>|<table>|<ours|foreign>;..." for EVERY same-mark rule
  _rs_ir=$(ip rule show 2>/dev/null) || return 1
  _rs_rows=$(printf '%s\n' "$_rs_ir" | awk -v m="$AIDNS_MARK" -v ours="$AIDNS_RULE_PREF" '
    { hit = 0
      for (i = 1; i < NF; i++) if ($i == "fwmark" && $(i + 1) == m) hit = 1
      if (!hit) next
      p = $1; sub(/:$/, "", p)
      t = ""
      for (i = 1; i < NF; i++) if ($i == "lookup" || $i == "table") t = $(i + 1)
      print p "|" t "|" (p == ours ? "ours" : "foreign") }')
  if [ -z "${_rs_rows:-}" ]; then printf 'absent'; return 0; fi
  printf '%s' "$_rs_rows" | LC_ALL=C sort -n | tr '\n' ';' | sed 's/;$//'
}

_rs_ksmbd_live_sig() { # semantic signature of OUR ksmbd share sections (ids are unstable)
  for _rs_ks in $(_rs_ksmbd_ours geomask-backups); do
    uci -q show ksmbd 2>/dev/null | awk -v p="$_rs_ks." '
      index($0, p) == 1 { print substr($0, length(p) + 1) }' | sort | tr '\n' ';'
    printf '\n'
  done | grep . | sort
}

_rs_ksmbd_snap_sig() { # the same signature reconstructed from the snapshot rows
  _rs_kids=$(sed -n 's/^uci|ksmbd|\(@match[0-9]*\)|@type|share$/\1/p' "$_rs_snap/uci" 2>/dev/null | sort -u)
  for _rs_kid in $_rs_kids; do
    sed -n "s/^uci|ksmbd|$_rs_kid|\([^|]*\)|\(.*\)$/\1='\2'/p" "$_rs_snap/uci" 2>/dev/null \
      | grep -v '^@type=' | sort | tr '\n' ';'
    printf '\n'
  done | grep . | sort
}

_rs_check_snapshot() { # _rs_check_snapshot <dir> - a damaged snapshot is refused as a whole
  for _rs_need in objects meta listing links services uci sysctl net cron shared \
                  symlinks nft-ai.list nft-v6.list; do
    if [ ! -f "$_rs_snap/$_rs_need" ]; then
      bad "rollback incomplete / recovery required: snapshot $_rs_snap is incomplete ($_rs_need missing)"
      return 1
    fi
  done
  _rs_ckv=0
  while IFS='|' read -r _rs_ck _rs_cp _rs_ca _rs_cb _rs_cc _rs_cd _rs_ce; do
    [ -n "${_rs_cp:-}" ] || continue
    if [ "$_rs_ck" = file ] && [ ! -f "$_rs_snap/files$_rs_cp" ]; then
      bad "rollback incomplete / recovery required: snapshot lost the copy of $_rs_cp"
      _rs_ckv=1
    fi
  done < "$_rs_snap/objects"
  while IFS='|' read -r _rs_sc _rs_sp _rs_si _rs_sk _rs_sh _rs_sd _rs_sm; do
    [ -n "${_rs_sp:-}" ] || continue
    if [ "$_rs_sk" = regular ] && [ ! -f "$_rs_snap/shared.$_rs_si.pre" ]; then
      bad "rollback incomplete / recovery required: snapshot lost the managed preimage of shared file $_rs_sp"
      _rs_ckv=1
    fi
  done < "$_rs_snap/shared"
  return "$_rs_ckv"
}

_reinstall_save() { # _reinstall_save <snapshot-dir> <install-path> (legacy helper)
  [ -f "$(P "$2")" ] || return 0
  _rs_dir="$1/files$(dirname "$2")"
  mkdir -p "$_rs_dir" 2>/dev/null || return 1
  cp -p "$(P "$2")" "$_rs_dir/" 2>/dev/null || return 1
  printf '%s\n' "$2" >> "$1/present"
}

_rs_type() { # _rs_type <install-path> -> regular|symlink|dir|absent|unknown
  _rs_tp="$(P "$1")"
  if [ -L "$_rs_tp" ]; then printf 'symlink'; return 0; fi
  if [ -f "$_rs_tp" ]; then printf 'regular'; return 0; fi
  if [ -d "$_rs_tp" ]; then printf 'dir'; return 0; fi
  if [ -e "$_rs_tp" ]; then printf 'unknown'; return 0; fi
  if ls -d "$_rs_tp" >/dev/null 2>&1; then printf 'unknown'; return 0; fi
  printf 'absent'
}

_rs_mode() { # _rs_mode <abs-path> -> octal mode
  _rs_mv=$(stat -c '%a' "$1" 2>/dev/null)
  if [ -z "${_rs_mv:-}" ]; then _rs_mv=$(stat -f '%Lp' "$1" 2>/dev/null); fi
  [ -n "${_rs_mv:-}" ] || return 1
  printf '%s' "$_rs_mv"
}

_rs_uid() { # _rs_uid <abs-path>
  _rs_uv=$(stat -c '%u' "$1" 2>/dev/null)
  [ -n "${_rs_uv:-}" ] || return 1
  printf '%s' "$_rs_uv"
}

_rs_devino() { # _rs_devino <abs-path>
  _rs_dv=$(stat -c '%d:%i' "$1" 2>/dev/null)
  [ -n "${_rs_dv:-}" ] || return 1
  printf '%s' "$_rs_dv"
}

_rs_size() { # _rs_size <abs-path>
  _rs_sv=$(stat -c '%s' "$1" 2>/dev/null)
  [ -n "${_rs_sv:-}" ] || return 1
  printf '%s' "$_rs_sv"
}

_rs_stat4() { # _rs_stat4 <abs-path> -> "mode|uid|dev:ino|size" in one stat call
  _rs_p4=$(stat -c '%a|%u|%d:%i|%s' "$1" 2>/dev/null)
  [ -n "${_rs_p4:-}" ] || return 1
  printf '%s' "$_rs_p4"
}

_rs_hash() { # _rs_hash <abs-path> -> sha256:<hex> (md5 fallback)
  if have sha256sum; then
    _rs_hv=$(sha256sum "$1" 2>/dev/null | cut -d' ' -f1)
    [ -n "${_rs_hv:-}" ] || return 1
    printf 'sha256:%s' "$_rs_hv"
    return 0
  fi
  if have md5sum; then
    _rs_hv=$(md5sum "$1" 2>/dev/null | cut -d' ' -f1)
    [ -n "${_rs_hv:-}" ] || return 1
    printf 'md5:%s' "$_rs_hv"
    return 0
  fi
  return 1
}

_rs_hash_stream() { # _rs_hash_stream (stdin) -> sha256:<hex> (md5 fallback)
  if have sha256sum; then
    printf 'sha256:%s' "$(sha256sum 2>/dev/null | cut -d' ' -f1)"
    return 0
  fi
  if have md5sum; then
    printf 'md5:%s' "$(md5sum 2>/dev/null | cut -d' ' -f1)"
    return 0
  fi
  return 1
}

_rs_is_nr_state() { # _rs_is_nr_state <install-path> -> 0 when the object is restore=NR
  for _rs_np in ${REINSTALL_NR_STATE:-}; do
    [ "$_rs_np" = "$1" ] && return 0
  done
  return 1
}

_rs_in_list() { # _rs_in_list <snapshot-dir> <install-path> -> 0 when it existed at snapshot
  [ -f "$1/listing" ] || return 1
  grep -qxF -- "$2" "$1/listing" 2>/dev/null
}

_rs_is_shared() { # _rs_is_shared <install-path> -> 0 for a shared file with a managed subset
  while IFS='|' read -r _rs_if _rs_ic; do
    [ -n "${_rs_if:-}" ] || continue
    [ "$_rs_if" = "$1" ] && return 0
  done <<EOF
${REINSTALL_SHARED_APPEND:-}
EOF
  return 1
}

_rs_note() { info "NR (not restorable): $*"; }

_rs_svc_scope() { # _rs_svc_scope <manifest service id> -> 0 when the reinstall touches it
  case "$1" in
    svc.ai-doh|svc.dnsmasq-ai)
      module_selected ai_dns && [ ! -f "$(P /etc/geomask-aidns.off)" ] ;;
    svc.hev-socks5-tunnel)
      module_selected path_ai || module_selected ai_dns ;;
    svc.hev-nop2p)
      [ -n "${GM_AUTO_LANE:-}" ] ;;
    svc.ksmbd)
      module_selected backup_share ;;
    *)
      return 0 ;;
  esac
}

_rs_svc_enabled() { # _rs_svc_enabled <initd-names-slash-separated> -> 1|0|unknown
  _rs_re="$(P /etc/rc.d)"
  if ! _rs_safe_path /etc/rc.d || [ ! -d "$_rs_re" ] || ! ls "$_rs_re" >/dev/null 2>&1; then
    printf 'unknown'; return 0
  fi
  for _rs_sn in $(printf '%s' "$1" | tr '/' ' '); do
    if ls "$_rs_re" 2>/dev/null | grep -qE "^S[0-9][0-9]${_rs_sn}$"; then
      printf '1'; return 0
    fi
  done
  printf '0'
}

_rs_svc_running() { # _rs_svc_running <pid-or-port> <mode> -> 1|0|unknown
  case "${2:-pidof}" in
    pgrep)
      have pgrep || { printf 'unknown'; return 0; }
      pgrep -f "$1" >/dev/null 2>&1 && printf '1' || printf '0'
      ;;
    port)
      if have netstat; then
        netstat -ltnu 2>/dev/null | grep -q ":$1 " && printf '1' || printf '0'
      else
        printf 'unknown'
      fi
      ;;
    *)
      if have pidof; then
        pidof "$1" >/dev/null 2>&1 && printf '1' || printf '0'
      elif have pgrep; then
        pgrep -x "$1" >/dev/null 2>&1 && printf '1' || printf '0'
      else
        printf 'unknown'
      fi
      ;;
  esac
}

_rs_settle() { [ "${GM_RESTORE_VERIFY_TRIES:-2}" = 1 ] && return 0; sleep 1; }

_rs_start_service() { # _rs_start_service <initd-names>
  for _rs_ss in $(printf '%s' "$1" | tr '/' ' '); do
    if ! _rs_safe_exec "/etc/init.d/$_rs_ss"; then
      bad "conflict: /etc/init.d/$_rs_ss is behind an unsafe or unpinned symlink - refusing to execute it"
      _rr=1
      return 1
    fi
    _rs_sp="$(P "/etc/init.d/$_rs_ss")"
    if [ -f "$_rs_sp" ]; then
      initd "$_rs_ss" start >/dev/null 2>&1
      return $?
    fi
  done
  return 1
}

_rs_stop_service() { # _rs_stop_service <initd-names>
  for _rs_ss in $(printf '%s' "$1" | tr '/' ' '); do
    if ! _rs_safe_exec "/etc/init.d/$_rs_ss"; then
      bad "conflict: /etc/init.d/$_rs_ss is behind an unsafe or unpinned symlink - refusing to execute it"
      _rr=1
      return 1
    fi
    _rs_sp="$(P "/etc/init.d/$_rs_ss")"
    if [ -f "$_rs_sp" ]; then
      initd "$_rs_ss" stop >/dev/null 2>&1
      return $?
    fi
  done
  return 1
}

_rs_link_owned() { # _rs_link_owned <svc-name> -> 0 when the snapshot tracks that service
  [ -f "$_rs_snap/services" ] || return 1
  while IFS='|' read -r _rs_li _rs_lin _rs_lip _rs_lim _rs_lie _rs_lir; do
    [ -n "${_rs_lin:-}" ] || continue
    for _rs_ls in $(printf '%s' "$_rs_lin" | tr '/' ' '); do
      [ "$_rs_ls" = "$1" ] && return 0
    done
  done < "$_rs_snap/services"
  return 1
}

_rs_ksmbd_ours() { # _rs_ksmbd_ours <share-name> -> uci section paths of OUR share only
  _rs_ka=$(uci -q show ksmbd 2>/dev/null | sed -n 's/^\(ksmbd\.[^=]*\)=share$/\1/p')
  for _rs_ks in $_rs_ka; do
    if [ "$(uci -q get "$_rs_ks.name" 2>/dev/null)" = "$1" ]; then
      printf '%s\n' "$_rs_ks"
    fi
  done
}

_rs_shared_neutral() { # _rs_shared_neutral <class> <abs-file> -> the part geomask does not own
  case "$1" in
    dnsai)
      awk -v u="$AIDNS_USER" 'index($0, u ":") != 1' "$2" ;;
    zapret-block)
      awk -v b='# >>> geomask sync: tunneled domains (generated) >>>' \
          -v e="# <<< geomask sync: tunneled domains <<<" '
        $0 == b { skip = 1; next }
        $0 == e { skip = 0; next }
        !skip { print }' "$2" ;;
    zapret-force)
      awk -v m='# geomask: tunneled, DPI removed' '
        index($0, m) == 1 { print substr($0, length(m) + 2); next }
        { print }' "$2" ;;
    *)
      cat "$2" ;;
  esac
}

_rs_snap_listing() { # _rs_snap_listing <dir> - names that existed before the transaction
  : > "$_rs_snap/listing" || return 1
  for _rs_ld in ${REINSTALL_LIST_DIRS:-}; do
    _rs_lp="$(P "$_rs_ld")"
    [ -d "$_rs_lp" ] || continue
    if ! _rs_safe_path "$_rs_ld"; then
      bad "snapshot: listing directory $_rs_ld is behind a symlink"
      return 1
    fi
    for _rs_lf in "$_rs_lp"/* "$_rs_lp"/.[!.]*; do
      [ -e "$_rs_lf" ] || [ -L "$_rs_lf" ] || continue
      printf '%s\n' "${_rs_lf#"$GM_PREFIX"}" >> "$_rs_snap/listing" 2>/dev/null || return 1
    done
  done
  return 0
}

_rs_snap_cron() { # _rs_snap_cron <dir>
  crontab -l > "$_rs_snap/cron" 2>/dev/null
  _rs_cr=$?
  case "$_rs_cr" in
    0|1) : ;;
    *) bad "snapshot: crontab state unobservable (crontab -l rc=$_rs_cr)"; return 1 ;;
  esac
  [ -f "$_rs_snap/cron" ] || : > "$_rs_snap/cron"
  return 0
}

_rs_snap_files() { # _rs_snap_files <dir> - byte objects of the manifest
  while IFS='|' read -r _rs_fp _rs_fe; do
    [ -n "${_rs_fp:-}" ] || continue
    _rs_is_shared "$_rs_fp" && continue
    if [ "$_rs_fe" = dir-or-absent ]; then
      if ! _rs_safe_path "$_rs_fp"; then
        bad "snapshot: $_rs_fp is behind an unsafe or unpinned symlink"
        return 1
      fi
    else
      if ! _rs_safe_file "$_rs_fp"; then
        bad "snapshot: $_rs_fp is a symlink (byte object; links are not restored as bytes)"
        return 1
      fi
    fi
    _rs_ft=$(_rs_type "$_rs_fp")
    if _rs_is_nr_state "$_rs_fp"; then
      case "$_rs_ft" in
        regular)
          _rs_fa="$(P "$_rs_fp")"
          _rs_f4=$(_rs_stat4 "$_rs_fa") || { bad "snapshot: cannot stat $_rs_fp"; return 1; }
          _rs_fm=${_rs_f4%%|*}; _rs_fr=${_rs_f4#*|}
          _rs_fu=${_rs_fr%%|*}; _rs_fr=${_rs_fr#*|}
          _rs_fi=${_rs_fr%%|*}; _rs_fs=${_rs_fr#*|}
          _rs_fh=$(_rs_hash "$_rs_fa") || { bad "snapshot: cannot hash $_rs_fp"; return 1; }
          printf 'norestore|%s|%s|%s|%s|%s|%s\n' "$_rs_fp" "$_rs_fm" "$_rs_fu" "$_rs_fi" "$_rs_fs" "$_rs_fh" >> "$_rs_snap/objects" ;;
        absent)
          printf 'norestore-absent|%s|-\n' "$_rs_fp" >> "$_rs_snap/objects" ;;
        *)
          bad "snapshot: NR object $_rs_fp has unrestorable type $_rs_ft"
          return 1 ;;
      esac
      continue
    fi
    case "$_rs_ft" in
      symlink)
        if [ "$_rs_fe" = dir-or-absent ] && [ -d "$(P "$_rs_fp")" ]; then
          # A trusted storage link (extroot-style /etc/mihomo, /etc/geomask) is a
          # directory object: keep the link, pin its target identity, restore metadata.
          _rs_fa="$(P "$_rs_fp")"
          _rs_f4=$(_rs_stat4 "$_rs_fa") || { bad "snapshot: cannot stat $_rs_fp"; return 1; }
          _rs_fm=${_rs_f4%%|*}; _rs_fr=${_rs_f4#*|}
          _rs_fu=${_rs_fr%%|*}; _rs_fr=${_rs_fr#*|}
          _rs_fi=${_rs_fr%%|*}
          _rs_lh=$(readlink -f "$_rs_fa" 2>/dev/null) || _rs_lh=""
          [ -n "${_rs_lh:-}" ] || { bad "snapshot: cannot resolve $_rs_fp"; return 1; }
          _rs_lr=$(_rs_posix_path "$_rs_lh")
          _rs_ld=$(_rs_devino "$_rs_lh") || { bad "snapshot: cannot pin $_rs_fp"; return 1; }
          printf 'dirlink|%s|%s|%s|%s|%s|-\n' \
            "$_rs_fp" "$_rs_fm" "$_rs_fu" "$_rs_ld" "$_rs_lr" >> "$_rs_snap/objects"
          continue
        fi
        bad "snapshot: unrestorable object: $_rs_fp is a symlink (the snapshot restores bytes, not links)"
        return 1 ;;
      unknown)
        bad "snapshot: unobservable object: $_rs_fp"
        return 1 ;;
      absent)
        printf 'absent|%s|-\n' "$_rs_fp" >> "$_rs_snap/objects" ;;
      dir)
        if [ "$_rs_fe" != dir-or-absent ]; then
          bad "snapshot: $_rs_fp is a directory, expected $_rs_fe"
          return 1
        fi
        _rs_fa="$(P "$_rs_fp")"
        _rs_f4=$(_rs_stat4 "$_rs_fa") || { bad "snapshot: cannot stat $_rs_fp"; return 1; }
        _rs_fm=${_rs_f4%%|*}; _rs_fr=${_rs_f4#*|}
        _rs_fu=${_rs_fr%%|*}; _rs_fr=${_rs_fr#*|}
        _rs_fi=${_rs_fr%%|*}
        printf 'dir|%s|%s|%s|%s\n' "$_rs_fp" "$_rs_fm" "$_rs_fu" "$_rs_fi" >> "$_rs_snap/objects" ;;
      regular)
        _rs_fdir="$_rs_snap/files$(dirname "$_rs_fp")"
        mkdir -p "$_rs_fdir" 2>/dev/null || { bad "snapshot: cannot create $_rs_fdir"; return 1; }
        _rs_fa="$(P "$_rs_fp")"
        cp -p "$_rs_fa" "$_rs_fdir/" 2>/dev/null || { bad "snapshot: cannot copy $_rs_fp"; return 1; }
        _rs_f4=$(_rs_stat4 "$_rs_fa") || { bad "snapshot: cannot stat $_rs_fp"; return 1; }
        _rs_fm=${_rs_f4%%|*}; _rs_fr=${_rs_f4#*|}
        _rs_fu=${_rs_fr%%|*}; _rs_fr=${_rs_fr#*|}
        _rs_fi=${_rs_fr%%|*}; _rs_fs=${_rs_fr#*|}
        _rs_fh=$(_rs_hash "$_rs_fa") || { bad "snapshot: cannot hash $_rs_fp (sha256sum/md5sum missing)"; return 1; }
        printf 'file|%s|%s|%s|%s|%s|%s\n' "$_rs_fp" "$_rs_fm" "$_rs_fu" "$_rs_fi" "$_rs_fs" "$_rs_fh" >> "$_rs_snap/objects" ;;
    esac
  done <<EOF
${REINSTALL_PREFLIGHT_BYTE_FILES:-}
EOF
  for _rs_fp in ${REINSTALL_TRACKED:-}; do
    _rs_is_shared "$_rs_fp" && continue
    if grep -qF "|$_rs_fp|" "$_rs_snap/objects" 2>/dev/null; then continue; fi
    if ! _rs_safe_file "$_rs_fp"; then
      bad "snapshot: extra tracked object $_rs_fp is a symlink"
      return 1
    fi
    _rs_ft=$(_rs_type "$_rs_fp")
    case "$_rs_ft" in
      regular)
        _rs_fdir="$_rs_snap/files$(dirname "$_rs_fp")"
        mkdir -p "$_rs_fdir" 2>/dev/null || { bad "snapshot: cannot create $_rs_fdir"; return 1; }
        _rs_fa="$(P "$_rs_fp")"
        cp -p "$_rs_fa" "$_rs_fdir/" 2>/dev/null || { bad "snapshot: cannot copy $_rs_fp"; return 1; }
        _rs_f4=$(_rs_stat4 "$_rs_fa") || return 1
        _rs_fm=${_rs_f4%%|*}; _rs_fr=${_rs_f4#*|}
        _rs_fu=${_rs_fr%%|*}; _rs_fr=${_rs_fr#*|}
        _rs_fi=${_rs_fr%%|*}; _rs_fs=${_rs_fr#*|}
        _rs_fh=$(_rs_hash "$_rs_fa") || return 1
        printf 'file|%s|%s|%s|%s|%s|%s\n' "$_rs_fp" "$_rs_fm" "$_rs_fu" "$_rs_fi" "$_rs_fs" "$_rs_fh" >> "$_rs_snap/objects" ;;
      absent)
        printf 'absent|%s|-\n' "$_rs_fp" >> "$_rs_snap/objects" ;;
      *)
        bad "snapshot: extra tracked object $_rs_fp is not a regular file or absent"
        return 1 ;;
    esac
  done
  return 0
}

_rs_snap_shared() { # _rs_snap_shared <dir> - managed subset of the shared files
  _rs_si=0
  while IFS='|' read -r _rs_sp _rs_sc; do
    [ -n "${_rs_sp:-}" ] || continue
    if ! _rs_safe_file "$_rs_sp"; then
      bad "snapshot: shared object $_rs_sp is a symlink - refusing to snapshot through it"
      return 1
    fi
    _rs_si=$((_rs_si+1))
    _rs_st=$(_rs_type "$_rs_sp")
    case "$_rs_st" in
      symlink)
        bad "snapshot: unrestorable shared object: $_rs_sp is a symlink"
        return 1 ;;
      dir)
        bad "snapshot: unrestorable shared object: $_rs_sp is a directory"
        return 1 ;;
      unknown)
        bad "snapshot: unobservable shared object: $_rs_sp"
        return 1 ;;
      absent)
        printf 'shared|%s|%s\n' "$_rs_sp" "$_rs_sc" >> "$_rs_snap/objects"
        printf '%s|%s|%s|absent|-|-|-\n' "$_rs_sc" "$_rs_sp" "$_rs_si" >> "$_rs_snap/shared"
        continue ;;
    esac
    _rs_sa="$(P "$_rs_sp")"
    _rs_s4=$(_rs_stat4 "$_rs_sa") || { bad "snapshot: cannot stat $_rs_sp"; return 1; }
    _rs_sm=${_rs_s4%%|*}; _rs_sr=${_rs_s4#*|}
    _rs_sd=${_rs_sr#*|}; _rs_sd=${_rs_sd%%|*}
    _rs_sh=$(_rs_shared_neutral "$_rs_sc" "$_rs_sa" | _rs_hash_stream) \
      || { bad "snapshot: cannot hash the managed part of $_rs_sp"; return 1; }
    : > "$_rs_snap/shared.$_rs_si.pre" || { bad "snapshot: cannot create shared.$_rs_si.pre"; return 1; }
    case "$_rs_sc" in
      dnsai)
        grep -E "^$AIDNS_USER:" "$_rs_sa" > "$_rs_snap/shared.$_rs_si.pre" 2>/dev/null || true ;;
      zapret-block)
        awk -v b='# >>> geomask sync: tunneled domains (generated) >>>' \
            -v e="# <<< geomask sync: tunneled domains <<<" '
          $0 == b { inb = 1 }
          inb { print }
          $0 == e { inb = 0 }' "$_rs_sa" > "$_rs_snap/shared.$_rs_si.pre" 2>/dev/null || true ;;
      zapret-force)
        # per-domain state before the run: A|domain = in the clear, M|domain = managed
        # (commented out by sync). A managed line returned to the clear must be re-commented,
        # which an "active domains only" preimage could not know (review 16.11, item 3).
        awk -v m='# geomask: tunneled, DPI removed' '
          index($0, m) == 1 { d = substr($0, length(m) + 2)
                              if (d != "") print "M|" d; next }
          $0 != "" && $0 !~ /^#/ { print "A|" $0 }' "$_rs_sa" \
          > "$_rs_snap/shared.$_rs_si.pre" 2>/dev/null || true ;;
    esac
    printf 'shared|%s|%s\n' "$_rs_sp" "$_rs_sc" >> "$_rs_snap/objects"
    printf '%s|%s|%s|regular|%s|%s|%s\n' "$_rs_sc" "$_rs_sp" "$_rs_si" "$_rs_sh" "$_rs_sd" "$_rs_sm" >> "$_rs_snap/shared"
  done <<EOF
${REINSTALL_SHARED_APPEND:-}
EOF
  return 0
}

_rs_snap_uci() { # _rs_snap_uci <dir> - preimage of the managed uci keys
  for _rs_up in network dhcp ksmbd; do
    if [ -f "$(P "/tmp/.uci/$_rs_up")" ]; then
      bad "snapshot: pending uci delta for $_rs_up - another writer is mid-edit; reinstall refused"
      return 1
    fi
  done
  while IFS='|' read -r _rs_pkg _rs_sel _rs_kind _rs_opts; do
    [ -n "${_rs_pkg:-}" ] || continue
    if ! _rs_safe_path "/etc/config/$_rs_pkg"; then
      bad "snapshot: /etc/config/$_rs_pkg is behind a symlink - refusing uci reads through it"
      return 1
    fi
    case "$_rs_kind" in
      section)
        if uci -q get "$_rs_pkg.$_rs_sel" >/dev/null 2>&1; then
          _rs_ty=$(uci -q get "$_rs_pkg.$_rs_sel" 2>/dev/null)
          printf 'uci|%s|%s|@type|%s\n' "$_rs_pkg" "$_rs_sel" "$_rs_ty" >> "$_rs_snap/uci"
          for _rs_o in $(printf '%s' "$_rs_opts" | tr ',' ' '); do
            if _rs_v=$(uci -q get "$_rs_pkg.$_rs_sel.$_rs_o" 2>/dev/null); then
              printf 'uci|%s|%s|%s|%s\n' "$_rs_pkg" "$_rs_sel" "$_rs_o" "$_rs_v" >> "$_rs_snap/uci"
            else
              printf 'uci|%s|%s|%s|<absent>\n' "$_rs_pkg" "$_rs_sel" "$_rs_o" >> "$_rs_snap/uci"
            fi
          done
        else
          printf 'uci|%s|%s|@type|<absent>\n' "$_rs_pkg" "$_rs_sel" >> "$_rs_snap/uci"
        fi ;;
      option)
        for _rs_o in $(printf '%s' "$_rs_opts" | tr ',' ' '); do
          if _rs_v=$(uci -q get "$_rs_pkg.$_rs_sel.$_rs_o" 2>/dev/null); then
            printf 'uci|%s|%s|%s|%s\n' "$_rs_pkg" "$_rs_sel" "$_rs_o" "$_rs_v" >> "$_rs_snap/uci"
          else
            printf 'uci|%s|%s|%s|<absent>\n' "$_rs_pkg" "$_rs_sel" "$_rs_o" >> "$_rs_snap/uci"
          fi
        done ;;
      name)
        _rs_mi=0
        for _rs_ms in $(_rs_ksmbd_ours "$_rs_sel"); do
          _rs_mi=$((_rs_mi+1))
          printf 'uci|%s|@match%d|@type|share\n' "$_rs_pkg" "$_rs_mi" >> "$_rs_snap/uci"
          # every option of OUR section is recorded: force_root appeared in the manifest
          # after phase 2b and a fixed allowlist silently dropped it.
          _rs_kol=$(uci -q show "$_rs_pkg" 2>/dev/null | awk -v p="$_rs_ms." '
            index($0, p) == 1 { rest = substr($0, length(p) + 1); sub(/=.*/, "", rest)
                                if (rest != "") print rest }')
          for _rs_ko in $_rs_kol; do
            if _rs_v=$(uci -q get "$_rs_ms.$_rs_ko" 2>/dev/null); then
              printf 'uci|%s|@match%d|%s|%s\n' "$_rs_pkg" "$_rs_mi" "$_rs_ko" "$_rs_v" >> "$_rs_snap/uci"
            else
              printf 'uci|%s|@match%d|%s|<absent>\n' "$_rs_pkg" "$_rs_mi" "$_rs_ko" >> "$_rs_snap/uci"
            fi
          done
        done
        [ "$_rs_mi" -gt 0 ] || printf 'uci|%s|@none|@type|<absent>\n' "$_rs_pkg" >> "$_rs_snap/uci"
        ;;
    esac
  done <<EOF
${REINSTALL_UCI_OBJECTS:-}
EOF
  return 0
}

_rs_snap_sysctl() { # _rs_snap_sysctl <dir> - per-interface disable_ipv6, never "0 by default"
  _rs_kd="$(P /proc/sys/net/ipv6/conf)"
  if ! _rs_safe_path /proc/sys/net/ipv6/conf || [ ! -d "$_rs_kd" ] || ! ls "$_rs_kd" >/dev/null 2>&1; then
    bad "snapshot: kernel sysctl state unobservable: /proc/sys/net/ipv6/conf"
    return 1
  fi
  for _rs_kf in "$_rs_kd"/*; do
    [ -d "$_rs_kf" ] || continue
    _rs_kn=${_rs_kf##*/}
    _rs_kv=$(cat "$_rs_kf/disable_ipv6" 2>/dev/null | tr -dc '01')
    case "$_rs_kv" in
      0|1) : ;;
      *) bad "snapshot: kernel sysctl unobservable: net.ipv6.conf.$_rs_kn.disable_ipv6"
         return 1 ;;
    esac
    printf 'sysctl|%s|%s\n' "$_rs_kn" "$_rs_kv" >> "$_rs_snap/sysctl"
  done
  return 0
}

_rs_snap_runtime() { # _rs_snap_runtime <dir> - tri-state enabled/running per service
  while IFS='|' read -r _rs_id _rs_kind _rs_initd _rs_pid _rs_mode _rs_extra; do
    [ "${_rs_kind:-}" = service ] || continue
    _rs_svc_scope "$_rs_id" || continue
    for _rs_is in $(printf '%s' "$_rs_initd" | tr '/' ' '); do
      if ! _rs_safe_exec "/etc/init.d/$_rs_is"; then
        bad "snapshot: init script /etc/init.d/$_rs_is is behind an unsafe or unpinned symlink"
        return 1
      fi
    done
    _rs_en=$(_rs_svc_enabled "$_rs_initd")
    _rs_run=$(_rs_svc_running "$_rs_pid" "$_rs_mode")
    if [ "$_rs_en" = unknown ]; then
      bad "snapshot: runtime state unobservable: $_rs_id (enabled unknown)"
      return 1
    fi
    if [ "$_rs_run" = unknown ]; then
      bad "snapshot: runtime state unobservable: $_rs_id (running unknown)"
      return 1
    fi
    printf '%s|%s|%s|%s|%s|%s\n' "$_rs_id" "$_rs_initd" "$_rs_pid" "$_rs_mode" "$_rs_en" "$_rs_run" >> "$_rs_snap/services"
  done <<EOF
${REINSTALL_PREFLIGHT_OBJECTS:-}
EOF
  # network/firewall are reloaded directly by the rollback even when their service row
  # is out of scope; pin them too so a target swap cannot redirect the reload.
  for _rs_is in network firewall; do
    if ! _rs_safe_exec "/etc/init.d/$_rs_is"; then
      bad "snapshot: /etc/init.d/$_rs_is is behind an unsafe or unpinned symlink"
      return 1
    fi
  done
  return 0
}

_rs_snap_links() { # <dir> - exact rc.d link names AND targets of our services
  _rs_ld="$(P /etc/rc.d)"
  if ! _rs_safe_path /etc/rc.d; then
    bad "snapshot: /etc/rc.d is behind a symlink - refusing to read autostart links through it"
    return 1
  fi
  if [ ! -d "$_rs_ld" ] || ! ls "$_rs_ld" >/dev/null 2>&1; then
    bad "snapshot: rc.d autostart links unobservable"
    return 1
  fi
  : > "$_rs_snap/links" || return 1
  for _rs_lf in "$_rs_ld"/*; do
    [ -L "$_rs_lf" ] || continue
    _rs_ln=${_rs_lf##*/}
    case "$_rs_ln" in
      [SK][0-9][0-9]*) : ;;
      *) continue ;;
    esac
    _rs_ls=${_rs_ln#[SK]}
    _rs_ls=${_rs_ls#??}
    _rs_link_owned "$_rs_ls" || continue
    _rs_lt=$(readlink "$_rs_lf" 2>/dev/null) \
      || { bad "snapshot: cannot read the target of $_rs_ln"; return 1; }
    printf '%s|%s\n' "$_rs_ln" "$_rs_lt" >> "$_rs_snap/links"
  done
  return 0
}

_rs_snap_net() { # _rs_snap_net <dir> - ip rule, nft table content, alias address
  ip rule show > "$_rs_snap/iprule.raw" 2>/dev/null \
    || { bad "snapshot: ip rule state unobservable"; return 1; }
  _rs_irs=$(_rs_iprule_state) || { bad "snapshot: ip rule state unobservable"; return 1; }
  printf 'iprule|%s\n' "$_rs_irs" >> "$_rs_snap/net"
  : > "$_rs_snap/nft-ai.list" || return 1
  : > "$_rs_snap/nft-v6.list" || return 1
  nft list table inet geomask_ai_dns > "$_rs_snap/nft-ai.list" 2>/dev/null
  _rs_nr=$?
  case "$_rs_nr" in
    0) printf 'nft-ai|present\n' >> "$_rs_snap/net" ;;
    1) : > "$_rs_snap/nft-ai.list"; printf 'nft-ai|absent\n' >> "$_rs_snap/net" ;;
    *) bad "snapshot: nft state unobservable: inet geomask_ai_dns (rc=$_rs_nr)"; return 1 ;;
  esac
  nft list chain inet fw4 geomask_no_v6 > "$_rs_snap/nft-v6.list" 2>/dev/null
  _rs_nr=$?
  case "$_rs_nr" in
    0) printf 'nft-v6|present\n' >> "$_rs_snap/net" ;;
    1) : > "$_rs_snap/nft-v6.list"; printf 'nft-v6|absent\n' >> "$_rs_snap/net" ;;
    *) bad "snapshot: nft state unobservable: inet fw4 geomask_no_v6 (rc=$_rs_nr)"; return 1 ;;
  esac
  _rs_ai=$(uci -q get network.lanai.ipaddr 2>/dev/null)
  _rs_ad=$(uci -q get network.lanai.device 2>/dev/null)
  if [ -n "${_rs_ai:-}" ]; then
    printf 'alias|present|%s|%s\n' "$_rs_ad" "$_rs_ai" >> "$_rs_snap/net"
  else
    printf 'alias|absent||\n' >> "$_rs_snap/net"
  fi
  return 0
}

_reinstall_snapshot() { # <dir> -> 0 when captured; pin mode is always reset
  _rs_pin_mode=1
  _rs_snapshot_capture "$@"
  _rs_snapshot_rc=$?
  _rs_pin_mode=0
  # A successful snapshot arms pin enforcement for the install actions that follow;
  # a failed/aborted snapshot must not leave the caller unable to use initd.
  if [ "$_rs_snapshot_rc" = 0 ]; then _rs_pin_enforce=1; else _rs_pin_enforce=0; fi
  return $_rs_snapshot_rc
}

_rs_snapshot_capture() { # <dir> - body of the snapshot, runs with pin mode 1
  _rs_snap="$1"
  mkdir -p "$_rs_snap/files" 2>/dev/null || return 1
  : > "$_rs_snap/symlinks" || return 1
  if ! _rs_critical_paths_safe; then
    bad "snapshot: unsafe or unpinned symlink in a tracked path; reinstall refused before mutation"
    return 1
  fi
  : > "$1/present"; : > "$1/absent"; : > "$1/rc.d"
  : > "$_rs_snap/objects" || return 1
  : > "$_rs_snap/listing" || return 1
  : > "$_rs_snap/links" || return 1
  : > "$_rs_snap/uci" || return 1
  : > "$_rs_snap/services" || return 1
  : > "$_rs_snap/sysctl" || return 1
  : > "$_rs_snap/net" || return 1
  : > "$_rs_snap/shared" || return 1
  printf 'schema=2\nprefix=%s\n' "$GM_PREFIX" > "$_rs_snap/meta" || return 1
  if [ -n "${GM_AUTO_LANE:-}" ]; then
    bad "snapshot: GM_AUTO_LANE is armed - geomask-lane.sh would create uci/service objects this snapshot cannot journal; reinstall refused before mutation"
    return 1
  fi
  _rs_snap_listing || return 1
  _rs_snap_cron || return 1
  _rs_snap_files || return 1
  _rs_snap_shared || return 1
  _rs_snap_uci || return 1
  _rs_snap_sysctl || return 1
  _rs_snap_runtime || return 1
  _rs_snap_links || return 1
  _rs_snap_net || return 1
  info "snapshot: state recorded in $_rs_snap"
  return 0
}

_rs_stop_new_services() { # _rs_stop_new_services <dir> - stop what the run started, BEFORE
  # file restore deletes the init scripts the failed install created. A refused stop is an
  # error: leaving a service running that was stopped before is not a rollback.
  [ -f "$_rs_snap/services" ] || return 0
  while IFS='|' read -r _rs_id _rs_initd _rs_pid _rs_mode _rs_en _rs_run; do
    [ -n "${_rs_id:-}" ] || continue
    [ "$_rs_run" = 0 ] || continue
    _rs_now=$(_rs_svc_running "$_rs_pid" "$_rs_mode")
    [ "$_rs_now" = 1 ] || continue
    _rs_stop_service "$_rs_initd" \
      || { bad "rollback: cannot stop $_rs_id (it was stopped before the run)"; _rr=1; }
  done < "$_rs_snap/services"
  return 0
}

_rs_restore_files() { # <dir> - byte objects, serialised with the config transaction (R04 round 3)
  # rpcd is reloaded in step2, so by the time a failed reinstall rolls back the panel is live
  # and can commit config.yaml through geomask-config-tx.py. This restore writes that very
  # file (cp) and then proves it: without the SAME kernel lock a live commit can land between
  # the copy and the verification (or be overwritten by an older snapshot), and the rollback
  # would report a state that no longer exists. Fail closed when the lock cannot be taken.
  if ! command -v gm_lock_acquire >/dev/null 2>&1; then
    bad "rollback: lock helper missing - refusing to restore config.yaml without serialisation"
    _rr=1
    return 1
  fi
  if ! gm_lock_acquire config-tx 30; then
    bad "rollback: config transaction lock is busy - refusing to restore config.yaml unlocked (retry after the live commit finishes)"
    _rr=1
    return 1
  fi
  _rs_rf_rc=0
  _rs_restore_files_unlocked "$@" || _rs_rf_rc=1
  # Verify the bytes while the lock is still held: no live commit can slip between the copy and
  # this check. The later _rs_restore_verify repeats it outside the lock on purpose - if a
  # writer changed the file after our restore, that verify must fail loudly.
  _rs_verify_files "$@" || { bad "rollback: byte objects do not match the snapshot while the transaction lock is held"; _rs_rf_rc=1; }
  gm_lock_release config-tx
  return $_rs_rf_rc
}

_rs_restore_files_unlocked() { # the byte restore itself; called only under config-tx
  [ -f "$_rs_snap/objects" ] || { bad "rollback: snapshot objects list missing"; return 1; }
  while IFS='|' read -r _rs_ok _rs_op _rs_oa _rs_ob _rs_oc _rs_od _rs_oe; do
    [ -n "${_rs_op:-}" ] || continue
    _rs_dst="$(P "$_rs_op")"
    if [ "$_rs_ok" = absent ]; then
      if ! _rs_safe_path "$(dirname "$_rs_op")"; then
        bad "conflict: a path component of $_rs_op is an unsafe or unpinned symlink"
        _rr=1
        continue
      fi
    elif [ "$_rs_ok" = file ]; then
      if ! _rs_safe_file "$_rs_op"; then
        bad "conflict: $_rs_op is a symlink (byte object; refusing to restore through it)"
        _rr=1
        continue
      fi
    else
      if ! _rs_safe_path "$_rs_op"; then
        bad "conflict: $_rs_op (or a parent) is an unsafe or unpinned symlink"
        _rr=1
        continue
      fi
    fi
    case "$_rs_ok" in
      file)
        if [ ! -f "$_rs_snap/files$_rs_op" ]; then
          bad "rollback: snapshot has no copy of $_rs_op"
          _rr=1
          continue
        fi
        if [ -L "$_rs_dst" ] || { [ -e "$_rs_dst" ] && [ ! -f "$_rs_dst" ]; }; then
          bad "rollback: $_rs_op is not a regular file any more - refusing to overwrite"
          _rr=1
          continue
        fi
        mkdir -p "$(dirname "$_rs_dst")" 2>/dev/null \
          || { bad "rollback: cannot create the directory of $_rs_op"; _rr=1; continue; }
        cp -p "$_rs_snap/files$_rs_op" "$_rs_dst" 2>/dev/null \
          || { bad "rollback: copy failed for $_rs_op"; _rr=1; continue; }
        chmod "$_rs_oa" "$_rs_dst" 2>/dev/null \
          || { bad "rollback: chmod $_rs_oa failed for $_rs_op"; _rr=1; continue; }
        ;;
      dirlink)
        if [ ! -L "$_rs_dst" ] || [ ! -d "$_rs_dst" ]; then
          bad "conflict: $_rs_op is no longer the pinned symlinked directory"
          _rr=1
          continue
        fi
        _rs_lh=$(readlink -f "$_rs_dst" 2>/dev/null) || _rs_lh=""
        _rs_lr=$(_rs_posix_path "$_rs_lh")
        _rs_ld=$(_rs_devino "$_rs_lh" 2>/dev/null) || _rs_ld=""
        if [ "$_rs_lr" != "$_rs_od" ] || [ "$_rs_ld" != "$_rs_oc" ]; then
          bad "conflict: target of $_rs_op changed after the snapshot - refusing to restore through it"
          _rr=1
          continue
        fi
        chmod "$_rs_oa" "$_rs_dst" 2>/dev/null \
          || { bad "rollback: chmod $_rs_oa failed for symlinked directory $_rs_op"; _rr=1; }
        ;;
      dir)
        if [ -L "$_rs_dst" ]; then
          bad "conflict: $_rs_op is a symlink to a directory - refusing to restore through it"
          _rr=1
          continue
        fi
        if [ -e "$_rs_dst" ] && [ ! -d "$_rs_dst" ]; then
          bad "rollback: $_rs_op is not a directory any more - refusing to replace"
          _rr=1
          continue
        fi
        mkdir -p "$_rs_dst" 2>/dev/null \
          || { bad "rollback: cannot recreate directory $_rs_op"; _rr=1; continue; }
        chmod "$_rs_oa" "$_rs_dst" 2>/dev/null \
          || { bad "rollback: chmod $_rs_oa failed for directory $_rs_op"; _rr=1; }
        ;;
      absent)
        if [ -d "$_rs_dst" ] && [ ! -L "$_rs_dst" ]; then
          if [ "$_rs_op" = "/root/geomask-backups" ]; then
            _rs_left=$(ls -A "$_rs_dst" 2>/dev/null | grep -v '^router-backup-' || true)
            if [ -z "$_rs_left" ]; then
              rmdir "$_rs_dst" 2>/dev/null \
                || { bad "rollback: cannot remove directory $_rs_op"; _rr=1; }
            else
              _rs_note "$_rs_op contains non-evidence files - directory kept"
            fi
          else
            rmdir "$_rs_dst" 2>/dev/null \
              || { bad "rollback: directory $_rs_op did not exist before the run and is not empty"; _rr=1; }
          fi
          continue
        fi
        rm -f "$_rs_dst" 2>/dev/null \
          || { bad "rollback: cannot remove $_rs_op (it did not exist before the run)"; _rr=1; }
        ;;
      shared|norestore|norestore-absent)
        : ;;   # shared files by _rs_restore_shared; NR state is never overwritten
    esac
  done < "$_rs_snap/objects"
  return 0
}

_rs_prune_temps() { # _rs_prune_temps <dir> - only temp/backup names this transaction created
  _rs_tl="$_rs_snap/listing"
  [ -f "$_rs_tl" ] || return 0
  while IFS='|' read -r _rs_ok _rs_op _rs_oa _rs_ob _rs_oc _rs_od _rs_oe; do
    [ -n "${_rs_op:-}" ] || continue
    case "$_rs_ok" in
      file|absent|shared|norestore|norestore-absent)
        if ! _rs_safe_path "$(dirname "$_rs_op")"; then continue; fi
        for _rs_sfx in ${REINSTALL_TEMP_SUFFIXES:-}; do
          _rs_cand="$_rs_op$_rs_sfx"
          [ -e "$(P "$_rs_cand")" ] || continue
          _rs_in_list "$_rs_snap" "$_rs_cand" && continue
          rm -f "$(P "$_rs_cand")" 2>/dev/null \
            || { bad "rollback: cannot remove our temporary $_rs_cand"; _rr=1; }
        done
        # Per-PID names: same rule, matched as a glob instead of an exact suffix.
        for _rs_glob in ${REINSTALL_TEMP_GLOBS:-}; do
          for _rs_cand in "$(P "$_rs_op")"$_rs_glob; do
            [ -e "$_rs_cand" ] || continue
            _rs_rel=${_rs_cand#"$GM_PREFIX"}
            _rs_in_list "$_rs_snap" "$_rs_rel" && continue
            rm -f "$_rs_cand" 2>/dev/null \
              || { bad "rollback: cannot remove our temporary $_rs_rel"; _rr=1; }
          done
        done
        for _rs_cand in "$(P "$_rs_op")".bak_geomask_* "$(P "$_rs_op")".pre-run-*; do
          [ -e "$_rs_cand" ] || continue
          _rs_rel=${_rs_cand#"$GM_PREFIX"}
          _rs_in_list "$_rs_snap" "$_rs_rel" && continue
          rm -f "$_rs_cand" 2>/dev/null \
            || { bad "rollback: cannot remove our backup $_rs_rel"; _rr=1; }
        done
        ;;
    esac
  done < "$_rs_snap/objects"
  # UCI config files are not byte objects, so their backups need their own scan:
  # geo-backend's `network.bak_v6off_*` is created by the IPv6 branch of the run.
  for _rs_ucp in network dhcp ksmbd firewall; do
    if ! _rs_safe_path "/etc/config/$_rs_ucp"; then continue; fi
    for _rs_cand in "$(P "/etc/config/$_rs_ucp")".bak_v6off_*; do
      [ -e "$_rs_cand" ] || continue
      _rs_rel=${_rs_cand#"$GM_PREFIX"}
      _rs_in_list "$_rs_snap" "$_rs_rel" && continue
      rm -f "$_rs_cand" 2>/dev/null \
        || { bad "rollback: cannot remove our backup $_rs_rel"; _rr=1; }
    done
  done
  return 0
}

_rs_restore_shared() { # _rs_restore_shared <dir> - managed subset only, conflicts refuse
  [ -f "$_rs_snap/shared" ] || return 0
  while IFS='|' read -r _rs_sc _rs_sp _rs_si _rs_sk _rs_sh _rs_sd _rs_sm; do
    [ -n "${_rs_sp:-}" ] || continue
    _rs_sa="$(P "$_rs_sp")"
    if [ "$_rs_sk" = regular ] && ! _rs_safe_file "$_rs_sp"; then
      bad "rollback: $_rs_sp is a symlink (byte file; refusing to restore through it)"
      _rr=1
      continue
    fi
    if [ "$_rs_sk" = absent ]; then
      # A router without zapret legitimately has no such file: absent -> absent is fine.
      # Only a file that APPEARED after the snapshot is not restorable (its writer may be us).
      if [ -e "$_rs_sa" ] || [ -L "$_rs_sa" ]; then
        bad "rollback: shared object $_rs_sp did not exist before the run and appeared since - not restorable"
        _rr=1
      fi
      continue
    fi
    if [ -L "$_rs_sa" ]; then
      bad "conflict: $_rs_sp is a symlink now - refusing to write through it"
      _rr=1
      continue
    fi
    if ! _rs_safe_file "$_rs_sp"; then
      bad "conflict: $_rs_sp is a symlink (byte file) - refusing to write through it"
      _rr=1
      continue
    fi
    _rs_pre="$_rs_snap/shared.$_rs_si.pre"
    if [ ! -f "$_rs_sa" ]; then
      bad "rollback: shared object $_rs_sp disappeared during the run"
      _rr=1
      continue
    fi
    if [ ! -f "$_rs_pre" ]; then
      bad "rollback incomplete / recovery required: snapshot lost the managed preimage of $_rs_sp"
      _rr=1
      continue
    fi
    if [ "$_rs_sc" = dnsai ]; then
      _rs_nd=$(_rs_devino "$_rs_sa") || _rs_nd=""
      if [ -n "${_rs_nd:-}" ] && [ "$_rs_nd" != "$_rs_sd" ]; then
        bad "conflict: $_rs_sp was replaced after the snapshot - not touching it"
        _rr=1
        continue
      fi
    fi
    _rs_nh=$(_rs_shared_neutral "$_rs_sc" "$_rs_sa" | _rs_hash_stream) || _rs_nh=""
    if [ "$_rs_nh" != "$_rs_sh" ]; then
      bad "conflict: foreign change in $_rs_sp - not overwriting (snapshot kept)"
      _rr=1
      continue
    fi
    # mktemp, not a predictable name: a planted <file>.rsnew symlink used to redirect the
    # rebuilt bytes outside the restored file (review 16.11, item 4).
    _rs_new=$(mktemp "$_rs_sa.rsnew.XXXXXX" 2>/dev/null)
    if [ -z "${_rs_new:-}" ]; then
      bad "rollback: cannot create a rebuild temp for $_rs_sp"
      _rr=1
      continue
    fi
    case "$_rs_sc" in
      dnsai)
        awk -v u="$AIDNS_USER" 'index($0, u ":") != 1' "$_rs_sa" > "$_rs_new" 2>/dev/null \
          || { bad "rollback: cannot rebuild $_rs_sp"; rm -f "$_rs_new"; _rr=1; continue; }
        cat "$_rs_pre" >> "$_rs_new" 2>/dev/null || true ;;
      zapret-block)
        awk -v b='# >>> geomask sync: tunneled domains (generated) >>>' \
            -v e="# <<< geomask sync: tunneled domains <<<" '
          $0 == b { skip = 1; next }
          $0 == e { skip = 0; next }
          !skip { print }' "$_rs_sa" > "$_rs_new" 2>/dev/null \
          || { bad "rollback: cannot rebuild $_rs_sp"; rm -f "$_rs_new"; _rr=1; continue; }
        cat "$_rs_pre" >> "$_rs_new" 2>/dev/null || true ;;
      zapret-force)
        awk -v m='# geomask: tunneled, DPI removed' -v pre="$_rs_pre" '
          BEGIN {
            while ((getline line < pre) > 0) {
              st = substr(line, 1, 1); d = substr(line, 3)
              if (d != "") want[d] = st
            }
          }
          {
            if (index($0, m) == 1) {
              d = substr($0, length(m) + 2)
              if (want[d] == "A") { print d; next }      # managed -> must be active again
              print; next
            }
            if ($0 != "" && $0 !~ /^#/) {
              if (want[$0] == "M") { print m " " $0; next }  # active -> must be managed again
            }
            print
          }' "$_rs_sa" > "$_rs_new" 2>/dev/null \
          || { bad "rollback: cannot rebuild $_rs_sp"; rm -f "$_rs_new"; _rr=1; continue; } ;;
    esac
    chmod "$_rs_sm" "$_rs_new" 2>/dev/null \
      || { bad "rollback: chmod $_rs_sm failed for $_rs_sp"; _rr=1; }
    mv -f "$_rs_new" "$_rs_sa" 2>/dev/null \
      || { bad "rollback: cannot install the rebuilt $_rs_sp"; rm -f "$_rs_new"; _rr=1; continue; }
  done < "$_rs_snap/shared"
  return 0
}

_rs_restore_uci() { # _rs_restore_uci <dir> - only our keys, only when no foreign delta
  for _rs_up in network dhcp ksmbd; do
    if [ -f "$(P "/tmp/.uci/$_rs_up")" ]; then
      bad "conflict: pending uci delta for $_rs_up appeared after the snapshot - not committing"
      _rr=1
      return 1
    fi
  done
  [ -f "$_rs_snap/uci" ] || return 0
  for _rs_ucf in network dhcp ksmbd; do
    if ! _rs_safe_path "/etc/config/$_rs_ucf"; then
      bad "conflict: /etc/config/$_rs_ucf is behind a symlink - refusing uci writes"
      _rr=1
      return 1
    fi
  done
  _rs_ty=$(sed -n 's/^uci|network|lanai|@type|//p' "$_rs_snap/uci" 2>/dev/null | head -1)
  if [ -n "${_rs_ty:-}" ]; then
    if [ "$_rs_ty" = '<absent>' ]; then
      if uci -q get network.lanai >/dev/null 2>&1; then
        _rs_wip=$(uci -q get network.lanai.ipaddr 2>/dev/null)
        _rs_wdev=$(uci -q get network.lanai.device 2>/dev/null)
        printf '%s|%s\n' "$_rs_wdev" "$_rs_wip" > "$_rs_snap/alias.was" 2>/dev/null || true
        uci -q delete network.lanai 2>/dev/null \
          || { bad "rollback: cannot delete network.lanai"; _rr=1; }
        if [ -f "$(P "/tmp/.uci/network")" ]; then
          uci commit network 2>/dev/null \
            || { bad "rollback: uci commit network failed"; _rr=1; }
        fi
      fi
    else
      uci set "network.lanai=$_rs_ty" 2>/dev/null \
        || { bad "rollback: cannot set network.lanai type"; _rr=1; }
      for _rs_o in proto device ipaddr netmask; do
        grep -q "^uci|network|lanai|$_rs_o|" "$_rs_snap/uci" 2>/dev/null || continue
        _rs_v=$(sed -n "s/^uci|network|lanai|$_rs_o|//p" "$_rs_snap/uci" 2>/dev/null | head -1)
        if [ "$_rs_v" = '<absent>' ]; then
          uci -q delete "network.lanai.$_rs_o" 2>/dev/null || true
          continue
        fi
        case "$_rs_o" in
          proto) uci set network.lanai.proto="$_rs_v" 2>/dev/null || _rr=1 ;;
          device) uci set network.lanai.device="$_rs_v" 2>/dev/null || _rr=1 ;;
          ipaddr) uci set network.lanai.ipaddr="$_rs_v" 2>/dev/null || _rr=1 ;;
          netmask) uci set network.lanai.netmask="$_rs_v" 2>/dev/null || _rr=1 ;;
        esac
      done
      if [ -f "$(P "/tmp/.uci/network")" ]; then
        uci commit network 2>/dev/null \
          || { bad "rollback: uci commit network failed"; _rr=1; }
      fi
    fi
  fi
  if grep -q '^uci|network|lan|ip6assign|' "$_rs_snap/uci" 2>/dev/null; then
    _rs_v=$(sed -n 's/^uci|network|lan|ip6assign|//p' "$_rs_snap/uci" 2>/dev/null | head -1)
    if [ "$_rs_v" = '<absent>' ]; then
      uci -q delete network.lan.ip6assign 2>/dev/null || true
    else
      uci set network.lan.ip6assign="$_rs_v" 2>/dev/null \
        || { bad "rollback: cannot restore network.lan.ip6assign"; _rr=1; }
    fi
    if [ -f "$(P "/tmp/.uci/network")" ]; then
      uci commit network 2>/dev/null \
        || { bad "rollback: uci commit network failed"; _rr=1; }
    fi
  fi
  for _k in ra dhcpv6 ndp; do
    grep -q "^uci|dhcp|lan|$_k|" "$_rs_snap/uci" 2>/dev/null || continue
    _rs_v=$(sed -n "s/^uci|dhcp|lan|$_k|//p" "$_rs_snap/uci" 2>/dev/null | head -1)
    if [ "$_rs_v" = '<absent>' ]; then
      uci -q delete "dhcp.lan.$_k" 2>/dev/null || true
    else
      uci set "dhcp.lan.$_k=$_rs_v" 2>/dev/null \
        || { bad "rollback: cannot restore dhcp.lan.$_k"; _rr=1; }
    fi
  done
  if [ -f "$(P "/tmp/.uci/dhcp")" ]; then
    uci commit dhcp 2>/dev/null \
      || { bad "rollback: uci commit dhcp failed"; _rr=1; }
  fi
  # ksmbd: compare the semantic signature first. If nothing changed, leave the sections
  # (and their anonymous ids) alone; a recreate would reorder/drop owner options.
  _rs_want_sig=$(_rs_ksmbd_snap_sig)
  _rs_now_sig=$(_rs_ksmbd_live_sig)
  if [ "$_rs_want_sig" != "$_rs_now_sig" ]; then
    _rs_guard=0
    while [ "$_rs_guard" -lt 50 ]; do
      _drop=$(_rs_ksmbd_ours geomask-backups | tail -1)
      [ -n "${_drop:-}" ] || break
      uci delete "$_drop" 2>/dev/null \
        || { bad "rollback: cannot delete our ksmbd share section"; _rr=1; break; }
      _rs_guard=$((_rs_guard+1))
    done
    _rs_kids=$(sed -n 's/^uci|ksmbd|\(@match[0-9]*\)|@type|share$/\1/p' "$_rs_snap/uci" 2>/dev/null | sort -u)
    for _rs_kid in $_rs_kids; do
      _sec=$(uci add ksmbd share 2>/dev/null)
      if [ -z "${_sec:-}" ]; then
        bad "rollback: cannot recreate our ksmbd share section"
        _rr=1
        continue
      fi
      while IFS='|' read -r _rs_uk _rs_ug _rs_um _rs_uo _rs_uv; do
        [ "$_rs_uk" = uci ] || continue
        [ "$_rs_ug" = ksmbd ] || continue
        [ "$_rs_um" = "$_rs_kid" ] || continue
        [ "$_rs_uo" = "@type" ] && continue
        uci set "ksmbd.$_sec.$_rs_uo=$_rs_uv" 2>/dev/null \
          || { bad "rollback: cannot set ksmbd.$_rs_uo"; _rr=1; }
      done < "$_rs_snap/uci"
    done
    if [ -f "$(P "/tmp/.uci/ksmbd")" ]; then
      uci commit ksmbd 2>/dev/null \
        || { bad "rollback: uci commit ksmbd failed"; _rr=1; }
    fi
  fi
  return 0
}

_rs_verify_alias() { # _rs_verify_alias <present|absent> <dev> <ip>
  [ -n "${1:-}" ] || return 0
  if [ "$1" = present ]; then
    [ "$(uci -q get network.lanai.ipaddr 2>/dev/null)" = "$3" ] || return 1
    [ -n "${2:-}" ] || return 1
    ip -4 addr show "$2" 2>/dev/null | grep -q " $3/" || return 1
    return 0
  fi
  uci -q get network.lanai >/dev/null 2>&1 && return 1
  if [ -n "${3:-}" ] && [ -n "${2:-}" ]; then
    ip -4 addr show "$2" 2>/dev/null | grep -q " $3/" && return 1
  fi
  return 0
}

_rs_restore_network() { # _rs_restore_network <dir> - netifd reload + alias confirmation
  _rs_aw=""; _rs_adev=""; _rs_aip=""
  while IFS='|' read -r _rs_nk _rs_nv _rs_nd _rs_ni; do
    [ "$_rs_nk" = alias ] || continue
    _rs_aw=$_rs_nv; _rs_adev=$_rs_nd; _rs_aip=$_rs_ni
  done < "$_rs_snap/net"
  if [ "$_rs_aw" = absent ] && [ -f "$_rs_snap/alias.was" ]; then
    IFS='|' read -r _rs_adev _rs_aip < "$_rs_snap/alias.was" || true
  fi
  if ! _rs_safe_exec /etc/init.d/network; then
    bad "conflict: /etc/init.d/network is behind an unsafe or unpinned symlink - refusing to reload network"
    _rr=1
    return 1
  fi
  initd network reload >/dev/null 2>&1 \
    || { bad "rollback: network reload failed - interfaces not confirmed"; _rr=1; return 1; }
  if ! _rs_verify_alias "$_rs_aw" "$_rs_adev" "$_rs_aip"; then
    _rs_settle
    initd network reload >/dev/null 2>&1 \
      || { bad "rollback: network reload failed (second attempt)"; _rr=1; return 1; }
    _rs_verify_alias "$_rs_aw" "$_rs_adev" "$_rs_aip" \
      || { bad "rollback: alias/interface state not confirmed"; _rr=1; return 1; }
  fi
  return 0
}

_rs_restore_firewall() { # <dir> - fw4 reload, nft table, our ip rule (pref+table)
  if ! _rs_safe_exec /etc/init.d/firewall; then
    bad "conflict: /etc/init.d/firewall is behind an unsafe or unpinned symlink - refusing to reload firewall"
    _rr=1
    return 1
  fi
  initd firewall reload >/dev/null 2>&1 \
    || { bad "rollback: firewall reload failed - nft state not applied"; _rr=1; }
  while IFS='|' read -r _rs_nk _rs_nv; do
    [ "$_rs_nk" = nft-ai ] || continue
    [ "$_rs_nv" = absent ] || continue
    if nft list table inet geomask_ai_dns >/dev/null 2>&1; then
      nft delete table inet geomask_ai_dns >/dev/null 2>&1 \
        || { bad "rollback: cannot delete nft table inet geomask_ai_dns"; _rr=1; }
    fi
  done < "$_rs_snap/net"
  while IFS= read -r _rs_nline; do
    [ -n "$_rs_nline" ] || continue
    _rs_nk=${_rs_nline%%|*}
    _rs_nv=${_rs_nline#*|}
    [ "$_rs_nk" = iprule ] || continue
    _rs_now=$(_rs_iprule_state) \
      || { bad "rollback: ip rule state unobservable"; _rr=1; continue; }
    [ "$_rs_nv" = "$_rs_now" ] && continue
    # Compare the WHOLE set of rules with our mark. Only the pref AIDNS_RULE_PREF is
    # ours; every other same-mark rule is foreign and is never modified. A foreign
    # change is a conflict, not something we silently overwrite.
    _rs_w_ours=""; _rs_w_for=""
    _rs_c_ours=""; _rs_c_for=""
    if [ "$_rs_nv" != absent ]; then
      for _rs_row in $(printf '%s' "$_rs_nv" | tr ';' ' '); do
        case "$_rs_row" in
          *"|ours") _rs_w_ours=$_rs_row ;;
          *) _rs_w_for="$_rs_w_for$_rs_row;" ;;
        esac
      done
    fi
    if [ "$_rs_now" != absent ]; then
      for _rs_row in $(printf '%s' "$_rs_now" | tr ';' ' '); do
        case "$_rs_row" in
          *"|ours") _rs_c_ours=$_rs_row ;;
          *) _rs_c_for="$_rs_c_for$_rs_row;" ;;
        esac
      done
    fi
    _rs_wp=""; _rs_wt=""
    if [ -n "$_rs_w_ours" ]; then
      _rs_wp=${_rs_w_ours%%|*}
      _rs_wrest=${_rs_w_ours#*|}
      _rs_wt=${_rs_wrest%%|*}
    fi
    _rs_cp=""; _rs_ct=""
    if [ -n "$_rs_c_ours" ]; then
      _rs_cp=${_rs_c_ours%%|*}
      _rs_crest=${_rs_c_ours#*|}
      _rs_ct=${_rs_crest%%|*}
    fi
    if [ -n "$_rs_c_ours" ] && { [ -z "$_rs_w_ours" ] || [ "$_rs_wt" != "$_rs_ct" ]; }; then
      ip rule del pref "$_rs_cp" fwmark "$AIDNS_MARK" table "$_rs_ct" >/dev/null 2>&1 \
        || { bad "rollback: cannot remove our ip rule (pref $_rs_cp table $_rs_ct)"; _rr=1; }
      _rs_c_ours=""
    fi
    if [ -n "$_rs_w_ours" ] && [ -z "$_rs_c_ours" ]; then
      ip rule add pref "$_rs_wp" fwmark "$AIDNS_MARK" table "$_rs_wt" >/dev/null 2>&1 \
        || { bad "rollback: cannot restore our ip rule (pref $_rs_wp table $_rs_wt)"; _rr=1; }
    fi
    if [ "$_rs_w_for" != "$_rs_c_for" ]; then
      bad "conflict: foreign ip rules with fwmark $AIDNS_MARK changed - not touching them"
      _rr=1
    fi
  done < "$_rs_snap/net"
  return 0
}

_rs_restore_sysctl() { # _rs_restore_sysctl <dir> - per-interface values, never a "0" default
  [ -f "$_rs_snap/sysctl" ] || return 0
  while IFS='|' read -r _rs_kk _rs_kn _rs_kv; do
    [ "$_rs_kk" = sysctl ] || continue
    _rs_kf="$(P "/proc/sys/net/ipv6/conf/$_rs_kn")"
    if ! _rs_safe_path "/proc/sys/net/ipv6/conf/$_rs_kn"; then
      bad "conflict: /proc/sys/net/ipv6/conf/$_rs_kn is behind a symlink - not writing sysctl"
      _rr=1
      continue
    fi
    if [ ! -d "$_rs_kf" ]; then
      bad "rollback: interface $_rs_kn disappeared - its disable_ipv6 is not restorable"
      _rr=1
      continue
    fi
    _rs_now=$(cat "$_rs_kf/disable_ipv6" 2>/dev/null | tr -dc '01')
    [ "$_rs_now" = "$_rs_kv" ] && continue
    sysctl -w "net.ipv6.conf.$_rs_kn.disable_ipv6=$_rs_kv" >/dev/null 2>&1 \
      || { bad "rollback: cannot write net.ipv6.conf.$_rs_kn.disable_ipv6"; _rr=1; }
  done < "$_rs_snap/sysctl"
  _rs_sf="$(P /etc/sysctl.d/99-disable-ipv6.conf)"
  if [ -f "$_rs_sf" ]; then
    if ! _rs_safe_path /etc/sysctl.d/99-disable-ipv6.conf; then
      bad "conflict: /etc/sysctl.d/99-disable-ipv6.conf is behind a symlink - refusing sysctl -p"
      _rr=1
      return 0
    fi
    sysctl -p "$_rs_sf" >/dev/null 2>&1 \
      || { bad "rollback: sysctl -p $_rs_sf failed"; _rr=1; }
  fi
  return 0
}

_rs_restore_links() { # <dir> - exact link names and targets
  _rs_rd="$(P /etc/rc.d)"
  if ! _rs_safe_path /etc/rc.d; then
    bad "conflict: /etc/rc.d is behind a symlink - refusing to write autostart links through it"
    _rr=1
    return 1
  fi
  if [ ! -d "$_rs_rd" ]; then
    bad "rollback: rc.d unobservable"
    _rr=1
    return 1
  fi
  for _rs_l in "$_rs_rd"/[SK][0-9][0-9]*; do
    [ -L "$_rs_l" ] || continue
    _rs_n=${_rs_l##*/}
    _rs_svc=${_rs_n#[SK]}
    _rs_svc=${_rs_svc#??}
    _rs_link_owned "$_rs_svc" || continue
    grep -q "^$_rs_n|" "$_rs_snap/links" 2>/dev/null && continue
    rm -f "$_rs_l" 2>/dev/null \
      || { bad "rollback: cannot remove the autostart link $_rs_n created by the run"; _rr=1; }
  done
  while IFS='|' read -r _rs_n _rs_t; do
    [ -n "${_rs_n:-}" ] || continue
    _rs_l="$_rs_rd/$_rs_n"
    if [ -L "$_rs_l" ] && [ "$(readlink "$_rs_l" 2>/dev/null)" = "$_rs_t" ]; then
      continue
    fi
    rm -f "$_rs_l" 2>/dev/null \
      || { bad "rollback: cannot replace the autostart link $_rs_n"; _rr=1; continue; }
    ln -s "$_rs_t" "$_rs_l" 2>/dev/null \
      || { bad "rollback: cannot recreate the autostart link $_rs_n -> $_rs_t"; _rr=1; }
  done < "$_rs_snap/links"
  return 0
}

_rs_restore_services() { # _rs_restore_services <dir> - back to the recorded running state
  [ -f "$_rs_snap/services" ] || return 0
  while IFS='|' read -r _rs_id _rs_initd _rs_pid _rs_mode _rs_en _rs_run; do
    [ -n "${_rs_id:-}" ] || continue
    _rs_now=$(_rs_svc_running "$_rs_pid" "$_rs_mode")
    case "$_rs_run" in
      1)
        if [ "$_rs_now" != 1 ]; then
          _rs_start_service "$_rs_initd" \
            || { bad "rollback: cannot start $_rs_id (it was running before the run)"; _rr=1; }
        fi ;;
      0)
        if [ "$_rs_now" = 1 ]; then
          _rs_stop_service "$_rs_initd" \
            || { bad "rollback: cannot stop $_rs_id (it was stopped before the run)"; _rr=1; }
        fi ;;
      *)
        bad "rollback: snapshot recorded an unknown running state for $_rs_id"
        _rr=1 ;;
    esac
  done < "$_rs_snap/services"
  return 0
}

_rs_restore_cron() { # _rs_restore_cron <dir> - exact crontab, foreign lines are a conflict
  # I03/I04 (audit 18.11.2026): the read, the foreign-line comparison and the write must all
  # happen under the same kernel `cron` lock. The old version compared before taking it, so a
  # panel write between the compare and the restore was silently overwritten; it also wrote
  # the snapshot even when the lock could not be taken.
  _cron_begin || {
    bad "rollback: crontab lock unavailable - not overwriting"
    _rr=1
    return 1
  }
  _rs_cur=$(crontab -l 2>/dev/null)
  _rs_cr=$?
  case "$_rs_cr" in
    0|1) : ;;
    *) _cron_end; bad "rollback: crontab state unobservable (rc=$_rs_cr)"; _rr=1; return 1 ;;
  esac
  _rs_want=$(cat "$_rs_snap/cron" 2>/dev/null)
  _rs_re='# geomask-(guard|ytwatch|ytwatch-reset|doctor-prune|vpnwatch|nodescan|audit-schedule)|sync_mtrickle_mihomo|geomask-node-scan'
  _rs_p1=$(printf '%s\n' "$_rs_cur" | grep -vE "$_rs_re" 2>/dev/null)
  _rs_p2=$(printf '%s\n' "$_rs_want" | grep -vE "$_rs_re" 2>/dev/null)
  if [ "$_rs_p1" != "$_rs_p2" ]; then
    _cron_end
    bad "conflict: crontab changed by another writer after the snapshot - not overwriting"
    _rr=1
    return 1
  fi
  crontab "$_rs_snap/cron" 2>/dev/null \
    || { _cron_end; bad "rollback: crontab write failed"; _rr=1; return 1; }
  _cron_end
  _rs_after=$(crontab -l 2>/dev/null)
  if [ "$_rs_after" != "$_rs_want" ]; then
    bad "rollback: crontab did not verify (silent write failure?)"
    _rr=1
    return 1
  fi
  return 0
}

_rs_verify_files() { # _rs_verify_files <dir>
  # Honour the argument every caller already passes: relying on a global _rs_snap silently
  # verified "whatever snapshot was set last" when a test or a future caller pointed elsewhere.
  _rs_snap=${1:-$_rs_snap}
  [ -f "$_rs_snap/objects" ] || return 1
  _rs_vr=0
  while IFS='|' read -r _rs_ok _rs_op _rs_oa _rs_ob _rs_oc _rs_od _rs_oe; do
    [ -n "${_rs_op:-}" ] || continue
    _rs_dst="$(P "$_rs_op")"
    case "$_rs_ok" in
      file)
        if ! _rs_safe_file "$_rs_op"; then
          bad "verify: $_rs_op is a symlink (byte object)"
          _rs_vr=1
          continue
        fi ;;
      dir|dirlink)
        if ! _rs_safe_path "$_rs_op"; then
          bad "verify: $_rs_op (or a parent) is an unsafe or unpinned symlink"
          _rs_vr=1
          continue
        fi ;;
      absent)
        if ! _rs_safe_path "$(dirname "$_rs_op")"; then
          bad "verify: a path component of $_rs_op is an unsafe or unpinned symlink"
          _rs_vr=1
          continue
        fi ;;
    esac
    case "$_rs_ok" in
      file)
        if [ ! -f "$_rs_snap/files$_rs_op" ]; then
          bad "verify: no snapshot copy of $_rs_op"
          _rs_vr=1
          continue
        fi
        if [ -L "$_rs_dst" ]; then
          bad "verify: $_rs_op is a symlink, expected the restored regular file"
          _rs_vr=1
          continue
        fi
        if ! cmp -s "$_rs_snap/files$_rs_op" "$_rs_dst" 2>/dev/null; then
          bad "verify: $_rs_op does not match the snapshot bytes"
          _rs_vr=1
        fi
        _rs_nowm=$(_rs_mode "$_rs_dst" 2>/dev/null) || _rs_nowm=""
        if [ "$_rs_nowm" != "$_rs_oa" ]; then
          bad "verify: mode of $_rs_op is ${_rs_nowm:-unknown}, expected $_rs_oa"
          _rs_vr=1
        fi ;;
      dirlink)
        if [ ! -L "$_rs_dst" ] || [ ! -d "$_rs_dst" ]; then
          bad "verify: $_rs_op is not the pinned symlinked directory"
          _rs_vr=1
        else
          _rs_lh=$(readlink -f "$_rs_dst" 2>/dev/null) || _rs_lh=""
          _rs_lr=$(_rs_posix_path "$_rs_lh")
          _rs_ld=$(_rs_devino "$_rs_lh" 2>/dev/null) || _rs_ld=""
          if [ "$_rs_lr" != "$_rs_od" ] || [ "$_rs_ld" != "$_rs_oc" ]; then
            bad "verify: target of $_rs_op changed after the snapshot"
            _rs_vr=1
          fi
        fi ;;
      dir)
        if [ -L "$_rs_dst" ]; then
          bad "verify: $_rs_op is a symlink, expected the restored directory"
          _rs_vr=1
        elif [ ! -d "$_rs_dst" ]; then
          bad "verify: directory $_rs_op is missing"
          _rs_vr=1
        fi ;;
      absent)
        if [ -e "$_rs_dst" ] || [ -L "$_rs_dst" ]; then
          bad "verify: $_rs_op did not exist before the run but is still present"
          _rs_vr=1
        fi ;;
      norestore)
        if [ ! -f "$_rs_dst" ]; then
          bad "verify: NR object $_rs_op disappeared during the run - not restorable"
          _rs_vr=1
        else
          _rs_nowh=$(_rs_hash "$_rs_dst" 2>/dev/null) || _rs_nowh=""
          if [ "$_rs_nowh" != "$_rs_oe" ]; then
            bad "verify: NR state $_rs_op was rewritten by its owner and cannot be restored (MagiTrickle state changed) - rollback incomplete"
            _rs_vr=1
          fi
        fi ;;
      norestore-absent)
        if [ -e "$_rs_dst" ] || [ -L "$_rs_dst" ]; then
          bad "verify: NR object $_rs_op did not exist before the run; it was created by the seeder and is not restorable"
          _rs_vr=1
        fi ;;
    esac
  done < "$_rs_snap/objects"
  [ "$_rs_vr" = 0 ]
}

_rs_verify_shared() { # _rs_verify_shared <dir>
  [ -f "$_rs_snap/shared" ] || return 0
  _rs_vr=0
  while IFS='|' read -r _rs_sc _rs_sp _rs_si _rs_sk _rs_sh _rs_sd _rs_sm; do
    [ -n "${_rs_sp:-}" ] || continue
    _rs_sa="$(P "$_rs_sp")"
    if [ "$_rs_sk" = absent ]; then
      if ! _rs_safe_path "$(dirname "$_rs_sp")"; then
        bad "verify: a path component of $_rs_sp is an unsafe or unpinned symlink"
        _rs_vr=1
        continue
      fi
      if [ -e "$_rs_sa" ] || [ -L "$_rs_sa" ]; then
        bad "verify: $_rs_sp did not exist before the run but is present now"
        _rs_vr=1
      fi
      continue
    fi
    if ! _rs_safe_file "$_rs_sp"; then
      bad "verify: $_rs_sp is a symlink or an unsafe/unpinned path"
      _rs_vr=1
      continue
    fi
    if [ -L "$_rs_sa" ]; then
      bad "verify: $_rs_sp is a symlink"
      _rs_vr=1
      continue
    fi
    _rs_pre="$_rs_snap/shared.$_rs_si.pre"
    if [ ! -f "$_rs_pre" ]; then
      bad "verify: snapshot lost the managed preimage of $_rs_sp"
      _rs_vr=1
      continue
    fi
    _rs_nh=$(_rs_shared_neutral "$_rs_sc" "$_rs_sa" 2>/dev/null | _rs_hash_stream) || _rs_nh=""
    if [ "$_rs_nh" != "$_rs_sh" ]; then
      bad "verify: foreign part of $_rs_sp differs from the snapshot"
      _rs_vr=1
    fi
    _rs_nowm=$(_rs_mode "$_rs_sa" 2>/dev/null) || _rs_nowm=""
    if [ "$_rs_nowm" != "$_rs_sm" ]; then
      bad "verify: mode of $_rs_sp is ${_rs_nowm:-unknown}, expected $_rs_sm"
      _rs_vr=1
    fi
    case "$_rs_sc" in
      dnsai)
        _rs_got=$(grep -E "^$AIDNS_USER:" "$_rs_sa" 2>/dev/null | sort)
        _rs_exp=$(sort "$_rs_pre" 2>/dev/null)
        if [ "$_rs_got" != "$_rs_exp" ]; then
          bad "verify: $AIDNS_USER lines in $_rs_sp do not match the snapshot"
          _rs_vr=1
        fi ;;
      zapret-block)
        _rs_got=$(awk -v b='# >>> geomask sync: tunneled domains (generated) >>>' \
                     -v e="# <<< geomask sync: tunneled domains <<<" '
          $0 == b { inb = 1 }
          inb { print }
          $0 == e { inb = 0 }' "$_rs_sa" 2>/dev/null | sort)
        _rs_exp=$(sort "$_rs_pre" 2>/dev/null)
        if [ "$_rs_got" != "$_rs_exp" ]; then
          bad "verify: managed block of $_rs_sp does not match the snapshot"
          _rs_vr=1
        fi ;;
      zapret-force)
        if ! awk -v m='# geomask: tunneled, DPI removed' -v pre="$_rs_pre" '
             BEGIN {
               while ((getline line < pre) > 0) {
                 st = substr(line, 1, 1); d = substr(line, 3)
                 if (d != "") want[d] = st
               }
             }
             {
               if (index($0, m) == 1) {
                 d = substr($0, length(m) + 2)
                 if (want[d] == "A") exit 1
                 seenM[d] = 1; next
               }
               if ($0 != "" && $0 !~ /^#/) {
                 if (want[$0] == "M") exit 1
                 seenA[$0] = 1
               }
             }
             END {
               for (d in want) {
                 if (want[d] == "A" && !(d in seenA)) exit 1
                 if (want[d] == "M" && !(d in seenM)) exit 1
               }
             }' "$_rs_sa" 2>/dev/null; then
          bad "verify: per-domain state of $_rs_sp does not match the snapshot"
          _rs_vr=1
        fi ;;
    esac
  done < "$_rs_snap/shared"
  [ "$_rs_vr" = 0 ]
}

_rs_verify_uci() { # _rs_verify_uci <dir>
  [ -f "$_rs_snap/uci" ] || return 0
  _rs_vr=0
  for _rs_up in network dhcp ksmbd; do
    if [ -f "$(P "/tmp/.uci/$_rs_up")" ]; then
      bad "verify: uci delta for $_rs_up is still pending - commit did not apply"
      _rs_vr=1
    fi
  done
  for _rs_ucf in network dhcp ksmbd; do
    if ! _rs_safe_path "/etc/config/$_rs_ucf"; then
      bad "verify: /etc/config/$_rs_ucf is behind a symlink - uci values not readable safely"
      return 1
    fi
  done
  while IFS='|' read -r _rs_uk _rs_pkg _rs_sec _rs_opt _rs_val; do
    [ "$_rs_uk" = uci ] || continue
    case "$_rs_sec" in
      @*) continue ;;   # @none / @matchN are journal markers, not live section names
    esac
    case "$_rs_opt" in
      @type)
        if [ "$_rs_val" = '<absent>' ]; then
          if uci -q get "$_rs_pkg.$_rs_sec" >/dev/null 2>&1; then
            bad "verify: $_rs_pkg.$_rs_sec did not exist before the run but is present"
            _rs_vr=1
          fi
        else
          _rs_got=$(uci -q get "$_rs_pkg.$_rs_sec" 2>/dev/null)
          if [ "$_rs_got" != "$_rs_val" ]; then
            bad "verify: type of $_rs_pkg.$_rs_sec is ${_rs_got:-missing}, expected $_rs_val"
            _rs_vr=1
          fi
        fi ;;
      *)
        _rs_got=$(uci -q get "$_rs_pkg.$_rs_sec.$_rs_opt" 2>/dev/null)
        _rs_grc=$?
        if [ "$_rs_val" = '<absent>' ]; then
          if [ "$_rs_grc" = 0 ]; then
            bad "verify: $_rs_pkg.$_rs_sec.$_rs_opt did not exist before the run but is present"
            _rs_vr=1
          fi
        elif [ "$_rs_got" != "$_rs_val" ]; then
          bad "verify: $_rs_pkg.$_rs_sec.$_rs_opt is ${_rs_got:-missing}, expected $_rs_val"
          _rs_vr=1
        fi ;;
    esac
  done < "$_rs_snap/uci"
  # ksmbd: sections are compared by their full option set (ids are not stable and the
  # preimage now includes force_root and every other option the owner had).
  _rs_want_sig=$(_rs_ksmbd_snap_sig)
  _rs_now_sig=$(_rs_ksmbd_live_sig)
  if [ "$_rs_want_sig" != "$_rs_now_sig" ]; then
    bad "verify: ksmbd share 'geomask-backups' does not match the snapshot"
    _rs_vr=1
  fi
  [ "$_rs_vr" = 0 ]
}

_rs_verify_sysctl() { # _rs_verify_sysctl <dir>
  [ -f "$_rs_snap/sysctl" ] || return 0
  _rs_vr=0
  while IFS='|' read -r _rs_kk _rs_kn _rs_kv; do
    [ "$_rs_kk" = sysctl ] || continue
    _rs_kf="$(P "/proc/sys/net/ipv6/conf/$_rs_kn")"
    if ! _rs_safe_path "/proc/sys/net/ipv6/conf/$_rs_kn"; then
      bad "verify: /proc/sys/net/ipv6/conf/$_rs_kn is an unsafe or unpinned symlink"
      _rs_vr=1
      continue
    fi
    if [ ! -d "$_rs_kf" ]; then
      bad "verify: interface $_rs_kn is gone"
      _rs_vr=1
      continue
    fi
    _rs_now=$(cat "$_rs_kf/disable_ipv6" 2>/dev/null | tr -dc '01')
    if [ "$_rs_now" != "$_rs_kv" ]; then
      bad "verify: net.ipv6.conf.$_rs_kn.disable_ipv6 is ${_rs_now:-unreadable}, expected $_rs_kv"
      _rs_vr=1
    fi
  done < "$_rs_snap/sysctl"
  [ "$_rs_vr" = 0 ]
}

_rs_nft_norm() { # <src> <dst> - canonical nft semantics (list or script form), counters ignored
  _rs_nft_out=$2
  _rs_nft_txt=$(awk '
    function trim(s) { sub(/^[ \t\r]+/, "", s); sub(/[ \t\r]+$/, "", s); return s }
    function norm(s) {
      sub(/\r/, "", s)
      gsub(/counter packets [0-9]+ bytes [0-9]+/, "counter", s)
      gsub(/packets [0-9]+ bytes [0-9]+/, "", s)
      gsub(/[ \t]+/, " ", s)
      sub(/^ /, "", s); sub(/ $/, "", s)
      gsub(/[ \t]*[{][ \t]*/, "{", s)
      gsub(/[ \t]*[}][ \t]*/, "}", s)
      gsub(/[ \t]*,[ \t]*/, ",", s)
      gsub(/[ \t]*;[ \t]*/, ";", s)
      sub(/;$/, "", s)
      return s
    }
    function addattrs(f, t, c, s,   n, a, i, part, sp, k, v) {
      n = split(s, a, ";")
      for (i = 1; i <= n; i++) {
        part = trim(a[i])
        if (part == "") continue
        sp = index(part, " ")
        if (sp > 0) { k = substr(part, 1, sp - 1); v = trim(substr(part, sp + 1)) }
        else { k = part; v = "" }
        attrs[f SUBSEP t SUBSEP c SUBSEP k] = v
      }
    }
    function clear_all(   k, n, ks, i) {
      n = 0; for (k in tables) ks[++n] = k
      for (i = 1; i <= n; i++) delete tables[ks[i]]
      n = 0; for (k in chains) ks[++n] = k
      for (i = 1; i <= n; i++) delete chains[ks[i]]
      n = 0; for (k in attrs) ks[++n] = k
      for (i = 1; i <= n; i++) delete attrs[ks[i]]
      n = 0; for (k in rules) ks[++n] = k
      for (i = 1; i <= n; i++) delete rules[ks[i]]
      n = 0; for (k in rcount) ks[++n] = k
      for (i = 1; i <= n; i++) delete rcount[ks[i]]
    }
    function clear_pref(pref,   k, n, ks, i) {
      n = 0; for (k in chains) if (index(k, pref) == 1) ks[++n] = k
      for (i = 1; i <= n; i++) delete chains[ks[i]]
      n = 0; for (k in attrs) if (index(k, pref) == 1) ks[++n] = k
      for (i = 1; i <= n; i++) delete attrs[ks[i]]
      n = 0; for (k in rules) if (index(k, pref) == 1) ks[++n] = k
      for (i = 1; i <= n; i++) delete rules[ks[i]]
      n = 0; for (k in rcount) if (index(k, pref) == 1) ks[++n] = k
      for (i = 1; i <= n; i++) delete rcount[ks[i]]
    }
    function add_rule(f, t, c, e,   key) {
      tables[f SUBSEP t] = 1
      chains[f SUBSEP t SUBSEP c] = 1
      key = f SUBSEP t SUBSEP c
      rcount[key]++
      rules[key SUBSEP sprintf("%05d", rcount[key])] = norm(e)
    }
    BEGIN { format = ""; ldepth = 0; lfam = ""; ltab = ""; lchain = ""; lattr = "" }
    {
      line = $0
      sub(/\r$/, "", line)
      s = trim(line)
      if (s == "" || s ~ /^#/) next
      if (format == "") {
        if (s ~ /^table[ \t]+[^ \t]+[ \t]+[^ \t{]+[ \t]+[{]/) format = "list"
        else if (s ~ /^(add|flush|delete|insert)[ \t]/) format = "script"
        else format = "raw"
      }
      if (format == "list") {
        if (s ~ /^table[ \t]/) {
          n = split(s, a, /[ \t]+/)
          lfam = a[2]; ltab = a[3]; sub(/[{;].*/, "", ltab)
          tables[lfam SUBSEP ltab] = 1
          ldepth = 1; lchain = ""; lattr = ""
          next
        }
        if (s ~ /^chain[ \t]/) {
          n = split(s, a, /[ \t]+/)
          lchain = a[2]; sub(/[{;].*/, "", lchain)
          chains[lfam SUBSEP ltab SUBSEP lchain] = 1
          ldepth = 2; lattr = ""
          next
        }
        if (s == "}") {
          if (ldepth >= 2) {
            if (lchain != "") { if (lattr != "") addattrs(lfam, ltab, lchain, lattr); lchain = "" }
            ldepth--
          } else if (ldepth == 1) { ldepth = 0 }
          next
        }
        if (ldepth == 1) {
          if (s ~ /^(set|map|flowtable|element|elements|counter|quota)[ \t]/) ldepth = 2
          print "raw|" lfam "|" ltab "|" norm(s)
          next
        }
        if (ldepth == 2 && lchain != "") {
          if (s ~ /^(type|policy|device|comment)[ \t]/) { lattr = lattr (lattr == "" ? "" : " ") s; next }
          add_rule(lfam, ltab, lchain, s)
          next
        }
        print "raw|" norm(s)
        next
      }
      if (format == "script") {
        n = split(s, a, /[ \t]+/)
        if (a[1] == "flush" && a[2] == "ruleset") { clear_all(); next }
        if (a[1] == "flush" && a[2] == "table") {
          fam = a[3]; tab = a[4]; sub(/[;].*/, "", tab)
          clear_pref(fam SUBSEP tab SUBSEP)
          tables[fam SUBSEP tab] = 1
          next
        }
        if (a[1] == "delete" && a[2] == "table") {
          fam = a[3]; tab = a[4]; sub(/[;].*/, "", tab)
          clear_pref(fam SUBSEP tab SUBSEP)
          delete tables[fam SUBSEP tab]
          next
        }
        if (a[1] == "delete" && a[2] == "chain") {
          fam = a[3]; tab = a[4]; name = a[5]; sub(/[;{].*/, "", name)
          clear_pref(fam SUBSEP tab SUBSEP name SUBSEP)
          delete chains[fam SUBSEP tab SUBSEP name]
          next
        }
        if (a[1] == "add" && a[2] == "table") {
          fam = a[3]; tab = a[4]; sub(/[;].*/, "", tab)
          tables[fam SUBSEP tab] = 1
          next
        }
        if (a[1] == "add" && a[2] == "chain") {
          fam = a[3]; tab = a[4]; name = a[5]; sub(/[;{].*/, "", name)
          chains[fam SUBSEP tab SUBSEP name] = 1
          if (index(s, "{") > 0) {
            rest = substr(s, index(s, "{") + 1)
            sub(/[}].*/, "", rest)
            addattrs(fam, tab, name, rest)
          }
          next
        }
        if (a[1] == "add" && a[2] == "rule") {
          fam = a[3]; tab = a[4]; name = a[5]
          rest = s
          sub(/^[a-z]+[ \t]+rule[ \t]+[^ \t]+[ \t]+[^ \t]+[ \t]+[^ \t]+[ \t]+/, "", rest)
          add_rule(fam, tab, name, rest)
          next
        }
        print "raw|" norm(s)
        next
      }
      print "raw|" norm(s)
    }
    END {
      for (k in tables) { split(k, p, SUBSEP); print "table|" p[1] "|" p[2] }
      for (k in chains) { split(k, p, SUBSEP); print "chain|" p[1] "|" p[2] "|" p[3] }
      for (k in attrs) { split(k, p, SUBSEP); print "attr|" p[1] "|" p[2] "|" p[3] "|" p[4] "|" attrs[k] }
      for (k in rules) { split(k, p, SUBSEP); print "rule|" p[1] "|" p[2] "|" p[3] "|" p[4] "|" rules[k] }
    }
  ' "$1" 2>/dev/null) || return 1
  printf '%s\n' "$_rs_nft_txt" | LC_ALL=C sort > "$_rs_nft_out" 2>/dev/null || return 1
}

_rs_verify_net() { # _rs_verify_net <dir>
  [ -f "$_rs_snap/net" ] || return 0
  _rs_vr=0
  _rs_aw=""; _rs_adev=""; _rs_aip=""
  while IFS= read -r _rs_nline; do
    [ -n "$_rs_nline" ] || continue
    _rs_nk=${_rs_nline%%|*}
    _rs_nrest=${_rs_nline#*|}
    case "$_rs_nk" in
      iprule)
        _rs_now=$(_rs_iprule_state)
        if [ "$_rs_now" != "$_rs_nrest" ]; then
          bad "verify: ip rule state is ${_rs_now:-unobservable}, expected $_rs_nrest"
          _rs_vr=1
        fi ;;
      nft-ai)
        _rs_nv=${_rs_nrest%%|*}
        if [ "$_rs_nv" = present ]; then
          if nft list table inet geomask_ai_dns > "$_rs_snap/nft-ai.now" 2>/dev/null; then
            _rs_nft_norm "$_rs_snap/nft-ai.list" "$_rs_snap/nft-ai.list.norm" \
              && _rs_nft_norm "$_rs_snap/nft-ai.now" "$_rs_snap/nft-ai.now.norm" \
              && cmp -s "$_rs_snap/nft-ai.list.norm" "$_rs_snap/nft-ai.now.norm" \
              || { bad "verify: nft table inet geomask_ai_dns structure differs from the snapshot"; _rs_vr=1; }
          else
            bad "verify: nft table inet geomask_ai_dns is missing"
            _rs_vr=1
          fi
        else
          if nft list table inet geomask_ai_dns >/dev/null 2>&1; then
            bad "verify: nft table inet geomask_ai_dns should be absent"
            _rs_vr=1
          fi
        fi ;;
      nft-v6)
        _rs_nv=${_rs_nrest%%|*}
        if [ "$_rs_nv" = present ]; then
          if nft list chain inet fw4 geomask_no_v6 > "$_rs_snap/nft-v6.now" 2>/dev/null; then
            _rs_nft_norm "$_rs_snap/nft-v6.list" "$_rs_snap/nft-v6.list.norm" \
              && _rs_nft_norm "$_rs_snap/nft-v6.now" "$_rs_snap/nft-v6.now.norm" \
              && cmp -s "$_rs_snap/nft-v6.list.norm" "$_rs_snap/nft-v6.now.norm" \
              || { bad "verify: nft chain inet fw4 geomask_no_v6 structure differs from the snapshot"; _rs_vr=1; }
          else
            bad "verify: nft chain inet fw4 geomask_no_v6 is missing"
            _rs_vr=1
          fi
        else
          if nft list chain inet fw4 geomask_no_v6 >/dev/null 2>&1; then
            bad "verify: nft chain inet fw4 geomask_no_v6 should be absent"
            _rs_vr=1
          fi
        fi ;;
      alias)
        _rs_aw=${_rs_nrest%%|*}
        _rs_atmp=${_rs_nrest#*|}
        _rs_adev=${_rs_atmp%%|*}; _rs_aip=${_rs_atmp#*|}
        [ "$_rs_aip" = "$_rs_atmp" ] && _rs_aip="" ;;
    esac
  done < "$_rs_snap/net"
  if [ "$_rs_aw" = absent ] && [ -f "$_rs_snap/alias.was" ]; then
    IFS='|' read -r _rs_adev _rs_aip < "$_rs_snap/alias.was" || true
  fi
  if ! _rs_verify_alias "$_rs_aw" "$_rs_adev" "$_rs_aip"; then
    bad "verify: alias/interface state does not match the snapshot"
    _rs_vr=1
  fi
  [ "$_rs_vr" = 0 ]
}

_rs_verify_runtime() { # _rs_verify_runtime <dir> - enabled AND running for every service
  [ -f "$_rs_snap/services" ] || return 0
  _rs_vr=0
  if ! _rs_safe_path /etc/rc.d || ! _rs_safe_path /etc/init.d; then
    bad "verify: /etc/rc.d or /etc/init.d is behind a symlink - runtime state unreadable safely"
    return 1
  fi
  while IFS='|' read -r _rs_id _rs_initd _rs_pid _rs_mode _rs_en _rs_run; do
    [ -n "${_rs_id:-}" ] || continue
    for _rs_is in $(printf '%s' "$_rs_initd" | tr '/' ' '); do
      if ! _rs_safe_exec "/etc/init.d/$_rs_is"; then
        bad "verify: init script /etc/init.d/$_rs_is is behind an unsafe or unpinned symlink"
        _rs_vr=1
      fi
    done
    _rs_now_en=$(_rs_svc_enabled "$_rs_initd")
    _rs_now_run=$(_rs_svc_running "$_rs_pid" "$_rs_mode")
    if [ "$_rs_now_en" != "$_rs_en" ]; then
      bad "verify: $_rs_id enabled=$_rs_now_en, expected $_rs_en"
      _rs_vr=1
    fi
    if [ "$_rs_now_run" != "$_rs_run" ]; then
      bad "verify: $_rs_id running=$_rs_now_run, expected $_rs_run"
      _rs_vr=1
    fi
  done < "$_rs_snap/services"
  if [ -f "$_rs_snap/links" ]; then
    while IFS='|' read -r _rs_n _rs_t; do
      [ -n "${_rs_n:-}" ] || continue
      _rs_l="$(P "/etc/rc.d/$_rs_n")"
      if [ ! -L "$_rs_l" ] || [ "$(readlink "$_rs_l" 2>/dev/null)" != "$_rs_t" ]; then
        bad "verify: autostart link $_rs_n -> $_rs_t is missing or has another target"
        _rs_vr=1
      fi
    done < "$_rs_snap/links"
  fi
  [ "$_rs_vr" = 0 ]
}

_rs_verify_cron() { # _rs_verify_cron <dir>
  _rs_want=$(cat "$_rs_snap/cron" 2>/dev/null)
  _rs_now=$(crontab -l 2>/dev/null)
  if [ "$_rs_now" != "$_rs_want" ]; then
    bad "verify: crontab does not match the snapshot"
    return 1
  fi
  return 0
}

_rs_nr_notes() { # _rs_nr_notes <dir> - honest NR list (they are not restored by design)
  _rs_note "MagiTrickle state is owned by magitrickled (NR): it is not overwritten, and a change makes the rollback incomplete"
  _rs_note "mihomo provider cache and the controller API refresh are network effects (not files)"
  _rs_note "network/firewall reload effects are verified as live state, not restored as files"
  _rs_note "witness logs (geo-sync.log, node-audit events/pools/reports) and /tmp transients are kept"
  return 0
}

_rs_restore_verify() { # _rs_restore_verify <dir> - the rollback is not trusted, it is verified
  _rs_vok=0
  # R04: the byte objects were written and proven under config-tx already. This second check
  # runs after that lock was released, so a live panel commit may legitimately (or not) change
  # config.yaml in between. A mismatch here is reported as a concurrent writer, not silently
  # accepted as "restored": the snapshot no longer describes the live file.
  _rs_verify_files || { _rs_vok=1; bad "rollback verification failed: file objects (a concurrent writer - e.g. a live config transaction - changed them after the serialised restore)"; }
  _rs_verify_shared || { _rs_vok=1; bad "rollback verification failed: shared files"; }
  _rs_verify_uci || { _rs_vok=1; bad "rollback verification failed: uci keys"; }
  _rs_verify_sysctl || { _rs_vok=1; bad "rollback verification failed: sysctl"; }
  _rs_verify_net || { _rs_vok=1; bad "rollback verification failed: net runtime"; }
  _rs_verify_runtime || { _rs_vok=1; bad "rollback verification failed: services/links"; }
  _rs_verify_cron || { _rs_vok=1; bad "rollback verification failed: crontab"; }
  if [ "$_rs_vok" != 0 ]; then
    bad "rollback verification failed: the restored state could not be confirmed"
    return 1
  fi
  return 0
}

_reinstall_restore() { # _reinstall_restore <dir> -> 0 only when the restored state is verified
  _rs_snap="$1"
  _rs_pin_mode=0
  _rs_pin_enforce=1
  _rr=0
  _rs_check_snapshot "$_rs_snap" || return 1
  if ! _rs_critical_paths_safe; then
    bad "rollback incomplete / recovery required: unsafe path (symlink component) - no writes, reloads or exec were attempted"
    return 1
  fi
  _rs_stop_new_services "$_rs_snap" || _rr=1
  _rs_restore_files "$_rs_snap" || _rr=1
  _rs_prune_temps "$_rs_snap" || _rr=1
  _rs_restore_shared "$_rs_snap" || _rr=1
  _rs_restore_uci "$_rs_snap" || _rr=1
  _rs_restore_network "$_rs_snap" || _rr=1
  _rs_restore_firewall "$_rs_snap" || _rr=1
  _rs_restore_sysctl "$_rs_snap" || _rr=1
  _rs_restore_links "$_rs_snap" || _rr=1
  _rs_restore_services "$_rs_snap" || _rr=1
  _rs_restore_cron "$_rs_snap" || _rr=1
  _rs_nr_notes "$_rs_snap" || _rr=1
  _rs_restore_verify "$_rs_snap" || _rr=1
  if [ "$_rr" = 0 ]; then
    info "откат проверен (verified rollback): файлы, UCI, сервисы и runtime соответствуют снимку"
    rm -rf "$_rs_snap" 2>/dev/null || true
  else
    bad "rollback incomplete / recovery required: снимок сохранён в $_rs_snap (не удаляйте его)"
  fi
  return $_rr
}

_reinstall_steps() { # _reinstall_steps <vpn-url> -> 0 only when every critical step succeeded
  _rvpn="$1"
  hdr "1/6" "удаление geomask"
  geomask_uninstall noreload || { bad "удаление не завершено"; return 1; }
  hdr "2/6" "гео-оверлей LuCI"
  step2_apply || { bad "файлы панели не записаны"; return 1; }
  step2_verify || { bad "проверка панели не пройдена"; return 1; }
  hdr "3/6" "mihomo: подписка + AI-USA"
  if write_mihomo_config "$_rvpn" ""; then
    api_refresh_provider sub "$_rvpn" && info "provider sub refreshed (no restart)" || warn "provider sub: refresh failed, применится при старте mihomo"
  else
    bad "конфиг mihomo не записан"
    return 1
  fi
  hdr "4/6" "AI-DNS (нет утечки DNS)"
  step4_apply || { bad "AI-DNS не настроен"; return 1; }
  step4_verify || { bad "проверка AI-DNS не пройдена"; return 1; }
  hdr "5/6" "синхронизация + роутинг"
  step5_apply || { bad "синхронизация не выполнена"; return 1; }
  step5_verify || { bad "проверка синхронизации не пройдена"; return 1; }
  hdr "6/6" "сервисы"
  step6_apply || { bad "сервисы не настроены"; return 1; }
  # The security baseline is part of a reinstall/update, not an optional extra: an update that
  # leaves IPv6 leaking is the same half-done repair the owner complained about elsewhere.
  # `--ipv6=keep` is the documented way out.
  hdr "IPv6" "выключение по умолчанию"
  apply_ipv6_default || { bad "IPv6 не выключен - переустановка отменена (--ipv6=keep, чтобы сохранить IPv6)"; return 1; }
  hdr "VERIFY" "итоговая проверка"
  step7_check || { bad "итоговая проверка не пройдена"; return 1; }
  info "verify: PASS"
  return 0
}

# ---- R03: package installs and the fail-closed reinstall preflight ------------
# Package installs are FORBIDDEN inside the reinstall path: the transaction promises a
# full rollback, and a package database plus post-install side effects cannot be rolled
# back by the file snapshot. The reinstall therefore never installs anything (including
# `apk add inotifywait` in step 5 - the sync watchdog falls back to a 10s poll); a missing
# dependency is a preflight REFUSAL, not an installation.
pkg_install() { # pkg_install <pkg>... -> 0 only when the package manager reports success
  if [ "${GM_REINSTALL_NO_PKG:-0}" = 1 ]; then
    warn "переустановка: автоустановка пакетов запрещена ($*) - зависимость должна быть установлена заранее"
    return 1
  fi
  if have apk; then
    info "installing: $* (apk)"
    apk update >/dev/null 2>&1 || warn "apk update failed - trying the current index"
    apk add "$@" >/dev/null 2>&1
  elif have opkg; then
    info "installing: $* (opkg)"
    opkg update >/dev/null 2>&1 || warn "opkg update failed - trying the current index"
    opkg install "$@" >/dev/null 2>&1
  else
    return 1
  fi
}

# The runtime objects of the reinstall write-set (tests/reinstall_write_set.json).
# Format: id|kind|f1|f2|f3 where kind decides the fields:
#   service  -> initd-name(s, '/'-separated) | pid-or-port | mode (pidof|pgrep|port)
#   crontab|links -> - | - | -
#   uci      -> probe key (uci -q get) | - | -
#   ip-rule  -> - | - | -
#   nft-table-> table spec | - | -
#   alias    -> uci key of the alias address | - | -
#   sysctl   -> /proc/sys/net/ipv6/conf | - | -
#   file|file-shared -> install path | expected (regular|regular-or-absent) | extra (seed-risk|-)
#   dirs     -> - | - | -      dir -> probe dir | - | -
# Tri-state enabled/running per service: enabled from /etc/rc.d links, running from
# pidof/pgrep/netstat. Any `unknown` is an ERROR, not a maybe.
REINSTALL_PREFLIGHT_OBJECTS="svc.dnsmasq|service|dnsmasq|dnsmasq|pidof
svc.mihomo|service|mihomo|mihomo|pidof
svc.magitrickle|service|magitrickle|magitrickled|pidof
svc.hev-socks5-tunnel|service|hev-socks5-tunnel|hev-socks5-tunnel|pidof
svc.hev-nop2p|service|hev-nop2p|hev-socks5-tunnel|pidof
svc.rpcd|service|rpcd|rpcd|pidof
svc.ai-doh|service|ai-doh|5055|port
svc.dnsmasq-ai|service|dnsmasq-ai|5353|port
svc.geomask-syncd|service|geomask-syncd|geomask-syncd.sh|pgrep
svc.network|service|network|netifd|pidof
svc.firewall|service|firewall|fw4|pidof
svc.ksmbd|service|ksmbd/ksmbd1|ksmbd|pidof
cron.user|crontab|-|-|-
rc.d|links|-|-|-
uci.network|uci|network.lan|-|-
uci.dhcp|uci|dhcp.lan|-|-
uci.ksmbd|uci|ksmbd|-|-
net.fwmark-rule|ip-rule|-|-|-
net.nft-ai-dns|nft-table|inet geomask_ai_dns|-|-
net.alias-lanai|alias|network.lanai.ipaddr|-|-
sysctl.kernel|sysctl|/proc/sys/net/ipv6/conf|-|-
file.passwd|file-shared|/etc/passwd|regular|-
file.group|file-shared|/etc/group|regular|-
shared.magitrickle-config|file-shared|/etc/magitrickle/state/config.yaml|regular-or-absent|seed-risk
shared.zapret-exclude|file-shared|/opt/zapret/ipset/zapret-hosts-user-exclude.txt|regular-or-absent|-
shared.zapret-force|file-shared|/opt/zapret/ipset/zapret-hosts-user.txt|regular-or-absent|-
file.mihomo-config|file|/etc/mihomo/config.yaml|regular-or-absent|-
dir.tracked|dirs|-|-|-
tmp.scratch|dir|/tmp|-|-"

# R03 phase 2a (review G): every write-set object whose snapshot stores BYTES
# (manifest snapshot SB/SBA/SAP - tests/reinstall_write_set.json). The preflight
# classifies each object's type before any mutation: a symlink would be followed by
# cp -p (it would capture and later restore the target's bytes), an unreadable file
# captures nothing - both are refusals. Format: install-path|expected with
# regular-or-absent or dir-or-absent. This table is cross-checked against the manifest
# by tests/reinstall_manifest.py (check_byte_table). Documented boundary (manifest
# meta.preflight_boundary): dynamic temp classes, snapshot=NONE transients and runtime
# effects without a file representation are not type-classified here.
REINSTALL_PREFLIGHT_BYTE_FILES="/usr/lib/geomask/geomask-node-audit.py|regular-or-absent
/usr/lib/geomask/geomask-audit-state.py|regular-or-absent
/usr/lib/geomask/geomask-config-tx.py|regular-or-absent
/usr/lib/geomask/geomask-config-owner.py|regular-or-absent
/usr/lib/geomask/geomask-apply.py|regular-or-absent
/usr/lib/geomask/geomask-lane-torrent.py|regular-or-absent
/usr/lib/geomask/geomask-sync-youtube.py|regular-or-absent
/usr/lib/geomask/geomask-audit-scheduler.py|regular-or-absent
/usr/lib/geomask/geomask-subscription-status.py|regular-or-absent
